package com.rootrecord.minecraft.rootessentials.explode;

import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.PlayerInventory;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.components.EquippableComponent;

/**
 * TNT can be worn in the chestplate slot (Paper equippable component).
 * {@code /explode} requires that vest and consumes it on confirm.
 */
public final class TntChestplate {

    private TntChestplate() {
    }

    public static boolean isWorn(Player player) {
        if (player == null) {
            return false;
        }
        ItemStack chest = player.getInventory().getChestplate();
        return isTnt(chest);
    }

    public static boolean consumeWorn(Player player) {
        if (!isWorn(player)) {
            return false;
        }
        player.getInventory().setChestplate(null);
        return true;
    }

    public static boolean isTnt(ItemStack stack) {
        return stack != null && stack.getType() == Material.TNT && stack.getAmount() > 0;
    }

    /** Stamp TNT so clients/servers allow it in the chest armor slot. */
    public static void makeWearable(ItemStack stack) {
        if (!isTnt(stack)) {
            return;
        }
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) {
            return;
        }
        if (meta.hasEquippable()) {
            EquippableComponent existing = meta.getEquippable();
            if (existing.getSlot() == EquipmentSlot.CHEST) {
                return;
            }
        }
        EquippableComponent equippable = meta.getEquippable();
        equippable.setSlot(EquipmentSlot.CHEST);
        equippable.setSwappable(true);
        equippable.setDispensable(true);
        meta.setEquippable(equippable);
        stack.setItemMeta(meta);
    }

    public static void stampInventory(Player player) {
        if (player == null) {
            return;
        }
        PlayerInventory inv = player.getInventory();
        ItemStack[] contents = inv.getContents();
        boolean changed = false;
        for (int i = 0; i < contents.length; i++) {
            ItemStack stack = contents[i];
            if (!isTnt(stack)) {
                continue;
            }
            makeWearable(stack);
            contents[i] = stack;
            changed = true;
        }
        if (changed) {
            inv.setContents(contents);
        }
        ItemStack chest = inv.getChestplate();
        if (isTnt(chest)) {
            makeWearable(chest);
            inv.setChestplate(chest);
        }
    }
}

package com.rootrecord.minecraft.rootessentials.explode;

import org.bukkit.Material;
import org.bukkit.entity.Item;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityPickupItemEvent;
import org.bukkit.event.inventory.CraftItemEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerRespawnEvent;
import org.bukkit.inventory.ItemStack;

/** Keeps TNT stacks stamped as wearable chestplates. */
public final class TntChestplateListener implements Listener {

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onJoin(PlayerJoinEvent event) {
        TntChestplate.stampInventory(event.getPlayer());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onRespawn(PlayerRespawnEvent event) {
        TntChestplate.stampInventory(event.getPlayer());
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPickup(EntityPickupItemEvent event) {
        if (!(event.getEntity() instanceof Player)) {
            return;
        }
        Item item = event.getItem();
        ItemStack stack = item.getItemStack();
        if (!TntChestplate.isTnt(stack)) {
            return;
        }
        TntChestplate.makeWearable(stack);
        item.setItemStack(stack);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onCraft(CraftItemEvent event) {
        ItemStack result = event.getCurrentItem();
        if (!TntChestplate.isTnt(result)) {
            return;
        }
        TntChestplate.makeWearable(result);
        event.setCurrentItem(result);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onClick(InventoryClickEvent event) {
        stamp(event.getCurrentItem());
        stamp(event.getCursor());
        if (event.getWhoClicked() instanceof Player player) {
            // Armor / hotbar moves can leave unstamped stacks; refresh after the click applies.
            player.getScheduler().run(player.getServer().getPluginManager().getPlugin("Root-Essentials"),
                    task -> TntChestplate.stampInventory(player), null);
        }
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onDrag(InventoryDragEvent event) {
        for (ItemStack stack : event.getNewItems().values()) {
            stamp(stack);
        }
        stamp(event.getOldCursor());
        stamp(event.getCursor());
    }

    private static void stamp(ItemStack stack) {
        if (stack == null || stack.getType() != Material.TNT) {
            return;
        }
        TntChestplate.makeWearable(stack);
    }
}

