$path = 'D:\.1 Work Stations\RootMC\docs\minecraft-26.2-spawn-eggs-power-ranking.md'
$raw = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
$rows = [regex]::Matches($raw, '(?m)^\| (\d+) \| (Spawn egg|Block|Enchanted book|RootMC|Potion|Armor trim) \| (.+) \|\s*$')
Write-Host "parsed $($rows.Count)"

$entries = [System.Collections.Generic.List[object]]::new()
foreach ($m in $rows) {
  $kind = $m.Groups[2].Value
  $rest = $m.Groups[3].Value
  $parts = $rest -split ' \| '
  if ($parts.Count -lt 3) { continue }
  $matCell = $parts[0].Trim()
  $nsCell = $parts[1].Trim()
  $nameCell = $parts[2].Trim(' ','*')
  $notes = if ($parts.Count -ge 4) { ($parts[3..($parts.Count-1)] -join ' | ').Trim() } else { '' }
  $type = switch ($kind) {
    'Spawn egg' { 'egg' }
    'Block' { 'block' }
    'Enchanted book' { 'book' }
    'RootMC' { 'rootmc' }
    'Potion' { 'potion' }
    'Armor trim' { 'trim' }
  }
  $mat = $null; $ns = $null; $qty = 1
  if ($type -eq 'egg') {
    if ($matCell -match '`([A-Z0-9_]+)`') { $mat = $Matches[1] }
    if ($nsCell -match '`([^`]+)`') { $ns = $Matches[1] }
  } elseif ($type -eq 'block' -or $type -eq 'trim') {
    if ($matCell -match '`([A-Z0-9_]+)`') { $mat = $Matches[1] }
    if ($nsCell -match '`([^`]+)`') { $ns = $Matches[1] }
  } elseif ($type -eq 'book') {
    if ($matCell -match 'Enchantment\.([A-Z0-9_]+)') { $mat = $Matches[1].ToLower() }
    $keys = [regex]::Matches($nsCell, 'minecraft:([a-z0-9_]+)')
    $ns = if ($keys.Count -ge 2) { "minecraft:$($keys[1].Groups[1].Value)" } else { "minecraft:$mat" }
  } elseif ($type -eq 'potion') {
    if ($matCell -match 'PotionType\.([A-Z0-9_]+)') { $mat = $Matches[1].ToLower() }
    $ns = "minecraft:potion{$mat}"
  } elseif ($type -eq 'rootmc') {
    $mat = 'Free Lotto Ticket'; $ns = 'rootmc:free_lotto_ticket'
  }
  $entries.Add([pscustomobject]@{Type=$type; Mat=$mat; Ns=$ns; Name=$nameCell; Notes=$notes; Qty=$qty})
}

