# 5) Update subsection overall ranks by namespaced / material match
function Update-SectionRanks([System.Collections.Generic.List[string]]$ls, [string]$heading, [scriptblock]$resolver) {
  $s = -1
  for ($i = 0; $i -lt $ls.Count; $i++) { if ($ls[$i] -eq $heading -or $ls[$i] -match [regex]::Escape($heading)) { $s = $i; break } }
  if ($s -lt 0) { return }
  for ($i = $s; $i -lt $ls.Count; $i++) {
    if ($i -gt $s -and $ls[$i] -match '^## ') { break }
    if ($ls[$i] -notmatch '^\| (\d+) \|') { continue }
    $newRank = & $resolver $ls[$i]
    if ($null -ne $newRank) {
      $ls[$i] = $ls[$i] -replace '^\| \d+ \|', "| $newRank |"
    }
  }
}

