]
total = len(renumbered)
lines[data_start:data_end] = renumbered

spawn_eggs = sum(1 for r in renumbered if "| Spawn egg |" in r)
potions = sum(1 for r in renumbered if "| Potion |" in r)
arrows = sum(1 for r in renumbered if "| Arrow |" in r)

for i, l in enumerate(lines):
    if l.startswith("## Ranked list"):
        lines[i] = f"## Ranked list (1 = least powerful -> {total} = most powerful)"
