            f"+ **1 Glowstone stack (x8)** + **1 Iron Ingot stack (x16)** + **1 Diamond stack (x16)** "
            f"+ **Netherite scrap** + **Netherite ingot** + **Nether Star** + 18 armor trims "
            f"+ 3 mineral blocks + 43 enchanted books + 1 RootMC item = **{total}** entries."
        )


def strip_marks(s: str) -> str:
