key_ranks: dict[str, int] = {}
start = next(i for i, l in enumerate(lines) if l.startswith("## Ranked list"))
data_start = next(i for i in range(start, len(lines)) if lines[i].startswith("| ---:")) + 1
data_end = data_start
while data_end < len(lines) and lines[data_end].startswith("|"):
    data_end += 1

for i in range(data_start, data_end):
