        continue
    rank = int(cols[0])
    kind = cols[1]
    bukkit = strip_marks(cols[3])
    ns = cols[4]
    if kind == "Arrow":
        if bukkit == "ARROW":
            key_ranks["arrow:plain"] = rank
        elif bukkit == "SPECTRAL_ARROW":
            key_ranks["arrow:spectral"] = rank
        else:
            m = re.search(r"\+ `minecraft:([a-z0-9_]+)`", ns)
            if m:
                key_ranks[f"arrow:tipped_{m.group(1)}"] = rank
    elif kind == "RootMC":
        key_ranks["rootmc:free_lotto_ticket"] = rank
    elif bukkit:
        key_ranks[bukkit] = rank
    em = re.search(r"minecraft:enchanted_book` \+ `minecraft:([a-z0-9_]+)", ns)
    if em:
        key_ranks[f"ns:enchant:{em.group(1)}"] = rank
    if kind == "Potion":
        pm = re.search(r"\+ `minecraft:([a-z0-9_]+)`", ns)
        if pm:
            key_ranks[f"ns:potion:{pm.group(1)}"] = rank

