import java.util.logging.Level;

/** Weighted redeem catalog loaded from {@code appreciation-rewards.json}. */
public final class AppreciationRewardPool {

    public record Reward(
            String id,
            String entry,
            int rank,
            int qty,
            int weight,
            String kind,
            String material,
            String enchant,
            String potion) {}

    private final List<Reward> rewards;
    private final long weightSum;
    private final String formula;

    public AppreciationRewardPool(RootAppreciationPlugin plugin) {
        List<Reward> loaded = new ArrayList<>();
        long sum = 0;
        String formula = "(248-rank)^1.2";
        try (InputStream in = plugin.getResource("appreciation-rewards.json")) {
            if (in == null) {
                plugin.getLogger().severe("Missing appreciation-rewards.json in jar");
            } else {
                JsonObject root = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8))
                        .getAsJsonObject();
                if (root.has("formula")) {
                    formula = root.get("formula").getAsString();
                }
                JsonArray arr = root.getAsJsonArray("rewards");
                for (JsonElement el : arr) {
                    JsonObject o = el.getAsJsonObject();
                    Reward r = new Reward(
                            o.get("id").getAsString(),
                            o.get("entry").getAsString(),
                            o.get("rank").getAsInt(),
                            o.get("qty").getAsInt(),
                            o.get("weight").getAsInt(),
                            o.get("kind").getAsString(),
                            o.has("material") ? o.get("material").getAsString() : null,
                            o.has("enchant") ? o.get("enchant").getAsString() : null,
                            o.has("potion") ? o.get("potion").getAsString() : null);
                    if (r.weight() > 0) {
                        loaded.add(r);
                        sum += r.weight();
                    }
                }
            }
        } catch (Exception ex) {
            plugin.getLogger().log(Level.SEVERE, "Failed loading appreciation-rewards.json", ex);
        }
        this.rewards = List.copyOf(loaded);
        this.weightSum = Math.max(1, sum);
        this.formula = formula;
        plugin.getLogger().info("Appreciation redeem pool: " + rewards.size() + " entries, weightSum=" + weightSum);
    }

    public List<Reward> rewards() {
        return rewards;
    }

    public long weightSum() {
        return weightSum;
    }

    public String formula() {
        return formula;
    }

    public boolean ready() {
        return !rewards.isEmpty();
    }

    public Reward roll() {
        if (rewards.isEmpty()) {
            return null;
        }
        long pick = ThreadLocalRandom.current().nextLong(weightSum);
        long cursor = 0;
        for (Reward r : rewards) {
            cursor += r.weight();
            if (pick < cursor) {
                return r;
            }
        }
        return rewards.get(rewards.size() - 1);
    }
}

package com.rootrecord.minecraft.rootappreciation;

import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.PlayerInventory;
import org.bukkit.inventory.meta.EnchantmentStorageMeta;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.PotionMeta;
import org.bukkit.potion.PotionType;

import java.lang.reflect.Method;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;

/** Builds and delivers one redeem reward (material / book / potion / tipped / free lotto). */
public final class AppreciationRewardGranter {

    private final RootAppreciationPlugin plugin;

    public AppreciationRewardGranter(RootAppreciationPlugin plugin) {
        this.plugin = plugin;
    }

    public static boolean hasEmptySlot(Player player) {
        PlayerInventory inv = player.getInventory();
        for (ItemStack stack : inv.getStorageContents()) {
            if (stack == null || stack.getType().isAir()) {
                return true;
            }
        }
        ItemStack off = inv.getItemInOffHand();
        return off == null || off.getType().isAir();
    }

    public boolean grant(Player player, AppreciationRewardPool.Reward reward) {
        if (reward == null) {
            return false;
        }
        if ("free_lotto".equalsIgnoreCase(reward.kind())) {
            return grantFreeLotto(player);
        }
        ItemStack stack = buildStack(reward);
        if (stack == null || stack.getType().isAir()) {
            plugin.getLogger().warning("Could not build reward: " + reward.id());
            return false;
        }
        return giveOrOffhand(player, stack);
    }

    private boolean giveOrOffhand(Player player, ItemStack stack) {
        Map<Integer, ItemStack> overflow = player.getInventory().addItem(stack);
        if (overflow.isEmpty()) {
            return true;
        }
        ItemStack rem = overflow.values().iterator().next();
        ItemStack off = player.getInventory().getItemInOffHand();
        if (off == null || off.getType().isAir()) {
            player.getInventory().setItemInOffHand(rem);
            return true;
        }
        player.getWorld().dropItemNaturally(player.getLocation(), rem);
        player.sendMessage(plugin.msg("inventory-full"));
        return true;
    }

    private ItemStack buildStack(AppreciationRewardPool.Reward reward) {
        String kind = reward.kind() == null ? "" : reward.kind().toLowerCase(Locale.ROOT);
        int qty = Math.max(1, Math.min(64, reward.qty()));
        return switch (kind) {
            case "enchanted_book" -> enchantedBook(reward.enchant(), qty);
            case "potion" -> potion(Material.POTION, reward.potion(), qty);
            case "tipped_arrow" -> potion(Material.TIPPED_ARROW, reward.potion(), qty);
            case "material" -> material(reward.material(), qty);
            default -> null;
        };
    }

    private ItemStack material(String name, int qty) {
        if (name == null || name.isBlank()) {
            return null;
        }
        Material mat = Material.matchMaterial(name);
        if (mat == null || mat.isAir()) {
            return null;
        }
        return new ItemStack(mat, qty);
    }

    private ItemStack enchantedBook(String enchantKey, int qty) {
        if (enchantKey == null || enchantKey.isBlank()) {
            return null;
        }
        Enchantment enchant = Enchantment.getByKey(NamespacedKey.minecraft(enchantKey.toLowerCase(Locale.ROOT)));
        if (enchant == null) {
            return null;
        }
        ItemStack stack = new ItemStack(Material.ENCHANTED_BOOK, qty);
        ItemMeta meta = stack.getItemMeta();
        if (!(meta instanceof EnchantmentStorageMeta storage)) {
            return null;
        }
        storage.addStoredEnchant(enchant, Math.max(1, enchant.getMaxLevel()), true);
        stack.setItemMeta(storage);
        return stack;
    }

    private ItemStack potion(Material base, String potionKey, int qty) {
        if (potionKey == null || potionKey.isBlank()) {
            return null;
        }
        PotionType type;
        try {
            type = PotionType.valueOf(potionKey.toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ex) {
            return null;
        }
        ItemStack stack = new ItemStack(base, qty);
        ItemMeta meta = stack.getItemMeta();
        if (!(meta instanceof PotionMeta potionMeta)) {
            return null;
        }
        potionMeta.setBasePotionType(type);
        stack.setItemMeta(potionMeta);
        return stack;
    }

    private boolean grantFreeLotto(Player player) {
        org.bukkit.plugin.Plugin gamble = Bukkit.getPluginManager().getPlugin("Root-Gamble");
        if (gamble == null || !gamble.isEnabled()) {
            // Fallback: paper voucher if gamble missing
            ItemStack paper = new ItemStack(Material.PAPER, 1);
            ItemMeta meta = paper.getItemMeta();
            if (meta != null) {
                meta.setDisplayName(plugin.colorize("&6Free Lotto Ticket"));
                meta.setLore(java.util.List.of(
                        plugin.colorize("&7Root-Gamble offline — show staff"),
                        plugin.colorize("&8Credit for /lotto free play")));
                paper.setItemMeta(meta);
            }
            return giveOrOffhand(player, paper);
        }
        try {
            Method grant = gamble.getClass().getMethod("grantFreePlay", UUID.class, String.class);
            grant.invoke(gamble, player.getUniqueId(), "lotto");
            return true;
        } catch (ReflectiveOperationException ex) {
            plugin.getLogger().warning("grantFreePlay failed: " + ex.getMessage());
            return false;
        }
    }
}

package com.rootrecord.minecraft.rootappreciation;

import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;

/** Right-click Appreciation Token to redeem one weighted reward. */
public final class AppreciationTokenListener implements Listener {

    private final RootAppreciationPlugin plugin;

    public AppreciationTokenListener(RootAppreciationPlugin plugin) {
        this.plugin = plugin;
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onInteract(PlayerInteractEvent event) {
        Action action = event.getAction();
        if (action != Action.RIGHT_CLICK_AIR && action != Action.RIGHT_CLICK_BLOCK) {
            return;
        }
        if (event.getHand() != EquipmentSlot.HAND) {
            return;
        }
        Player player = event.getPlayer();
        ItemStack stack = player.getInventory().getItemInMainHand();
        if (!plugin.tokens().isAppreciationToken(stack)) {
            return;
        }
        if (!plugin.config().enabled() || !plugin.config().redeemEnabled()) {
            return;
        }
        if (!player.hasPermission("rootappreciation.redeem")) {
            return;
        }
        event.setCancelled(true);
        // Defer one tick so interact does not fight inventory mutations.
        Bukkit.getScheduler().runTask(plugin, () -> plugin.service().redeemOne(player));
    }
}

package com.rootrecord.minecraft.rootappreciation;

import org.bukkit.configuration.file.YamlConfiguration;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Level;

/** Weighted redeem catalog loaded from {@code appreciation-rewards.yml}. */
public final class AppreciationRewardPool {

    public record Reward(
            String id,
            String entry,
            int rank,
            int qty,
            int weight,
            String kind,
            String material,
            String enchant,
            String potion) {}

    private final List<Reward> rewards;
    private final long weightSum;
    private final String formula;

    public AppreciationRewardPool(RootAppreciationPlugin plugin) {
        List<Reward> loaded = new ArrayList<>();
        long sum = 0;
        String formula = "(248-rank)^1.2";
        try (InputStream in = plugin.getResource("appreciation-rewards.yml")) {
            if (in == null) {
                plugin.getLogger().severe("Missing appreciation-rewards.yml in jar");
            } else {
                YamlConfiguration yaml = YamlConfiguration.loadConfiguration(
                        new InputStreamReader(in, StandardCharsets.UTF_8));
                formula = yaml.getString("formula", formula);
                for (Map<?, ?> map : yaml.getMapList("rewards")) {
                    String id = str(map.get("id"));
                    String entry = str(map.get("entry"));
                    String kind = str(map.get("kind"));
                    int rank = num(map.get("rank"), 0);
                    int qty = Math.max(1, num(map.get("qty"), 1));
                    int weight = Math.max(0, num(map.get("weight"), 0));
                    if (id.isBlank() || entry.isBlank() || kind.isBlank() || weight <= 0) {
                        continue;
                    }
                    Reward r = new Reward(
                            id,
                            entry,
                            rank,
                            qty,
                            weight,
                            kind,
                            blankToNull(str(map.get("material"))),
                            blankToNull(str(map.get("enchant"))),
                            blankToNull(str(map.get("potion"))));
                    loaded.add(r);
                    sum += weight;
                }
            }
        } catch (Exception ex) {
            plugin.getLogger().log(Level.SEVERE, "Failed loading appreciation-rewards.yml", ex);
        }
        this.rewards = List.copyOf(loaded);
        this.weightSum = Math.max(1, sum);
        this.formula = formula;
        plugin.getLogger().info("Appreciation redeem pool: " + rewards.size() + " entries, weightSum=" + weightSum);
    }

    private static String str(Object o) {
        return o == null ? "" : String.valueOf(o).trim();
    }

    private static String blankToNull(String s) {
        return s == null || s.isBlank() ? null : s;
    }

    private static int num(Object o, int def) {
        if (o instanceof Number n) {
            return n.intValue();
        }
        if (o != null) {
            try {
                return Integer.parseInt(String.valueOf(o).trim());
            } catch (NumberFormatException ignored) {
                // fall through
            }
        }
        return def;
    }

    public List<Reward> rewards() {
        return rewards;
    }

    public long weightSum() {
        return weightSum;
    }

    public String formula() {
        return formula;
    }

    public boolean ready() {
        return !rewards.isEmpty();
    }

    public Reward roll() {
        if (rewards.isEmpty()) {
            return null;
        }
        long pick = ThreadLocalRandom.current().nextLong(weightSum);
        long cursor = 0;
        for (Reward r : rewards) {
            cursor += r.weight();
            if (pick < cursor) {
                return r;
            }
        }
        return rewards.get(rewards.size() - 1);
    }
}

