{
  "name": "rootmc-sexi",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Local Sexi Discord recommendation assistant foundation (design recs only).",
  "scripts": {
    "start": "node src/index.mjs",
    "server": "node src/server.mjs",
    "poller": "node src/poller.mjs",
    "post-proposal": "node scripts/post-proposal.mjs"
  },
  "engines": {
    "node": ">=20"
  }
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** Reuse RootMC realm-api env loader without publishing a package. */
export function loadEnv() {
  const loaderPath = path.resolve(
    __dirname,
    "../../rootmc-realm-api/scripts/lib/rootmc-env.mjs",
  );
  if (!fs.existsSync(loaderPath)) {
    throw new Error(`Missing env loader at ${loaderPath}`);
  }
  return import(loaderPath).then((m) => m.loadRootMcEnv());
}

export function botToken(env) {
  return String(env.DISCORD_ROOTMC_BOT_TOKEN || env.DISCORD_BOT_TOKEN || "")
    .replace(/^bot\s+/i, "")
    .trim();
}

export function grokToken(env) {
  return String(
    env.GROK_API_BEARER_TOKEN ||
      env.GROK_ROOT_ASK_BEARER_TOKEN ||
      env.XAI_API_KEY ||
      "",
  ).trim();
}

/** Discord user IDs Sexi must never @mention. */
export const NEVER_MENTION = new Set([
  "788153722198294618", // asked not to be tagged
]);

export const DISCORD_API = "https://discord.com/api/v10";
export const ROOTMC_GUILD_ID = "1516108585740800042";
export const ROOTMC_BOT_APP_ID = "1511794429986345020";

/** Default watch list — proposals forum + admins. */
export const DEFAULT_WATCH_CHANNELS = [
  "1526664180491358419", // proposals
  "1516121832493678612", // admins
];

export const SEXI_PORT = Number(process.env.SEXI_PORT || 8787);

import { grokToken, NEVER_MENTION } from "./config.mjs";

const SYSTEM = `You are Sexi, RootMC's playful design assistant in Discord.
Give concise Minecraft SMP / economy / skills / quests recommendations.
Rules:
- Design and player-experience advice only.
- Never mention serverside secrets, deploy steps, databases, credentials, jar filenames, internal disk paths, FileZilla, Shockbyte panel steps, or API tokens.
- Never @mention Discord user IDs in the deny list (they will be stripped anyway).
- Prefer Gold (G) not dollars.
- Keep replies under 1800 characters.
- Be friendly and direct.`;

export function stripForbiddenMentions(text) {
  let out = String(text || "");
  for (const id of NEVER_MENTION) {
    out = out.replace(new RegExp(`<@!?${id}>`, "g"), "that player");
  }
  return out;
}

export function heuristicRecommend(question, context = "") {
  const q = `${question}\n${context}`.toLowerCase();
  const bits = [];
  bits.push("**Sexi (heuristic):**");
  if (/quest|challenge|crate|key/.test(q)) {
    bits.push(
      "Keep quests **optional**. Rewards should match Appreciation Tokens / cosmetics — fun, not wallet or claim advantage. If keys exist, open fluff crates, not economy bombs.",
    );
  }
  if (/skill|mcmmo|prestige|level/.test(q)) {
    bits.push(
      "Preserve veteran levels on any skills replace (1:1 migrate). Milestone flavor every ~25 levels is fine; prestige is long-term. Don't shrink Retro caps just to feel 'cleaner'.",
    );
  }
  if (/token|appreciation|redeem|vote/.test(q)) {
    bits.push(
      "Tokens are already the soft-reward lane — vote /bonus / trade / right-click redeem. Point people at https://rootmc.net/thanks/ for odds.",
    );
  }
  if (/shop|market|economy|gold/.test(q)) {
    bits.push(
      "Player shops set prices; mint-peg gold resources stay out of shops. Prefer treasury-backed rewards over minting Gold.",
    );
  }
  if (bits.length === 1) {
    bits.push(
      "Need a sharper ask — quests, skills, economy, tokens, towns? I'll give a concrete rec.",
    );
  }
  bits.push("_LLM offline or unused — heuristic path._");
  return stripForbiddenMentions(bits.join("\n"));
}

export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) return stripForbiddenMentions("Ask me something about RootMC design.");

  const key = grokToken(env || {});
  if (!key) {
    return heuristicRecommend(q, context);
  }

  try {
    const res = await fetch("https://api.x.ai/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "grok-3-mini",
        temperature: 0.5,
        max_tokens: 700,
        messages: [
          { role: "system", content: SYSTEM },
          {
            role: "user",
            content: `Thread/context:\n${String(context || "(none)").slice(0, 3500)}\n\nQuestion:\n${q}`,
          },
        ],
      }),
    });
    const text = await res.text();
    if (!res.ok) {
      return heuristicRecommend(q, context) + `\n_(LLM ${res.status} — fell back)_`;
    }
    const data = JSON.parse(text);
    const reply = data?.choices?.[0]?.message?.content?.trim();
    if (!reply) return heuristicRecommend(q, context);
    return stripForbiddenMentions(reply.slice(0, 1900));
  } catch {
    return heuristicRecommend(q, context);
  }
}

export function looksLikeSexiTrigger(content, botUserId) {
  const raw = String(content || "");
  if (!raw.trim()) return false;
  if (botUserId && raw.includes(`<@${botUserId}>`)) return true;
  if (botUserId && raw.includes(`<@!${botUserId}>`)) return true;
  return /\b@?sexi\b/i.test(raw) || /sexi\s+assistant/i.test(raw);
}

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/\b@?sexi\b/gi, "")
    .replace(/sexi\s+assistant/gi, "")
    .trim();
}

import http from "node:http";
import { loadEnv, SEXI_PORT } from "./config.mjs";
import { recommend } from "./recommend.mjs";

const env = await loadEnv();

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://127.0.0.1:${SEXI_PORT}`);
  res.setHeader("Content-Type", "application/json; charset=utf-8");

  if (req.method === "GET" && url.pathname === "/health") {
    res.end(JSON.stringify({ ok: true, service: "rootmc-sexi", version: "0.1.0" }));
    return;
  }

  if (req.method === "POST" && url.pathname === "/v1/recommend") {
    let body = "";
    for await (const chunk of req) body += chunk;
    let parsed = {};
    try {
      parsed = body ? JSON.parse(body) : {};
    } catch {
      res.statusCode = 400;
      res.end(JSON.stringify({ error: "invalid_json" }));
      return;
    }
    const answer = await recommend({
      question: parsed.question || parsed.prompt || "",
      context: parsed.context || "",
      env,
    });
    res.end(JSON.stringify({ answer }));
    return;
  }

  res.statusCode = 404;
  res.end(JSON.stringify({ error: "not_found" }));
});

server.listen(SEXI_PORT, "127.0.0.1", () => {
  console.log(`rootmc-sexi HTTP on http://127.0.0.1:${SEXI_PORT}`);
});

import {
  loadEnv,
  botToken,
  DISCORD_API,
  ROOTMC_BOT_APP_ID,
  DEFAULT_WATCH_CHANNELS,
} from "./config.mjs";
import {
  extractQuestion,
  looksLikeSexiTrigger,
  recommend,
} from "./recommend.mjs";

const env = await loadEnv();
const token = botToken(env);
if (token.length < 40) {
  console.error("DISCORD_ROOTMC_BOT_TOKEN missing — poller idle");
  process.exit(1);
}

const headers = {
  Authorization: `Bot ${token}`,
  "User-Agent": "RootMC-Sexi/0.1",
  "Content-Type": "application/json",
};

const seen = new Set();
const watch = (process.env.SEXI_WATCH_CHANNELS || DEFAULT_WATCH_CHANNELS.join(","))
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

const POLL_MS = Number(process.env.SEXI_POLL_MS || 12_000);

async function fetchJson(path, init = {}) {
  const res = await fetch(`${DISCORD_API}${path}`, {
    ...init,
    headers: { ...headers, ...(init.headers || {}) },
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${path} ${res.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : null;
}

async function channelTargets() {
  const out = new Set(watch);
  // Expand proposals forum into active threads
  if (watch.includes("1526664180491358419")) {
    try {
      const active = await fetchJson(`/guilds/1516108585740800042/threads/active`);
      for (const t of active?.threads || []) {
        if (t.parent_id === "1526664180491358419") out.add(t.id);
      }
    } catch (err) {
      console.warn("active threads:", err.message);
    }
  }
  return [...out];
}

async function reply(channelId, content, refId) {
  return fetchJson(`/channels/${channelId}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: String(content).slice(0, 2000),
      message_reference: refId ? { message_id: refId } : undefined,
      allowed_mentions: { parse: [] },
    }),
  });
}

async function tick() {
  const channels = await channelTargets();
  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=15`);
    } catch {
      continue;
    }
    for (const msg of messages || []) {
      if (!msg?.id || seen.has(msg.id)) continue;
      seen.add(msg.id);
      if (seen.size > 5000) {
        const drop = [...seen].slice(0, 1000);
        for (const id of drop) seen.delete(id);
      }
      if (msg.author?.bot) continue;
      if (msg.author?.id === ROOTMC_BOT_APP_ID) continue;
      if (!looksLikeSexiTrigger(msg.content, ROOTMC_BOT_APP_ID)) continue;

      const question = extractQuestion(msg.content) || "What do you recommend here?";
      const older = (messages || [])
        .filter((m) => m.id !== msg.id)
        .slice(0, 8)
        .map((m) => `${m.author?.username}: ${m.content}`)
        .join("\n");
      console.log(`sexi trigger in ${channelId} from ${msg.author?.username}`);
      const answer = await recommend({ question, context: older, env });
      try {
        await reply(channelId, answer, msg.id);
      } catch (err) {
        console.warn("reply failed:", err.message);
      }
    }
  }
}

console.log(`rootmc-sexi poller watching ${watch.length} base channel(s), every ${POLL_MS}ms`);
await tick();
setInterval(() => {
  tick().catch((err) => console.warn("tick:", err.message));
}, POLL_MS);

import { spawn } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

function run(script) {
  const child = spawn(process.execPath, [path.join(__dirname, script)], {
    cwd: root,
    stdio: "inherit",
    env: process.env,
  });
  child.on("exit", (code) => {
    console.error(`${script} exited`, code);
    process.exit(code || 1);
  });
  return child;
}

run("server.mjs");
run("poller.mjs");

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadRootMcEnv, rootMcBotToken } from "../../rootmc-realm-api/scripts/lib/rootmc-env.mjs";
import { discordMessageUrl } from "../../rootmc-realm-api/scripts/lib/rootmc-discord.mjs";

const API = "https://discord.com/api/v10";
const forumId = "1526664180491358419";
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const planPath = path.resolve(__dirname, "../PROPOSAL.md");
const planBytes = fs.readFileSync(planPath);
const token = rootMcBotToken(loadRootMcEnv()).replace(/^bot\s+/i, "").trim();

const summary = [
  "**Proposal: Sexi Discord recommendation assistant** — foundation scaffolding.",
  "",
  "**Goal:** Local background helper so staff can ask **Sexi** / `@sexi` for **design recommendations** in Discord (proposals / admins) without waiting for a Cursor relay.",
  "",
  "**Principles:**",
  "• Public replies = game-design only (no secrets / deploys / DB / jars)",
  "• Opt-out: never ping players who ask not to be tagged",
  "• Local-first HTTP + poller now; Gateway / slash / Cursor SDK later",
  "",
  "**v0 folder:** `Web Files/rootmc-sexi/` — `npm start` → health on `:8787` + channel poller.",
  "",
  "Full proposal attached. Status: **foundation live locally — expand after feedback.**",
].join("\n");

const threadRes = await fetch(`${API}/channels/${forumId}/threads`, {
  method: "POST",
  headers: {
    Authorization: `Bot ${token}`,
    "Content-Type": "application/json",
    "User-Agent": "RootMC/post-sexi-proposal",
  },
  body: JSON.stringify({
    name: "Sexi Discord recommendation assistant (foundation)",
    auto_archive_duration: 10080,
    message: { content: summary.slice(0, 2000) },
  }),
});
const threadText = await threadRes.text();
if (!threadRes.ok) throw new Error(`thread ${threadRes.status}: ${threadText.slice(0, 500)}`);
const thread = JSON.parse(threadText);
console.log("DISCORD_THREAD", discordMessageUrl(forumId, thread.id));

const form = new FormData();
form.append("payload_json", JSON.stringify({ content: "Full proposal (markdown)." }));
form.append("files[0]", new Blob([planBytes], { type: "text/markdown" }), "sexi-proposal.md");
const fileRes = await fetch(`${API}/channels/${thread.id}/messages`, {
  method: "POST",
  headers: { Authorization: `Bot ${token}`, "User-Agent": "RootMC/post-sexi-proposal" },
  body: form,
});
const fileText = await fileRes.text();
if (!fileRes.ok) throw new Error(`file ${fileRes.status}: ${fileText.slice(0, 500)}`);
const msg = JSON.parse(fileText);
console.log("DISCORD_FILE", discordMessageUrl(thread.id, msg.id));

