package com.rootrecord.minecraft.rootheads;

import org.bukkit.Material;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.entity.EntityType;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public final class HeadsConfig {

    public record MobHead(
            String id,
            EntityType entityType,
            String displayName,
            Material material,
            String texture,
            double chance,
            double lootingBonus
    ) {}

    public record PlayerHeads(
            boolean enabled,
            boolean requirePvp,
            long samePairCooldownMs,
            double chance,
            double lootingBonus,
            String displayName,
            List<String> lore
    ) {}

    private final boolean enabled;
    private final boolean requireDirectPlayerKill;
    private final boolean denySpawner;
    private final boolean denySpawnerEgg;
    private final long sameMobCooldownMs;
    private final Map<String, String> messages;
    private final Map<String, MobHead> mobs;
    private final PlayerHeads playerHeads;

    private HeadsConfig(
            boolean enabled,
            boolean requireDirectPlayerKill,
            boolean denySpawner,
            boolean denySpawnerEgg,
            long sameMobCooldownMs,
            Map<String, String> messages,
            Map<String, MobHead> mobs,
            PlayerHeads playerHeads) {
        this.enabled = enabled;
        this.requireDirectPlayerKill = requireDirectPlayerKill;
        this.denySpawner = denySpawner;
        this.denySpawnerEgg = denySpawnerEgg;
        this.sameMobCooldownMs = sameMobCooldownMs;
        this.messages = messages;
        this.mobs = mobs;
        this.playerHeads = playerHeads;
    }

    public static HeadsConfig from(FileConfiguration cfg) {
        Map<String, String> messages = new LinkedHashMap<>();
        ConfigurationSection msgSec = cfg.getConfigurationSection("messages");
        if (msgSec != null) {
            for (String key : msgSec.getKeys(false)) {
                messages.put(key, msgSec.getString(key, ""));
            }
        }

        Map<String, MobHead> mobs = new LinkedHashMap<>();
        ConfigurationSection mobSec = cfg.getConfigurationSection("mobs");
        if (mobSec != null) {
            for (String id : mobSec.getKeys(false)) {
                ConfigurationSection row = mobSec.getConfigurationSection(id);
                if (row == null || !row.getBoolean("enabled", true)) {
                    continue;
                }
                EntityType type;
                try {
                    type = EntityType.valueOf(id.trim().toUpperCase(Locale.ROOT));
                } catch (IllegalArgumentException ex) {
                    continue;
                }
                Material mat = Material.matchMaterial(row.getString("material", "PLAYER_HEAD"));
                if (mat == null || mat.isAir()) {
                    mat = Material.PLAYER_HEAD;
                }
                double chance = Math.max(0, Math.min(1, row.getDouble("chance", 0.02)));
                double looting = Math.max(0, row.getDouble("looting-bonus", 0.005));
                String key = id.toLowerCase(Locale.ROOT);
                mobs.put(key, new MobHead(
                        key,
                        type,
                        row.getString("display-name", "&f" + id + " Head"),
                        mat,
                        row.getString("texture", ""),
                        chance,
                        looting));
            }
        }

        ConfigurationSection ph = cfg.getConfigurationSection("player-heads");
        List<String> lore = ph != null ? ph.getStringList("lore") : List.of();
        if (lore.isEmpty()) {
            lore = List.of("&7Root-Heads collectible");
        }
        long pairSec = ph != null ? Math.max(0, ph.getLong("same-pair-cooldown-seconds", 86400)) : 86400L;
        PlayerHeads playerHeads = new PlayerHeads(
                ph == null || ph.getBoolean("enabled", true),
                ph == null || ph.getBoolean("require-pvp", true),
                pairSec * 1000L,
                Math.max(0, Math.min(1, ph != null ? ph.getDouble("chance", 0.05) : 0.05)),
                Math.max(0, ph != null ? ph.getDouble("looting-bonus", 0.0) : 0.0),
                ph != null ? ph.getString("display-name", "&c{player}'s Head") : "&c{player}'s Head",
                Collections.unmodifiableList(new ArrayList<>(lore)));

        long cooldownSec = Math.max(0, cfg.getLong("same-mob-cooldown-seconds", 300));
        return new HeadsConfig(
                cfg.getBoolean("enabled", true),
                cfg.getBoolean("require-direct-player-kill", true),
                cfg.getBoolean("deny-spawner", true),
                cfg.getBoolean("deny-spawner-egg", true),
                cooldownSec * 1000L,
                Collections.unmodifiableMap(messages),
                Collections.unmodifiableMap(mobs),
                playerHeads);
    }

    public boolean enabled() {
        return enabled;
    }

    public boolean requireDirectPlayerKill() {
        return requireDirectPlayerKill;
    }

    public boolean denySpawner() {
        return denySpawner;
    }

    public boolean denySpawnerEgg() {
        return denySpawnerEgg;
    }

    public long sameMobCooldownMs() {
        return sameMobCooldownMs;
    }

    public Map<String, String> messages() {
        return messages;
    }

    public Map<String, MobHead> mobs() {
        return mobs;
    }

    public MobHead mob(String id) {
        if (id == null) {
            return null;
        }
        return mobs.get(id.toLowerCase(Locale.ROOT));
    }

    public MobHead byEntity(EntityType type) {
        if (type == null) {
            return null;
        }
        return mobs.get(type.name().toLowerCase(Locale.ROOT));
    }

    public PlayerHeads playerHeads() {
        return playerHeads;
    }

    public boolean playerHeadsEnabled() {
        return playerHeads.enabled();
    }
}

package com.rootrecord.minecraft.rootheads;

import com.destroystokyo.paper.profile.PlayerProfile;
import com.destroystokyo.paper.profile.ProfileProperty;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.OfflinePlayer;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.SkullMeta;
import org.bukkit.persistence.PersistentDataType;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.UUID;

public final class HeadItemFactory {

    private static final LegacyComponentSerializer LEGACY = LegacyComponentSerializer.legacyAmpersand();

    public static final String KIND_MOB = "mob";
    public static final String KIND_PLAYER = "player";

    private final NamespacedKey markerKey;
    private final NamespacedKey kindKey;
    private final NamespacedKey mobKey;
    private final NamespacedKey ownerKey;
    private final NamespacedKey versionKey;

    public HeadItemFactory(RootHeadsPlugin plugin) {
        this.markerKey = new NamespacedKey(plugin, "root_head");
        this.kindKey = new NamespacedKey(plugin, "head_kind");
        this.mobKey = new NamespacedKey(plugin, "mob_id");
        this.ownerKey = new NamespacedKey(plugin, "owner_uuid");
        this.versionKey = new NamespacedKey(plugin, "plugin_version");
    }

    public boolean isRootHead(ItemStack stack) {
        if (stack == null || !stack.hasItemMeta()) {
            return false;
        }
        return stack.getItemMeta().getPersistentDataContainer().has(markerKey, PersistentDataType.BYTE);
    }

    public String readKind(ItemStack stack) {
        if (!isRootHead(stack)) {
            return null;
        }
        return stack.getItemMeta().getPersistentDataContainer().get(kindKey, PersistentDataType.STRING);
    }

    public String readMobId(ItemStack stack) {
        if (!isRootHead(stack)) {
            return null;
        }
        return stack.getItemMeta().getPersistentDataContainer().get(mobKey, PersistentDataType.STRING);
    }

    public String readOwnerUuid(ItemStack stack) {
        if (!isRootHead(stack)) {
            return null;
        }
        return stack.getItemMeta().getPersistentDataContainer().get(ownerKey, PersistentDataType.STRING);
    }

    public ItemStack createMobHead(HeadsConfig.MobHead mob, String pluginVersion) {
        ItemStack stack = new ItemStack(mob.material(), 1);
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) {
            return stack;
        }
        meta.displayName(legacy(mob.displayName()));
        List<Component> lore = new ArrayList<>();
        lore.add(legacy("&7Root-Heads collectible"));
        lore.add(legacy("&8Mob drop · cosmetic"));
        meta.lore(lore);

        if (meta instanceof SkullMeta skull && mob.material() == Material.PLAYER_HEAD) {
            applyTexture(skull, mob.id(), mob.texture());
        }

        var pdc = meta.getPersistentDataContainer();
        pdc.set(markerKey, PersistentDataType.BYTE, (byte) 1);
        pdc.set(kindKey, PersistentDataType.STRING, KIND_MOB);
        pdc.set(mobKey, PersistentDataType.STRING, mob.id().toLowerCase(Locale.ROOT));
        pdc.set(versionKey, PersistentDataType.STRING, pluginVersion == null ? "" : pluginVersion);
        stack.setItemMeta(meta);
        return stack;
    }

    public ItemStack createPlayerHead(OfflinePlayer owner, HeadsConfig.PlayerHeads settings, String pluginVersion) {
        ItemStack stack = new ItemStack(Material.PLAYER_HEAD, 1);
        SkullMeta meta = (SkullMeta) stack.getItemMeta();
        if (meta == null) {
            return stack;
        }
        String name = owner.getName() != null ? owner.getName() : owner.getUniqueId().toString();
        meta.displayName(legacy(settings.displayName().replace("{player}", name)));
        List<Component> lore = new ArrayList<>();
        for (String line : settings.lore()) {
            lore.add(legacy(line == null ? "" : line.replace("{player}", name)));
        }
        meta.lore(lore);
        meta.setOwningPlayer(owner);

        var pdc = meta.getPersistentDataContainer();
        pdc.set(markerKey, PersistentDataType.BYTE, (byte) 1);
        pdc.set(kindKey, PersistentDataType.STRING, KIND_PLAYER);
        pdc.set(mobKey, PersistentDataType.STRING, "player");
        pdc.set(ownerKey, PersistentDataType.STRING, owner.getUniqueId().toString());
        pdc.set(versionKey, PersistentDataType.STRING, pluginVersion == null ? "" : pluginVersion);
        stack.setItemMeta(meta);
        return stack;
    }

    private void applyTexture(SkullMeta meta, String id, String texture) {
        if (texture == null || texture.isBlank()) {
            return;
        }
        UUID uuid = UUID.nameUUIDFromBytes(("RootHeads:" + id).getBytes(StandardCharsets.UTF_8));
        PlayerProfile profile = Bukkit.createProfile(uuid, id.length() > 16 ? id.substring(0, 16) : id);
        profile.setProperty(new ProfileProperty("textures", texture.trim()));
        meta.setPlayerProfile(profile);
    }

    private static Component legacy(String raw) {
        return LEGACY.deserialize(raw == null ? "" : raw).decoration(TextDecoration.ITALIC, false);
    }
}

package com.rootrecord.minecraft.rootheads;

import org.bukkit.entity.Player;

import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;

public final class HeadDropService {

    private final RootHeadsPlugin plugin;
    /** killerUuid|mobId → last drop millis */
    private final Map<String, Long> mobCooldowns = new ConcurrentHashMap<>();
    /** killerUuid|victimUuid → last drop millis */
    private final Map<String, Long> pairCooldowns = new ConcurrentHashMap<>();

    public HeadDropService(RootHeadsPlugin plugin) {
        this.plugin = plugin;
    }

    public void clearCooldowns() {
        mobCooldowns.clear();
        pairCooldowns.clear();
    }

    public boolean tryMobDrop(Player killer, HeadsConfig.MobHead mob, int lootingLevel) {
        HeadsConfig cfg = plugin.config();
        if (!cfg.enabled() || mob == null) {
            return false;
        }
        if (!killer.hasPermission("rootheads.drops")) {
            return false;
        }
        long now = System.currentTimeMillis();
        String key = killer.getUniqueId() + "|" + mob.id().toLowerCase(Locale.ROOT);
        long cd = cfg.sameMobCooldownMs();
        if (cd > 0) {
            Long last = mobCooldowns.get(key);
            if (last != null && now - last < cd) {
                return false;
            }
        }
        double chance = Math.min(1.0, mob.chance() + Math.max(0, lootingLevel) * mob.lootingBonus());
        if (ThreadLocalRandom.current().nextDouble() >= chance) {
            return false;
        }
        if (cd > 0) {
            mobCooldowns.put(key, now);
        }
        return true;
    }

    public boolean tryPlayerDrop(Player killer, Player victim, int lootingLevel) {
        HeadsConfig.PlayerHeads ph = plugin.config().playerHeads();
        if (!plugin.config().enabled() || !ph.enabled()) {
            return false;
        }
        if (!killer.hasPermission("rootheads.drops")) {
            return false;
        }
        if (killer.getUniqueId().equals(victim.getUniqueId())) {
            return false;
        }
        long now = System.currentTimeMillis();
        String key = pairKey(killer.getUniqueId(), victim.getUniqueId());
        long cd = ph.samePairCooldownMs();
        if (cd > 0) {
            Long last = pairCooldowns.get(key);
            if (last != null && now - last < cd) {
                return false;
            }
        }
        double chance = Math.min(1.0, ph.chance() + Math.max(0, lootingLevel) * ph.lootingBonus());
        if (ThreadLocalRandom.current().nextDouble() >= chance) {
            return false;
        }
        if (cd > 0) {
            pairCooldowns.put(key, now);
        }
        return true;
    }

    private static String pairKey(UUID killer, UUID victim) {
        return killer + "|" + victim;
    }
}

package com.rootrecord.minecraft.rootheads;

import org.bukkit.Material;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.CreatureSpawnEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.metadata.FixedMetadataValue;

public final class HeadDeathListener implements Listener {

    private static final String META_SPAWN_REASON = "rootheads_spawn_reason";

    private final RootHeadsPlugin plugin;

    public HeadDeathListener(RootHeadsPlugin plugin) {
        this.plugin = plugin;
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onSpawn(CreatureSpawnEvent event) {
        event.getEntity().setMetadata(
                META_SPAWN_REASON,
                new FixedMetadataValue(plugin, event.getSpawnReason().name()));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDeath(EntityDeathEvent event) {
        HeadsConfig cfg = plugin.config();
        if (!cfg.enabled()) {
            return;
        }

        Entity entity = event.getEntity();
        Player killer = event.getEntity().getKiller();
        if (cfg.requireDirectPlayerKill() && killer == null) {
            return;
        }
        if (killer == null) {
            return;
        }

        if (entity instanceof Player victim) {
            handlePlayerKill(killer, victim);
            return;
        }

        if (deniedSpawn(entity, cfg)) {
            return;
        }

        HeadsConfig.MobHead mob = cfg.byEntity(entity.getType());
        if (mob == null) {
            return;
        }
        int looting = lootingLevel(killer);
        if (!plugin.drops().tryMobDrop(killer, mob, looting)) {
            return;
        }
        ItemStack head = plugin.items().createMobHead(mob, plugin.getPluginMeta().getVersion());
        entity.getWorld().dropItemNaturally(entity.getLocation(), head);
        killer.sendMessage(plugin.msg("drop").replace("{head}", strip(mob.displayName())));
    }

    private void handlePlayerKill(Player killer, Player victim) {
        HeadsConfig.PlayerHeads ph = plugin.config().playerHeads();
        if (!ph.enabled()) {
            return;
        }
        if (ph.requirePvp()) {
            // getKiller() already implies player combat contribution.
        }
        int looting = lootingLevel(killer);
        if (!plugin.drops().tryPlayerDrop(killer, victim, looting)) {
            return;
        }
        ItemStack head = plugin.items().createPlayerHead(victim, ph, plugin.getPluginMeta().getVersion());
        victim.getWorld().dropItemNaturally(victim.getLocation(), head);
        killer.sendMessage(plugin.msg("player-drop").replace("{player}", victim.getName()));
    }

    private boolean deniedSpawn(Entity entity, HeadsConfig cfg) {
        if (!cfg.denySpawner() && !cfg.denySpawnerEgg()) {
            return false;
        }
        if (!entity.hasMetadata(META_SPAWN_REASON)) {
            return false;
        }
        String reason = entity.getMetadata(META_SPAWN_REASON).getFirst().asString();
        if (cfg.denySpawner() && "SPAWNER".equals(reason)) {
            return true;
        }
        return cfg.denySpawnerEgg() && "SPAWNER_EGG".equals(reason);
    }

    private static int lootingLevel(Player killer) {
        ItemStack hand = killer.getInventory().getItemInMainHand();
        if (hand == null || hand.getType() == Material.AIR) {
            return 0;
        }
        return hand.getEnchantmentLevel(Enchantment.LOOTING);
    }

    private static String strip(String colored) {
        if (colored == null) {
            return "";
        }
        return colored.replaceAll("(?i)&[0-9a-fk-or]", "");
    }
}

package com.rootrecord.minecraft.rootheads;

import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

public final class HeadsCommand implements CommandExecutor, TabCompleter {

    private final RootHeadsPlugin plugin;

    public HeadsCommand(RootHeadsPlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 0) {
            sender.sendMessage(plugin.colorize("&e/rootheads reload | give <player> <mob|player> [amount] | inspect"));
            return true;
        }
        String sub = args[0].toLowerCase(Locale.ROOT);
        return switch (sub) {
            case "reload" -> handleReload(sender);
            case "give" -> handleGive(sender, args);
            case "inspect" -> handleInspect(sender);
            default -> {
                sender.sendMessage(plugin.colorize("&e/rootheads reload | give <player> <mob|player> [amount] | inspect"));
                yield true;
            }
        };
    }

    private boolean handleReload(CommandSender sender) {
        if (!sender.hasPermission("rootheads.admin")) {
            sender.sendMessage(plugin.msg("no-permission"));
            return true;
        }
        plugin.reloadAll();
        sender.sendMessage(plugin.msg("reload"));
        return true;
    }

    private boolean handleGive(CommandSender sender, String[] args) {
        if (!sender.hasPermission("rootheads.admin")) {
            sender.sendMessage(plugin.msg("no-permission"));
            return true;
        }
        if (args.length < 3) {
            sender.sendMessage(plugin.msg("give-usage"));
            return true;
        }
        Player target = resolvePlayer(args[1]);
        if (target == null) {
            sender.sendMessage(plugin.msg("player-not-found").replace("{player}", args[1]));
            return true;
        }
        String mobId = args[2].toLowerCase(Locale.ROOT);
        int amount = 1;
        if (args.length >= 4) {
            try {
                amount = Integer.parseInt(args[3]);
            } catch (NumberFormatException ex) {
                sender.sendMessage(plugin.msg("give-usage"));
                return true;
            }
        }
        amount = Math.max(1, Math.min(64, amount));

        String version = plugin.getPluginMeta().getVersion();
        if ("player".equals(mobId)) {
            if (!plugin.config().playerHeadsEnabled()) {
                sender.sendMessage(plugin.msg("disabled"));
                return true;
            }
            for (int i = 0; i < amount; i++) {
                giveOrDrop(target, plugin.items().createPlayerHead(target, plugin.config().playerHeads(), version));
            }
        } else {
            HeadsConfig.MobHead mob = plugin.config().mob(mobId);
            if (mob == null) {
                String list = String.join(", ", plugin.config().mobs().keySet()) + ", player";
                sender.sendMessage(plugin.msg("unknown-mob").replace("{mobs}", list));
                return true;
            }
            for (int i = 0; i < amount; i++) {
                giveOrDrop(target, plugin.items().createMobHead(mob, version));
            }
        }
        sender.sendMessage(plugin.msg("give-ok")
                .replace("{amount}", String.valueOf(amount))
                .replace("{mob}", mobId)
                .replace("{player}", target.getName()));
        return true;
    }

    private boolean handleInspect(CommandSender sender) {
        if (!sender.hasPermission("rootheads.admin")) {
            sender.sendMessage(plugin.msg("no-permission"));
            return true;
        }
        if (!(sender instanceof Player player)) {
            sender.sendMessage(plugin.colorize("&cPlayers only."));
            return true;
        }
        ItemStack hand = player.getInventory().getItemInMainHand();
        if (!plugin.items().isRootHead(hand)) {
            sender.sendMessage(plugin.msg("inspect-no"));
            return true;
        }
        String kind = plugin.items().readKind(hand);
        String mob = plugin.items().readMobId(hand);
        String owner = plugin.items().readOwnerUuid(hand);
        String label = mob == null ? "?" : mob;
        if (HeadItemFactory.KIND_PLAYER.equals(kind) && owner != null) {
            label = "player (" + owner + ")";
        }
        sender.sendMessage(plugin.msg("inspect-yes").replace("{mob}", label));
        return true;
    }

    private static void giveOrDrop(Player target, ItemStack stack) {
        var leftover = target.getInventory().addItem(stack);
        leftover.values().forEach(left -> target.getWorld().dropItemNaturally(target.getLocation(), left));
    }

    private static Player resolvePlayer(String name) {
        Player exact = Bukkit.getPlayerExact(name);
        if (exact != null) {
            return exact;
        }
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (p.getName().equalsIgnoreCase(name)) {
                return p;
            }
        }
        return null;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        if (!sender.hasPermission("rootheads.admin")) {
            return List.of();
        }
        if (args.length == 1) {
            return filter(List.of("reload", "give", "inspect"), args[0]);
        }
        if (args.length == 2 && args[0].equalsIgnoreCase("give")) {
            return filter(Bukkit.getOnlinePlayers().stream().map(Player::getName).collect(Collectors.toList()), args[1]);
        }
        if (args.length == 3 && args[0].equalsIgnoreCase("give")) {
            List<String> ids = new ArrayList<>(plugin.config().mobs().keySet());
            ids.add("player");
            return filter(ids, args[2]);
        }
        if (args.length == 4 && args[0].equalsIgnoreCase("give")) {
            return filter(List.of("1", "8", "16", "64"), args[3]);
        }
        return List.of();
    }

    private static List<String> filter(List<String> options, String prefix) {
        String p = prefix.toLowerCase(Locale.ROOT);
        List<String> out = new ArrayList<>();
        for (String o : options) {
            if (o.toLowerCase(Locale.ROOT).startsWith(p)) {
                out.add(o);
