import path from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, CursorAgentError } from "@cursor/sdk";
import { cursorApiKey, SEXI_MODEL, SEXI_WORKSPACE } from "./config.mjs";
import { stripForbiddenMentions } from "./recommend.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** RootMC workspace root (plugins, web, docs). */
export function workspaceRoot() {
  if (SEXI_WORKSPACE) return SEXI_WORKSPACE;
  return path.resolve(__dirname, "../../..");
}

const SYSTEM_PROMPT = `You are Sexi, RootMC's design assistant answering in Discord.

Hard rules:
1. OUTPUT ONLY the Discord reply text. No preamble, no "Sure", no tool narration.
2. Design / player-experience recommendations only.
3. Do NOT edit files, create commits, run builds, deploy, touch .env, or change live servers.
4. Do NOT reveal secrets, tokens, credentials, database hosts, jar filenames, FileZilla/Shockbyte steps, or internal disk paths.
5. Prefer Gold (G), not dollars.
6. Keep under 1800 characters. Use short markdown (**bold**, bullets).
7. Never @mention Discord users by ID.
8. If repo context helps, use it silently — don't dump file paths in the reply.`;

/** Strip common secret / path leaks before Discord. */
export function scrubPublicReply(text) {
  let out = String(text || "");
  out = out.replace(/```[\s\S]*?```/g, (block) => {
    if (/password|token|secret|api[_-]?key|\.env/i.test(block)) {
      return "_[code omitted]_";
    }
    return block;
  });
  out = out.replace(/D:\\\.1 Work Stations\\RootMC[^\s`]*/gi, "`(workspace)`");
  out = out.replace(/\/(?:Users|home)\/[^\s`]+/gi, "`(path)`");
  out = out.replace(
    /\b(?:CURSOR_API_KEY|DISCORD_(?:ROOTMC_)?BOT_TOKEN|GROK_[A-Z0-9_]+|JWT_[A-Z0-9_]+|XAI_API_KEY)\b\s*[:=]\s*\S+/gi,
    "[redacted]",
  );
  out = out.replace(/\bsk-[a-zA-Z0-9_-]{20,}\b/g, "[redacted]");
  out = out.replace(/\bcursor_[a-zA-Z0-9_-]{20,}\b/g, "[redacted]");
  out = stripForbiddenMentions(out);
  return out.trim().slice(0, 1900);
}

let queue = Promise.resolve();

function enqueue(fn) {
  const run = queue.then(fn, fn);
  queue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

/**
 * One-shot local Cursor agent against the RootMC workspace.
 * Serialised so Discord bursts don't spawn parallel agents.
 */
export async function cursorRecommend({ question, context = "", env }) {
  const apiKey = cursorApiKey(env || {});
  if (!apiKey) {
    return { ok: false, reason: "missing_cursor_api_key", text: null };
  }

  const cwd = workspaceRoot();
  const prompt = `${SYSTEM_PROMPT}

Thread/context (Discord):
${String(context || "(none)").slice(0, 3500)}

Question:
${String(question).trim()}

Write the Discord reply now.`;

  return enqueue(async () => {
    try {
      const result = await Agent.prompt(prompt, {
        apiKey,
        model: {
          id: SEXI_MODEL,
          params: [{ id: "fast", value: "true" }],
        },
        local: {
          cwd,
          // Keep ambient settings off — Sexi is a service, not your IDE session.
          settingSources: [],
          // Constrain shell when the host supports it; ignore if unsupported.
          sandboxOptions: { enabled: true },
          autoReview: true,
        },
      });

      if (result.status === "error") {
        console.warn("cursor run error", result.id, result.error?.message || result.error);
        return {
          ok: false,
          reason: "run_error",
          text: null,
          runId: result.id,
        };
      }

      const raw = String(result.result || "").trim();
      if (!raw) {
        return { ok: false, reason: "empty_result", text: null, runId: result.id };
      }

      return {
        ok: true,
        reason: "ok",
        text: scrubPublicReply(raw),
        runId: result.id,
        agentId: result.agentId,
      };
    } catch (err) {
      // Retry once without sandbox if the host rejects sandboxOptions.
      const msg = err instanceof CursorAgentError ? err.message : String(err?.message || err);
      if (/sandbox/i.test(msg)) {
        try {
          const result = await Agent.prompt(prompt, {
            apiKey,
            model: { id: SEXI_MODEL, params: [{ id: "fast", value: "true" }] },
            local: { cwd, settingSources: [], autoReview: true },
          });
          if (result.status === "error" || !result.result) {
            return { ok: false, reason: "run_error", text: null };
          }
          return {
            ok: true,
            reason: "ok_no_sandbox",
            text: scrubPublicReply(result.result),
            runId: result.id,
          };
        } catch (err2) {
          console.warn("cursorRecommend fallback:", err2?.message || err2);
          return { ok: false, reason: "startup_error", text: null };
        }
      }
      console.warn("cursorRecommend:", msg);
      return {
        ok: false,
        reason: err instanceof CursorAgentError ? "startup_error" : "unknown_error",
        text: null,
      };
    }
  });
}

import { NEVER_MENTION } from "./config.mjs";

export function stripForbiddenMentions(text) {
  let out = String(text || "");
  for (const id of NEVER_MENTION) {
    out = out.replace(new RegExp(`<@!?${id}>`, "g"), "that player");
  }
  return out;
}

/** Strip common secret / path leaks before Discord. */
export function scrubPublicReply(text) {
  let out = stripForbiddenMentions(text);
  out = out.replace(/```[\s\S]*?```/g, (block) => {
    if (/password|token|secret|api[_-]?key|\.env/i.test(block)) {
      return "_[code omitted]_";
    }
    return block;
  });
  out = out.replace(/D:\\\.1 Work Stations\\RootMC[^\s`]*/gi, "`(workspace)`");
  out = out.replace(/\/(?:Users|home)\/[^\s`]+/gi, "`(path)`");
  out = out.replace(
    /\b(?:CURSOR_API_KEY|DISCORD_(?:ROOTMC_)?BOT_TOKEN|GROK_[A-Z0-9_]+|JWT_[A-Z0-9_]+|XAI_API_KEY)\b\s*[:=]\s*\S+/gi,
    "[redacted]",
  );
  out = out.replace(/\bsk-[a-zA-Z0-9_-]{20,}\b/g, "[redacted]");
  out = out.replace(/\bcursor_[a-zA-Z0-9_-]{20,}\b/g, "[redacted]");
  return out.trim().slice(0, 1900);
}

