import { grokToken } from "./config.mjs";
import { cursorRecommend } from "./cursorBrain.mjs";
import { scrubPublicReply, stripForbiddenMentions } from "./scrub.mjs";

export { stripForbiddenMentions, scrubPublicReply };

export function heuristicRecommend(question, context = "") {
  const q = `${question}\n${context}`.toLowerCase();
  const bits = [];
  bits.push("**Sexi (heuristic):**");
  if (/quest|challenge|crate|key/.test(q)) {
    bits.push(
      "Keep quests **optional**. Rewards should match Appreciation Tokens / cosmetics — fun, not wallet or claim advantage. If keys exist, open fluff crates, not economy bombs.",
    );
  }
  if (/skill|mcmmo|prestige|level/.test(q)) {
    bits.push(
      "Preserve veteran levels on any skills replace (1:1 migrate). Milestone flavor every ~25 levels is fine; prestige is long-term. Don't shrink Retro caps just to feel 'cleaner'.",
    );
  }
  if (/token|appreciation|redeem|vote/.test(q)) {
    bits.push(
      "Tokens are already the soft-reward lane — vote /bonus / trade / right-click redeem. Point people at https://rootmc.net/thanks/ for odds.",
    );
  }
  if (/shop|market|economy|gold/.test(q)) {
    bits.push(
      "Player shops set prices; mint-peg gold resources stay out of shops. Prefer treasury-backed rewards over minting Gold.",
    );
  }
  if (bits.length === 1) {
    bits.push(
      "Need a sharper ask — quests, skills, economy, tokens, towns? I'll give a concrete rec.",
    );
  }
  bits.push("_Cursor API key missing or agent failed — heuristic fallback._");
  return scrubPublicReply(bits.join("\n"));
}

async function grokRecommend(question, context, env) {
  const key = grokToken(env || {});
  if (!key) return null;

  const SYSTEM = `You are Sexi, RootMC's playful design assistant in Discord.
Give concise Minecraft SMP / economy / skills / quests recommendations.
Rules: design only; no secrets/deploy; Gold not dollars; under 1800 chars.`;

  try {
    const res = await fetch("https://api.x.ai/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "grok-3-mini",
        temperature: 0.5,
        max_tokens: 700,
        messages: [
          { role: "system", content: SYSTEM },
          {
            role: "user",
            content: `Thread/context:\n${String(context || "(none)").slice(0, 3500)}\n\nQuestion:\n${question}`,
          },
        ],
      }),
    });
    if (!res.ok) return null;
    const data = await res.json();
    const reply = data?.choices?.[0]?.message?.content?.trim();
    return reply ? scrubPublicReply(reply) : null;
  } catch {
    return null;
  }
}

/**
 * Prefer Cursor (local agent on RootMC workspace). Heuristic fallback.
 * Grok only if SEXI_USE_GROK=1 (not preferred).
 */
export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) return scrubPublicReply("Ask me something about RootMC design.");

  const cursor = await cursorRecommend({ question: q, context, env });
  if (cursor.ok && cursor.text) {
    return cursor.text;
  }
  if (cursor.reason === "missing_cursor_api_key") {
    console.warn("Sexi: set CURSOR_API_KEY in RootMC .env for Cursor brain");
  } else if (cursor.reason) {
    console.warn("Sexi cursor brain:", cursor.reason);
  }

  const useGrok = String(process.env.SEXI_USE_GROK || "").trim() === "1";
  if (useGrok) {
    const grok = await grokRecommend(q, context, env);
    if (grok) return grok;
  }

  return heuristicRecommend(q, context);
}

export function looksLikeSexiTrigger(content, botUserId) {
  const raw = String(content || "");
  if (!raw.trim()) return false;
  if (botUserId && raw.includes(`<@${botUserId}>`)) return true;
  if (botUserId && raw.includes(`<@!${botUserId}>`)) return true;
  return /\b@?sexi\b/i.test(raw) || /sexi\s+assistant/i.test(raw);
}

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/\b@?sexi\b/gi, "")
    .replace(/sexi\s+assistant/gi, "")
    .trim();
}

