import {
  loadEnv,
  botToken,
  sexiBotAppId,
  DISCORD_API,
  DEFAULT_WATCH_CHANNELS,
} from "./config.mjs";
import {
  extractQuestion,
  looksLikeSexiTrigger,
  recommend,
} from "./recommend.mjs";

const env = await loadEnv();
const token = botToken(env);
const botAppId = sexiBotAppId(env);
if (token.length < 40) {
  console.error("SEXI_DISCORD_BOT_TOKEN missing — poller idle");
  process.exit(1);
}
if (!botAppId) {
  console.error("SEXI_DISCORD_APPLICATION_ID / CLIENT_ID missing — poller idle");
  process.exit(1);
}

const headers = {
  Authorization: `Bot ${token}`,
  "User-Agent": "RootMC-Sexi/0.2",
  "Content-Type": "application/json",
};

const seen = new Set();
const watch = (process.env.SEXI_WATCH_CHANNELS || DEFAULT_WATCH_CHANNELS.join(","))
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

const POLL_MS = Number(process.env.SEXI_POLL_MS || 12_000);

async function fetchJson(path, init = {}) {
  const res = await fetch(`${DISCORD_API}${path}`, {
    ...init,
    headers: { ...headers, ...(init.headers || {}) },
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${path} ${res.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : null;
}

async function channelTargets() {
  const out = new Set(watch);
  // Expand proposals forum into active threads
  if (watch.includes("1526664180491358419")) {
    try {
      const active = await fetchJson(`/guilds/1516108585740800042/threads/active`);
      for (const t of active?.threads || []) {
        if (t.parent_id === "1526664180491358419") out.add(t.id);
      }
    } catch (err) {
      console.warn("active threads:", err.message);
    }
  }
  return [...out];
}

async function reply(channelId, content, refId) {
  return fetchJson(`/channels/${channelId}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: String(content).slice(0, 2000),
      message_reference: refId ? { message_id: refId } : undefined,
      allowed_mentions: { parse: [] },
    }),
  });
}

async function tick() {
  const channels = await channelTargets();
  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=15`);
    } catch {
      continue;
    }
    for (const msg of messages || []) {
      if (!msg?.id || seen.has(msg.id)) continue;
      seen.add(msg.id);
      if (seen.size > 5000) {
        const drop = [...seen].slice(0, 1000);
        for (const id of drop) seen.delete(id);
      }
      if (msg.author?.bot) continue;
      if (msg.author?.id === botAppId) continue;
      if (!looksLikeSexiTrigger(msg.content, botAppId)) continue;

      const question = extractQuestion(msg.content) || "What do you recommend here?";
      const older = (messages || [])
        .filter((m) => m.id !== msg.id)
        .slice(0, 8)
        .map((m) => `${m.author?.username}: ${m.content}`)
        .join("\n");
      console.log(`sexi trigger in ${channelId} from ${msg.author?.username}`);
      const answer = await recommend({ question, context: older, env });
      try {
        await reply(channelId, answer, msg.id);
      } catch (err) {
        console.warn("reply failed:", err.message);
      }
    }
  }
}

console.log(
  `rootmc-sexi poller as app ${botAppId}, watching ${watch.length} base channel(s), every ${POLL_MS}ms`,
);
await tick();
setInterval(() => {
  tick().catch((err) => console.warn("tick:", err.message));
}, POLL_MS);

