import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WEB_PUBLIC = path.resolve(__dirname, "../../rootmc-web/public");

/** Curated public RootMC pages Sexi can cite. */
export const SITE_CATALOG = [
  { id: "wiki-hub", url: "https://rootmc.net/wiki/", local: "wiki/index.html", keywords: ["wiki", "guide", "docs", "help"] },
  { id: "wiki-economy", url: "https://rootmc.net/wiki/economy/", local: "wiki/economy/index.html", keywords: ["economy", "gold", "g ", "shop", "reserve", "loan", "tax", "baltop", "mint", "note"] },
  { id: "wiki-player", url: "https://rootmc.net/wiki/player/", local: "wiki/player/index.html", keywords: ["player", "join", "link", "howto", "new"] },
  { id: "wiki-claims", url: "https://rootmc.net/wiki/claims/", local: "wiki/claims/index.html", keywords: ["claim", "claims", "land", "chunk"] },
  { id: "wiki-territories", url: "https://rootmc.net/wiki/territories/", local: "wiki/territories/index.html", keywords: ["territory", "territories", "influence"] },
  { id: "wiki-constitution", url: "https://rootmc.net/wiki/constitution/", local: "wiki/constitution/index.html", keywords: ["constitution", "governance", "rules", "treasury"] },
  { id: "wiki-plugins", url: "https://rootmc.net/wiki/plugins/", local: "wiki/plugins/index.html", keywords: ["plugin", "plugins", "suite", "install"] },
  { id: "wiki-api", url: "https://rootmc.net/wiki/plugins/api/", local: "wiki/plugins/api/index.html", keywords: ["api", "manifest", "updater", "heartbeat"] },
  { id: "wiki-versioning", url: "https://rootmc.net/wiki/versioning/", local: "wiki/versioning/index.html", keywords: ["version", "versioning"] },
  { id: "wiki-awards", url: "https://rootmc.net/wiki/weekly-awards/", local: "wiki/weekly-awards/index.html", keywords: ["award", "weekly", "prize"] },
  { id: "thanks", url: "https://rootmc.net/thanks/", local: "thanks/index.html", keywords: ["thanks", "token", "appreciation", "redeem", "vote", "bonus"] },
  { id: "plugins-catalog", url: "https://rootmc.net/plugins/", local: "plugins/index.html", keywords: ["catalog", "download", "jar"] },
  { id: "economy-live", url: "https://rootmc.net/economy/", local: "economy/index.html", keywords: ["economy", "dashboard", "live"] },
  { id: "heads", url: "https://rootmc.net/wiki/", local: "wiki/index.html", keywords: ["head", "heads", "mobhead", "skull"] },
];

function htmlToText(html) {
  return String(html || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

function readLocal(rel) {
  const full = path.join(WEB_PUBLIC, rel);
  if (!fs.existsSync(full)) return null;
  try {
    return htmlToText(fs.readFileSync(full, "utf8"));
  } catch {
    return null;
  }
}

async function fetchRemote(url) {
  try {
    const res = await fetch(url, {
      headers: { "User-Agent": "RootMC-Sexi/0.2 (+https://rootmc.net)" },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) return null;
    return htmlToText(await res.text());
  } catch {
    return null;
  }
}

/** Score catalog pages against the question; return top snippets. */
export async function gatherSiteContext(question, { maxPages = 4, maxChars = 9000 } = {}) {
  const q = String(question || "").toLowerCase();
  const scored = SITE_CATALOG.map((page) => {
    let score = 0;
    for (const kw of page.keywords) {
      if (q.includes(kw.toLowerCase())) score += kw.length > 4 ? 3 : 2;
    }
    if (score === 0 && /wiki|site|docs|guide|how/.test(q)) score = 1;
    return { ...page, score };
  })
    .filter((p) => p.score > 0)
    .sort((a, b) => b.score - a.score);

  const picks = (scored.length ? scored : SITE_CATALOG.filter((p) => p.id === "wiki-hub" || p.id === "wiki-economy")).slice(
    0,
    maxPages,
  );

  const blocks = [];
  let used = 0;
  for (const page of picks) {
    let text = readLocal(page.local);
    if (!text || text.length < 80) {
      text = await fetchRemote(page.url);
    }
    if (!text) continue;
    const slice = text.slice(0, 2200);
    const block = `### ${page.id} (${page.url})\n${slice}`;
    if (used + block.length > maxChars) break;
    blocks.push(block);
    used += block.length;
  }

  const index = SITE_CATALOG.map((p) => `- ${p.url} [${p.keywords.slice(0, 4).join(", ")}]`).join("\n");
  return {
    pages: picks.map((p) => p.url),
    brief: `Public RootMC resource index:\n${index}\n\nPulled page text:\n${blocks.join("\n\n") || "(none pulled)"}`,
  };
}

import { grokToken, SEXI_GROK_MODEL } from "./config.mjs";
import { SEXI_HARD_RULES, SEXI_PERSONA } from "./persona.mjs";
import { gatherSiteContext } from "./siteContext.mjs";
import { scrubPublicReply } from "./scrub.mjs";

/**
 * Chatty Grok brain — wiki/site aware. Not for deep repo work.
 */
export async function grokRecommend({ question, context = "", env }) {
  const key = grokToken(env || {});
  if (!key) {
    return { ok: false, reason: "missing_xai_key", text: null };
  }

  const site = await gatherSiteContext(question);
  const system = `${SEXI_PERSONA}

${SEXI_HARD_RULES}

Mode: **Discord hangout / idea lab** (Grok).
- Use the wiki/site excerpts below to ground answers. Cite public https://rootmc.net links when useful.
- Riff on proposals, balance, player vibes. Be conversational.
- If they ask you to implement, dig into plugin source, ship jars, or do hard coding work, tell them you'll handle that when you're **back at the Root Server** (Cursor). Don't fake that you edited code.
- Don't invent live economy numbers — point at wiki /economy pages.`;

  const user = `Discord thread/context:
${String(context || "(none)").slice(0, 3500)}

Player/staff ask:
${String(question).trim()}

Site/wiki pack (may be partial):
${site.brief.slice(0, 10000)}

Write Sexi's Discord reply now.`;

  try {
    const res = await fetch("https://api.x.ai/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: SEXI_GROK_MODEL,
        temperature: 0.75,
        max_tokens: 750,
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
      }),
    });
    const text = await res.text();
    if (!res.ok) {
      console.warn("grokRecommend", res.status, text.slice(0, 200));
      return { ok: false, reason: `http_${res.status}`, text: null };
    }
    const data = JSON.parse(text);
    const reply = data?.choices?.[0]?.message?.content?.trim();
    if (!reply) return { ok: false, reason: "empty", text: null };
    return {
      ok: true,
      reason: "ok",
      text: scrubPublicReply(reply),
      pages: site.pages,
    };
  } catch (err) {
    console.warn("grokRecommend:", err?.message || err);
    return { ok: false, reason: "error", text: null };
  }
}

import { grokToken } from "./config.mjs";
