/** Phrases that mean: escalate to Cursor on the Root Server (repo-hard work). */
export function wantsRootServer(question) {
  const q = String(question || "").toLowerCase();
  if (String(process.env.SEXI_FORCE_CURSOR || "").trim() === "1") return true;
  return (
    /\broot\s*server\b/.test(q) ||
    /\bback\s+at\s+the\s+root\b/.test(q) ||
    /\b(use|ask|call)\s+cursor\b/.test(q) ||
    /\bdeep\s*(dive|work|look)\b/.test(q) ||
    /\b(implement|code\s+this|build\s+it|ship\s+it|write\s+the\s+plugin|dig\s+into\s+(the\s+)?(repo|code|source))\b/.test(
      q,
    ) ||
    /\b(check|read|scan)\s+(the\s+)?(repo|codebase|source|plugins?)\b/.test(q) ||
    /\bhard\s*mode\b/.test(q)
  );
}

export function heuristicRecommend(question, context = "") {
  const q = `${question}\n${context}`.toLowerCase();
  const bits = [];
  bits.push("**Sexi:** okay sooo —");
  if (/quest|challenge|crate|key/.test(q)) {
    bits.push(
      "quests should stay **optional** and cute, not a wallet grind. Rewards = Appreciation Tokens / cosmetics vibes — fluff crates > economy bombs. keep that drip collectible.",
    );
  }
  if (/skill|mcmmo|prestige|level/.test(q)) {
    bits.push(
      "don't wipe veteran levels babes — **1:1 migrate**. milestone flavor every ~25 levels is fire; prestige is the long cozy grind. shrinking Retro caps just to feel 'cleaner' is mid.",
    );
  }
  if (/token|appreciation|redeem|vote/.test(q)) {
    bits.push(
      "tokens are already the soft-reward lane — vote /bonus / trade / right-click redeem. odds live at https://rootmc.net/thanks/ ✨",
    );
  }
  if (/shop|market|economy|gold/.test(q)) {
    bits.push(
      "player shops set the vibe on prices; mint-peg gold stuff stays out of shops. treasury-backed rewards > printing Gold. peek https://rootmc.net/wiki/economy/ — keep it cozy not broken.",
    );
  }
  if (bits.length === 1) {
    bits.push(
      "spill a little more — quests, skills, economy, tokens, towns? i'll give you a real rec. wiki hub is https://rootmc.net/wiki/",
    );
  }
  bits.push("_brains offline rn — soft fallback_");
  return scrubPublicReply(bits.join("\n"));
}

/**
 * Default: Grok + wiki/site (chatty idea lab).
 * Root Server phrases → Cursor local agent (harder repo work).
 */
export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) {
    return scrubPublicReply(
      "hey hey — ask me about RootMC vibes, wiki stuff, or a proposal idea. if you need me deep in the code, say **Root Server** and i'll clock in ✨",
    );
  }

  const brain = String(process.env.SEXI_BRAIN || env?.SEXI_BRAIN || "grok")
    .trim()
    .toLowerCase();

  if (wantsRootServer(q) || brain === "cursor") {
    console.log("Sexi → Root Server (Cursor)");
    const cursor = await cursorRecommend({ question: q, context, env, deep: true });
    if (cursor.ok && cursor.text) return cursor.text;
    console.warn("Sexi cursor:", cursor.reason);
    // Fall through to Grok so she can still talk
  }

  if (brain !== "heuristic") {
    const grok = await grokRecommend({ question: q, context, env });
    if (grok.ok && grok.text) return grok.text;
    console.warn("Sexi grok:", grok.reason);
  }

  // Last resort: Cursor even for chat if Grok failed and key exists
  if (!wantsRootServer(q) && grokToken(env || {})) {
    // already tried grok
  } else {
    const cursor = await cursorRecommend({ question: q, context, env, deep: false });
    if (cursor.ok && cursor.text) return cursor.text;
  }

  return heuristicRecommend(q, context);
}

