  const url = new URL(req.url || "/", `http://127.0.0.1:${SEXI_PORT}`);
  res.setHeader("Content-Type", "application/json; charset=utf-8");

  if (req.method === "GET" && url.pathname === "/health") {
    const hasGrok = Boolean(grokToken(env));
    const hasCursor = Boolean(cursorApiKey(env));
    const preferred = String(process.env.SEXI_BRAIN || env.SEXI_BRAIN || "grok").toLowerCase();
