/**
 * Build Discord conversation context so Sexi remembers the player's recent lines.
 * Discord message arrays are newest-first.
 */

const PLAYER_LINES = Number(process.env.SEXI_PLAYER_CONTEXT || 12);
const THREAD_LINES = Number(process.env.SEXI_THREAD_CONTEXT || 10);
const SEXI_LINES = Number(process.env.SEXI_OWN_CONTEXT || 6);

function line(m) {
  const name = m.author?.username || m.author?.global_name || "unknown";
  const text = String(m.content || "").replace(/\s+/g, " ").trim();
  if (!text) return null;
  return `${name}: ${text}`;
}

/**
 * @param {object} opts
 * @param {object} opts.trigger - triggering message
 * @param {object[]} opts.messages - channel messages newest-first
 * @param {string} opts.sexiBotId
 */
export function buildPlayerContext({ trigger, messages, sexiBotId }) {
  const list = Array.isArray(messages) ? messages : [];
  const playerId = trigger?.author?.id;
  const parts = [];

  // Reply-to target if present
  const refId = trigger?.message_reference?.message_id;
  if (refId) {
    const ref = list.find((m) => m.id === refId);
    if (ref) {
      const l = line(ref);
      if (l) parts.push(`(replying to) ${l}`);
    }
  }

  // This player's recent messages (including trigger), chronological
  const fromPlayer = list
    .filter((m) => m.author?.id === playerId && m.content)
    .slice(0, PLAYER_LINES)
    .reverse()
    .map(line)
    .filter(Boolean);

  if (fromPlayer.length) {
    parts.push("Recent messages from this player (oldest → newest):");
    parts.push(...fromPlayer);
  }

  // Sexi's own recent replies in-channel (so she doesn't contradict herself)
  const fromSexi = list
    .filter((m) => m.author?.id === sexiBotId && m.content)
    .slice(0, SEXI_LINES)
    .reverse()
    .map(line)
    .filter(Boolean);
  if (fromSexi.length) {
    parts.push("Your recent replies here:");
    parts.push(...fromSexi);
  }

  // Short mixed thread window around the chat
  const thread = list
    .filter((m) => m.id !== trigger?.id && m.content)
    .slice(0, THREAD_LINES)
    .reverse()
    .map(line)
    .filter(Boolean);
  if (thread.length) {
    parts.push("Recent thread (others included):");
    parts.push(...thread);
  }

  return parts.join("\n").slice(0, 6000);
}

/** In-memory rolling history per channel+player (survives between polls). */
const memory = new Map();
const MEMORY_MAX = 20;

export function rememberPlayerLine(channelId, playerId, username, content) {
  if (!channelId || !playerId || !content) return;
  const key = `${channelId}:${playerId}`;
  const arr = memory.get(key) || [];
  arr.push({ username, content: String(content).slice(0, 500), at: Date.now() });
  while (arr.length > MEMORY_MAX) arr.shift();
  memory.set(key, arr);
}

export function memoryContext(channelId, playerId) {
  const key = `${channelId}:${playerId}`;
  const arr = memory.get(key);
  if (!arr?.length) return "";
  return (
    "Earlier in this channel from this player (memory):\n" +
    arr.map((r) => `${r.username}: ${r.content}`).join("\n")
  );
}

import {
  loadEnv,
  botToken,
  sexiBotAppId,
  DISCORD_API,
  DEFAULT_WATCH_CHANNELS,
} from "./config.mjs";
import {
  extractQuestion,
  looksLikeSexiTrigger,
  recommend,
} from "./recommend.mjs";
import {
  buildPlayerContext,
  rememberPlayerLine,
  memoryContext,
} from "./playerContext.mjs";

const env = await loadEnv();
const token = botToken(env);
const botAppId = sexiBotAppId(env);
if (token.length < 40) {
  console.error("SEXI_DISCORD_BOT_TOKEN missing — poller idle");
  process.exit(1);
}
if (!botAppId) {
  console.error("SEXI_DISCORD_APPLICATION_ID / CLIENT_ID missing — poller idle");
  process.exit(1);
}

const headers = {
  Authorization: `Bot ${token}`,
  "User-Agent": "RootMC-Sexi/0.3",
  "Content-Type": "application/json",
};

const seen = new Set();
const watch = (process.env.SEXI_WATCH_CHANNELS || DEFAULT_WATCH_CHANNELS.join(","))
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

const POLL_MS = Number(process.env.SEXI_POLL_MS || 12_000);
const FETCH_LIMIT = Number(process.env.SEXI_FETCH_LIMIT || 50);

async function fetchJson(path, init = {}) {
  const res = await fetch(`${DISCORD_API}${path}`, {
    ...init,
    headers: { ...headers, ...(init.headers || {}) },
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${path} ${res.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : null;
}

async function channelTargets() {
  const out = new Set(watch);
  if (watch.includes("1526664180491358419")) {
    try {
      const active = await fetchJson(`/guilds/1516108585740800042/threads/active`);
      for (const t of active?.threads || []) {
        if (t.parent_id === "1526664180491358419") out.add(t.id);
      }
    } catch (err) {
      console.warn("active threads:", err.message);
    }
  }
  return [...out];
}

async function reply(channelId, content, refId) {
  return fetchJson(`/channels/${channelId}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: String(content).slice(0, 2000),
      message_reference: refId ? { message_id: refId } : undefined,
      allowed_mentions: { parse: [] },
    }),
  });
}

/** Quietly index recent human lines so memory stays warm even without a trigger. */
function warmMemory(channelId, messages) {
  for (const m of [...(messages || [])].reverse()) {
    if (!m?.author || m.author.bot) continue;
    if (m.author.id === botAppId) continue;
    if (!m.content?.trim()) continue;
    rememberPlayerLine(channelId, m.author.id, m.author.username, m.content);
  }
}

async function tick() {
  const channels = await channelTargets();
  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=${FETCH_LIMIT}`);
    } catch {
      continue;
    }

    warmMemory(channelId, messages);

    for (const msg of messages || []) {
      if (!msg?.id || seen.has(msg.id)) continue;
      seen.add(msg.id);
      if (seen.size > 5000) {
        const drop = [...seen].slice(0, 1000);
        for (const id of drop) seen.delete(id);
      }
      if (msg.author?.bot) continue;
      if (msg.author?.id === botAppId) continue;
      if (!looksLikeSexiTrigger(msg.content, botAppId)) continue;

      const question = extractQuestion(msg.content) || "continue our conversation — what do you think?";
      const live = buildPlayerContext({
        trigger: msg,
        messages,
        sexiBotId: botAppId,
      });
      const mem = memoryContext(channelId, msg.author.id);
      const context = [mem, live].filter(Boolean).join("\n\n").slice(0, 6500);

      console.log(`sexi trigger in ${channelId} from ${msg.author?.username}`);
      const answer = await recommend({ question, context, env });
      try {
        await reply(channelId, answer, msg.id);
        rememberPlayerLine(channelId, botAppId, "Sexi", answer);
      } catch (err) {
        console.warn("reply failed:", err.message);
      }
    }
  }
}

console.log(
  `rootmc-sexi poller as app ${botAppId}, watching ${watch.length} base channel(s), every ${POLL_MS}ms (player context on)`,
);
await tick();
setInterval(() => {
  tick().catch((err) => console.warn("tick:", err.message));
}, POLL_MS);

