import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "../../..");

function safeRead(file, max = 8000) {
  try {
    if (!fs.existsSync(file) || !fs.statSync(file).isFile()) return null;
    const raw = fs.readFileSync(file, "utf8");
    // Drop obvious secret-ish lines
    const cleaned = raw
      .split(/\r?\n/)
      .filter((line) => !/(password|token|secret|api[_-]?key|jdbc:|Bearer\s)/i.test(line))
      .join("\n");
    return cleaned.slice(-max);
  } catch {
    return null;
  }
}

function listNewest(dir, pred, limit = 5) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs
      .readdirSync(dir)
      .map((name) => ({ name, full: path.join(dir, name) }))
      .filter((e) => {
        try {
          return pred(e.full, e.name);
        } catch {
          return false;
        }
      })
      .map((e) => ({ ...e, mtime: fs.statSync(e.full).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, limit);
  } catch {
    return [];
  }
}

function findLatestLogs() {
  const candidates = [];
  const roots = [
    path.join(ROOT, "Server Handoffs", "1. RootMC - Claims", "logs"),
    path.join(ROOT, "Server Handoffs", "2. RootMC - Towny", "logs"),
    path.join(ROOT, "Server Handoffs", "3. RootMC - Test Server", "logs"),
    path.join(ROOT, "Server Live Backups"),
  ];
  for (const dir of roots) {
    for (const hit of listNewest(
      dir,
      (full, name) =>
        /\.(log|txt)$/i.test(name) || name === "latest.log" || /log/i.test(name),
      8,
    )) {
      candidates.push(hit);
    }
    // nested */logs/latest.log under live backups (shallow)
    try {
      if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) continue;
      for (const name of fs.readdirSync(dir).slice(0, 40)) {
        const nested = path.join(dir, name, "logs", "latest.log");
        if (fs.existsSync(nested)) {
          candidates.push({ name: `${name}/logs/latest.log`, full: nested, mtime: fs.statSync(nested).mtimeMs });
        }
      }
    } catch {
      /* ignore */
    }
  }
  return candidates.sort((a, b) => b.mtime - a.mtime).slice(0, 3);
}

/**
 * Pull local workspace snippets Sexi can discuss (scrubbed).
 */
export function gatherLocalContext(question = "") {
  const q = String(question || "").toLowerCase();
  const blocks = [];
  const wantLogs = /log|weird|error|crash|exception|console|file|access|workspace|repo/.test(q);
  const wantHeads = /head|mobhead|skull/.test(q);
  const wantThanks = /token|thanks|appreciation/.test(q);

  // Recent plugin changelogs
  const changeDir = path.join(ROOT, "Change Logs", "plugins");
  const changelogs = listNewest(changeDir, (full, name) => name.endsWith(".md"), 6);
  for (const c of changelogs.slice(0, wantLogs || wantHeads || wantThanks ? 4 : 2)) {
    const text = safeRead(c.full, 2500);
    if (text) blocks.push(`### changelog ${c.name}\n${text}`);
  }

  // root-heads / appreciation if relevant
  const extras = [];
  if (wantHeads) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-heads.md"));
    extras.push(
      path.join(ROOT, "Plugin Building", "Minecraft", "plugins", "root-heads", "src", "main", "resources", "root-heads.yml"),
    );
  }
  if (wantThanks) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-appreciation.md"));
  }
  for (const file of extras) {
    const text = safeRead(file, 3000);
    if (text) blocks.push(`### ${path.basename(file)}\n${text}`);
  }

  // Server logs (tail)
  if (wantLogs || /look|check|see|scan|read/.test(q)) {
    for (const log of findLatestLogs()) {
      const text = safeRead(log.full, 4500);
      if (text) {
        blocks.push(`### log tail (${log.name})\n${text}`);
      }
    }
  }

  // Sexi / workspace README crumbs
  const readme = safeRead(path.join(ROOT, "Web Files", "rootmc-sexi", "README.md"), 1500);
  if (readme) blocks.push(`### sexi README\n${readme}`);

  const joined = blocks.join("\n\n").slice(0, 14000);
  return {
    hasFiles: blocks.length > 0,
    brief:
      blocks.length > 0
        ? `Local RootMC workspace pack (scrubbed; summarize, don't quote secrets/paths):\n${joined}`
        : "Local pack empty — no matching files found.",
  };
}

