import fs from "node:fs";
import path from "node:path";
import { AVA_HANDOFF } from "./config.mjs";

function dataDir() {
  const root = AVA_HANDOFF || path.resolve("D:\\.1 Work Stations\\RootMC\\Server Handoffs\\Ava Ivy");
  const dir = path.join(root, "data");
  fs.mkdirSync(dir, { recursive: true });
  fs.mkdirSync(path.join(root, "uploads"), { recursive: true });
  fs.mkdirSync(path.join(root, "plans"), { recursive: true });
  return dir;
}

function readJson(file, fallback) {
  try {
    if (!fs.existsSync(file)) return fallback;
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return fallback;
  }
}

function writeJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(value, null, 2), "utf8");
}

export function storePaths() {
  const dir = dataDir();
  return {
    dir,
    seen: path.join(dir, "seen.json"),
    watermark: path.join(dir, "watermark.json"),
    hush: path.join(dir, "hush.json"),
    lastReply: path.join(dir, "last-reply.json"),
  };
}

export function loadSeen() {
  const raw = readJson(storePaths().seen, { ids: [] });
  return new Set(Array.isArray(raw.ids) ? raw.ids : []);
}

export function saveSeen(seen) {
  const ids = [...seen];
  if (ids.length > 8000) ids.splice(0, ids.length - 6000);
  writeJson(storePaths().seen, { ids, updatedAt: Date.now() });
}

export function loadWatermark() {
  return readJson(storePaths().watermark, { channels: {}, shutdownAt: 0 });
}

export function saveWatermark(wm) {
  writeJson(storePaths().watermark, { ...wm, updatedAt: Date.now() });
}

export function markShutdown(channelLatestMap) {
  const wm = loadWatermark();
  wm.shutdownAt = Date.now();
  wm.channels = { ...(wm.channels || {}), ...channelLatestMap };
  saveWatermark(wm);
}

export function isHushed() {
  const h = readJson(storePaths().hush, { muted: false });
  return Boolean(h.muted);
}

export function setHushed(muted, reason = "") {
  writeJson(storePaths().hush, { muted: Boolean(muted), reason, at: Date.now() });
}

export function lastReplyFor(channelId) {
  const all = readJson(storePaths().lastReply, {});
  return all[channelId] || "";
}

export function setLastReply(channelId, text) {
  const all = readJson(storePaths().lastReply, {});
  all[channelId] = String(text || "").slice(0, 500);
  writeJson(storePaths().lastReply, all);
}

export function nearDuplicate(a, b) {
  const norm = (s) =>
    String(s || "")
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 280);
  const x = norm(a);
  const y = norm(b);
  if (!x || !y) return false;
  if (x === y) return true;
  return x.includes(y.slice(0, 80)) || y.includes(x.slice(0, 80));
}

import { cursorApiKey } from "./config.mjs";
import { cursorRecommend } from "./cursorBrain.mjs";
import { scrubPublicReply } from "./scrub.mjs";
import { gatherSiteContext } from "./siteContext.mjs";
import { gatherLocalContext } from "./localContext.mjs";

export { scrubPublicReply } from "./scrub.mjs";
export { stripForbiddenMentions } from "./scrub.mjs";

export function wantsRootServer(question) {
  const q = String(question || "").toLowerCase();
  if (String(process.env.SEXI_FORCE_CURSOR || "").trim() === "1") return true;
  return (
    /\broot\s*server\b/.test(q) ||
    /\b(implement|code\s+this|build\s+it|ship\s+it|dig\s+into\s+(the\s+)?(repo|code|source))\b/.test(q) ||
    /\b(check|read|scan|look\s+at)\s+(the\s+)?(repo|codebase|source|plugins?|logs?)\b/.test(q)
  );
}

export function isHushCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    /\b(stop|hush|quiet|sleep|go\s+offline|shut\s+up)\b/.test(q) &&
    /\b(ava|sexi)\b/.test(q)
  ) || /^(stop|hush|quiet)\s*(ava|sexi)?[!?.]*$/i.test(q.trim());
}

export function isWakeCommand(content) {
  const q = String(content || "").toLowerCase();
  return /\b(wake|come\s+back|you'?re\s+active|unmute)\b/.test(q) && /\b(ava|sexi)\b/.test(q);
}

export function heuristicRecommend(question) {
  const q = String(question || "").toLowerCase();
  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }
  return scrubPublicReply(
    "Cursor's offline on my end — drop the question again when the Root Server's up, or leave notes in my handoff folder.",
  );
}

/**
 * Cursor-only brain. Wiki + local packs go into the Cursor prompt.
 */
export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) {
    return scrubPublicReply("What's up? Wiki, design, logs, proposals — fire away. Give me a sec when you ping; I think before I talk.");
  }

  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans|(come|get)\s+over\s+here/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }

  if (!cursorApiKey(env || {})) {
    return heuristicRecommend(q);
  }

  const site = await gatherSiteContext(q);
  const local = gatherLocalContext(`${q}\n${context}`);
  const packed = [
    context,
    site.brief.slice(0, 6000),
    local.brief.slice(0, 10000),
  ]
    .filter(Boolean)
    .join("\n\n");

  const deep = wantsRootServer(q) || local.hasFiles;
  const cursor = await cursorRecommend({
    question: q,
    context: packed,
    env,
    deep,
  });
  if (cursor.ok && cursor.text) return cursor.text;
  console.warn("Ava cursor:", cursor.reason);
  return heuristicRecommend(q);
}

/** Clear address to Ava — not mid-sentence gossip. */
export function looksLikeSexiTrigger(contentOrMsg, botUserId) {
  if (contentOrMsg && typeof contentOrMsg === "object") {
    const msg = contentOrMsg;
    if (botUserId && Array.isArray(msg.mentions)) {
      if (msg.mentions.some((u) => String(u?.id) === String(botUserId))) return true;
    }
    if (msg.message_reference?.message_id && botUserId) {
      // reply-to handled by poller when ref author is Ava
    }
    return looksLikeSexiTrigger(msg.content || "", botUserId);
  }
  const raw = String(contentOrMsg || "").trim();
  if (!raw) return false;
  if (botUserId && (raw.includes(`<@${botUserId}>`) || raw.includes(`<@!${botUserId}>`))) {
    return true;
  }
  if (/\b@?sexi\b/i.test(raw) || /sexi\s+assistant/i.test(raw)) return true;
  // "Ava" / "Ava Ivy" as address — start of message, or short ping
  if (/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?([,:!?]|\s|$)/i.test(raw)) {
    return true;
  }
  if (/^ava(\s+ivy)?[!?.]*$/i.test(raw)) return true;
  return false;
}

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/\b@?sexi\b/gi, "")
    .replace(/sexi\s+assistant/gi, "")
    .replace(/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?[,:!]?\s*/i, "")
    .trim();
}

import {
  loadEnv,
  botToken,
  sexiBotAppId,
  DISCORD_API,
  watchChannels,
} from "./config.mjs";
import {
  extractQuestion,
  looksLikeSexiTrigger,
  recommend,
  isHushCommand,
  isWakeCommand,
} from "./recommend.mjs";
import {
  buildPlayerContext,
  rememberPlayerLine,
  memoryContext,
} from "./playerContext.mjs";
import { pickAck } from "./persona.mjs";
import {
  loadSeen,
  saveSeen,
  loadWatermark,
  saveWatermark,
  markShutdown,
  isHushed,
  setHushed,
  lastReplyFor,
  setLastReply,
  nearDuplicate,
  storePaths,
} from "./store.mjs";

const env = await loadEnv();
const token = botToken(env);
const botAppId = sexiBotAppId(env);
if (token.length < 40) {
  console.error("SEXI_DISCORD_BOT_TOKEN missing — poller idle");
  process.exit(1);
}
if (!botAppId) {
  console.error("SEXI_DISCORD_APPLICATION_ID missing — poller idle");
  process.exit(1);
}

const headers = {
  Authorization: `Bot ${token}`,
  "User-Agent": "RootMC-Ava/0.4",
  "Content-Type": "application/json",
};

const seen = loadSeen();
const watch = watchChannels(env);
const ANNOUNCE_CHANNEL =
  process.env.AVA_ANNOUNCE_CHANNEL ||
  env.AVA_ANNOUNCE_CHANNEL ||
  "1516108586307158088";

const POLL_MS = Number(process.env.SEXI_POLL_MS || 12_000);
const FETCH_LIMIT = Number(process.env.SEXI_FETCH_LIMIT || 50);
const busyChannels = new Set();
let live = false; // false until boot handshake finishes

async function fetchJson(path, init = {}) {
  const res = await fetch(`${DISCORD_API}${path}`, {
    ...init,
    headers: { ...headers, ...(init.headers || {}) },
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${path} ${res.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : null;
}

async function channelTargets() {
  const out = new Set(watch);
  if (watch.includes("1526664180491358419")) {
    try {
      const active = await fetchJson(`/guilds/1516108585740800042/threads/active`);
      for (const t of active?.threads || []) {
        if (t.parent_id === "1526664180491358419") out.add(t.id);
      }
    } catch (err) {
      console.warn("active threads:", err.message);
    }
  }
  return [...out];
}

async function reply(channelId, content, refId) {
  return fetchJson(`/channels/${channelId}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: String(content).slice(0, 2000),
      message_reference: refId ? { message_id: refId } : undefined,
      allowed_mentions: { parse: [] },
    }),
  });
}

function warmMemory(channelId, messages) {
  for (const m of [...(messages || [])].reverse()) {
    if (!m?.author || m.author.bot) continue;
    if (m.author.id === botAppId) continue;
    if (!m.content?.trim()) continue;
    rememberPlayerLine(channelId, m.author.id, m.author.username, m.content);
  }
}

function markSeen(id) {
  if (!id) return;
  seen.add(id);
  if (seen.size > 8000) {
    const drop = [...seen].slice(0, 2000);
    for (const x of drop) seen.delete(x);
  }
}

function snowflakeTime(id) {
  try {
    return Number((BigInt(id) >> 22n) + 1420070400000n);
  } catch {
    return 0;
  }
}

async function bootHandshake() {
  storePaths(); // ensure uploads/plans/data exist
  const wm = loadWatermark();
  const channels = await channelTargets();
  const bullets = [];
  const latestMap = {};

  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=${FETCH_LIMIT}`);
    } catch {
      continue;
    }
    if (!Array.isArray(messages) || !messages.length) continue;
    latestMap[channelId] = messages[0].id;
    const floorId = wm.channels?.[channelId];
    const floorTs = wm.shutdownAt || 0;

    for (const m of messages) {
      markSeen(m.id);
      if (m.author?.bot) continue;
      const ts = snowflakeTime(m.id);
      const isNew =
        floorId ? BigInt(m.id) > BigInt(floorId) : floorTs ? ts > floorTs : false;
      if (!isNew) continue;
      const text = String(m.content || "").trim();
      if (!text) continue;
      const hit =
        looksLikeSexiTrigger(m, botAppId) ||
        /\b(ava|sexi)\b/i.test(text);
      if (hit) {
        bullets.push(`• **${m.author.username}**: ${text.slice(0, 160)}`);
      }
    }
    warmMemory(channelId, messages);
  }

  saveSeen(seen);
  saveWatermark({ channels: latestMap, shutdownAt: Date.now() });

  const summary =
    bullets.length > 0
      ? [
          "**While I was out — quick catch-up:**",
          ...bullets.slice(0, 12),
          bullets.length > 12 ? `_…+${bullets.length - 12} more_` : null,
        ]
          .filter(Boolean)
          .join("\n")
      : "**While I was out:** nothing directed at me worth replaying. All good.";

  const apology = [
    "Sorry I was asleep — that dump above is the sync, not me spam-replying old pings.",
    "I'm **Ava Ivy**, back and active. Lead-dev brain + gamer-girl mouth.",
    "Ping me with @Sexi / Ava — I'll say *give me a sec* while I think, then answer once.",
  ].join("\n");

  try {
    await reply(ANNOUNCE_CHANNEL, summary);
    await reply(ANNOUNCE_CHANNEL, apology);
  } catch (err) {
    console.warn("boot announce failed:", err.message);
  }

  live = true;
  console.log("Ava boot handshake done — live");
}

async function handleTrigger(channelId, msg, messages) {
  if (busyChannels.has(channelId)) return;
  busyChannels.add(channelId);
  try {
    const question =
      extractQuestion(msg.content) || "you pinged me — what's up?";
    const liveCtx = buildPlayerContext({
      trigger: msg,
      messages,
      sexiBotId: botAppId,
    });
    const mem = memoryContext(channelId, msg.author.id);
    const context = [mem, liveCtx].filter(Boolean).join("\n\n").slice(0, 6500);

    const ack = pickAck();
    try {
      await reply(channelId, ack, msg.id);
    } catch (err) {
      console.warn("ack failed:", err.message);
    }

    console.log(`ava trigger in ${channelId} from ${msg.author?.username}`);
    const answer = await recommend({ question, context, env });
    if (nearDuplicate(answer, lastReplyFor(channelId))) {
      console.log("skip near-duplicate answer");
      return;
    }
    await reply(channelId, answer, msg.id);
    setLastReply(channelId, answer);
    rememberPlayerLine(channelId, botAppId, "Ava", answer);
  } finally {
    busyChannels.delete(channelId);
    saveSeen(seen);
  }
}

async function tick() {
  if (!live) return;
  const channels = await channelTargets();
  const latestMap = {};

  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=${FETCH_LIMIT}`);
    } catch {
      continue;
    }
    if (Array.isArray(messages) && messages[0]?.id) {
      latestMap[channelId] = messages[0].id;
    }

    warmMemory(channelId, messages);

    // Process oldest-first among new triggers so order feels natural
    const batch = [...(messages || [])].reverse();
    for (const msg of batch) {
      if (!msg?.id || seen.has(msg.id)) continue;
      markSeen(msg.id);
      if (msg.author?.bot) continue;
      if (msg.author?.id === botAppId) continue;

      if (isHushCommand(msg.content)) {
        setHushed(true, "user hush");
        try {
          await reply(channelId, "Got it — going quiet. Ping me when you want me back.", msg.id);
        } catch {
          /* ignore */
        }
        continue;
      }
      if (isWakeCommand(msg.content)) {
        setHushed(false, "user wake");
        try {
          await reply(channelId, "I'm up. Give me a sec when you ask something — I think first.", msg.id);
        } catch {
          /* ignore */
        }
        continue;
      }

      if (isHushed()) continue;
      if (!looksLikeSexiTrigger(msg, botAppId)) continue;

      await handleTrigger(channelId, msg, messages);
    }
  }

  if (Object.keys(latestMap).length) {
    const wm = loadWatermark();
    saveWatermark({ ...wm, channels: { ...(wm.channels || {}), ...latestMap } });
  }
}

function shutdown() {
  console.log("Ava shutting down — watermark");
  // best-effort; channel map refreshed each tick
  markShutdown(loadWatermark().channels || {});
  saveSeen(seen);
  process.exit(0);
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

console.log(
  `Ava Ivy poller as app ${botAppId}, watching ${watch.length} channel(s), every ${POLL_MS}ms`,
);
console.log(`handoff data: ${storePaths().dir}`);

await bootHandshake();
setInterval(() => {
  tick().catch((err) => console.warn("tick:", err.message));
}, POLL_MS);

