import path from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, CursorAgentError } from "@cursor/sdk";
import { cursorApiKey, SEXI_MODEL, SEXI_WORKSPACE } from "./config.mjs";
import { SEXI_HARD_RULES, SEXI_PERSONA } from "./persona.mjs";
import { scrubPublicReply } from "./scrub.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** RootMC workspace root (plugins, web, docs). */
export function workspaceRoot() {
  if (SEXI_WORKSPACE) return SEXI_WORKSPACE;
  return path.resolve(__dirname, "../../..");
}

let queue = Promise.resolve();

function enqueue(fn) {
  const run = queue.then(fn, fn);
  queue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

/**
 * Root Server mode — local Cursor agent on the RootMC workspace.
 * Prefer fast replies; deep dig only when asked / packs need file inspection.
 */
export async function cursorRecommend({ question, context = "", env, deep = false }) {
  const apiKey = cursorApiKey(env || {});
  if (!apiKey) {
    return { ok: false, reason: "missing_cursor_api_key", text: null };
  }

  const cwd = workspaceRoot();
  const modeNote = deep
    ? `Mode: Root Server deep dig.
Use attached packs first. Only inspect extra files if the packs don't answer.
OUTPUT ONLY a Discord reply — accurate summary, no secret dumps, no raw disk paths, no deploy steps.
Never name other AIs or vendors — say Root Server if you must.
If you'd edit code, describe the change; Alex executes.`
    : `Mode: Root Server quick assist.
Answer from the attached packs + question. Do NOT wander the repo unless the packs are empty/irrelevant.
OUTPUT ONLY a Discord reply. Accuracy > vibes. Never name other AIs.`;

  const prompt = `${SEXI_PERSONA}

${SEXI_HARD_RULES}

${modeNote}

Quality bar:
- Be correct. Wrong confidence is worse than "not sure".
- Be fast to read: answer first, then one link or next step.
- Stay in Ava's voice.

Thread/context (Discord — includes this player's recent messages; stay in continuity):
${String(context || "(none)").slice(0, 5500)}

Question (may continue prior chat):
${String(question).trim()}

Write Ava's Discord reply now.`;

  return enqueue(async () => {
    const tryPrompt = async (withSandbox) =>
      Agent.prompt(prompt, {
        apiKey,
        model: {
          id: SEXI_MODEL,
          // Prefer fast always; deep still uses non-fast for harder digs
          params: [{ id: "fast", value: deep ? "false" : "true" }],
        },
        local: {
          cwd,
          settingSources: [],
          autoReview: true,
          ...(withSandbox ? { sandboxOptions: { enabled: true } } : {}),
        },
      });

    try {
      let result;
      try {
        result = await tryPrompt(true);
      } catch (err) {
        const msg = err instanceof CursorAgentError ? err.message : String(err?.message || err);
        if (!/sandbox/i.test(msg)) throw err;
        console.warn("cursor sandbox unsupported — retrying without sandbox");
        result = await tryPrompt(false);
      }

      if (result.status === "error") {
        console.warn("cursor run error", result.id, result.error?.message || result.error);
        return { ok: false, reason: "run_error", text: null, runId: result.id };
      }

      const raw = String(result.result || "").trim();
      if (!raw) {
        return { ok: false, reason: "empty_result", text: null, runId: result.id };
      }

      return {
        ok: true,
        reason: "ok",
        text: scrubPublicReply(raw),
        runId: result.id,
        agentId: result.agentId,
      };
    } catch (err) {
      const msg = err instanceof CursorAgentError ? err.message : String(err?.message || err);
      console.warn("cursorRecommend:", msg);
      return {
        ok: false,
        reason: err instanceof CursorAgentError ? "startup_error" : "unknown_error",
        text: null,
      };
    }
  });
}

import { cursorApiKey } from "./config.mjs";
import { cursorRecommend } from "./cursorBrain.mjs";
import { scrubPublicReply } from "./scrub.mjs";
import { gatherSiteContext } from "./siteContext.mjs";
import { gatherLocalContext } from "./localContext.mjs";

export { scrubPublicReply } from "./scrub.mjs";
export { stripForbiddenMentions } from "./scrub.mjs";

export function wantsRootServer(question) {
  const q = String(question || "").toLowerCase();
  if (String(process.env.SEXI_FORCE_CURSOR || "").trim() === "1") return true;
  return (
    /\broot\s*server\b/.test(q) ||
    /\b(implement|code\s+this|build\s+it|ship\s+it|dig\s+into\s+(the\s+)?(repo|code|source))\b/.test(q) ||
    /\b(check|read|scan|look\s+at|verify|find)\s+(the\s+)?(repo|codebase|source|plugins?|logs?|files?)\b/.test(q) ||
    /\b(why\s+(is|did|does)|stack\s*trace|exception|crash|npe)\b/.test(q)
  );
}

export function isHushCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    (/\b(stop|hush|quiet|sleep|go\s+offline|shut\s+up)\b/.test(q) &&
      /\b(ava|sexi)\b/.test(q)) ||
    /^(stop|hush|quiet)\s*(ava|sexi)?[!?.]*$/i.test(q.trim())
  );
}

export function isWakeCommand(content) {
  const q = String(content || "").toLowerCase();
  return /\b(wake|come\s+back|you'?re\s+active|unmute)\b/.test(q) && /\b(ava|sexi)\b/.test(q);
}

export function heuristicRecommend(question) {
  const q = String(question || "").toLowerCase();
  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }
  return scrubPublicReply(
    "I'm a bit offline on the deep-dig side — ask again when the Root Server's up, or leave notes in my handoff folder.",
  );
}

/**
 * Cursor-only brain. Wiki + local packs go into the Cursor prompt.
 * Pack gather is parallel; deep dig only when needed (speed default).
 */
export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) {
    return scrubPublicReply(
      "What's up? Wiki, design, logs, proposals — fire away. Give me a sec when you ping; I think before I talk.",
    );
  }

  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans|(come|get)\s+over\s+here/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }

  if (!cursorApiKey(env || {})) {
    return heuristicRecommend(q);
  }

  const [site, local] = await Promise.all([
    gatherSiteContext(q, { maxPages: 3, maxChars: 6500 }),
    Promise.resolve(gatherLocalContext(`${q}\n${context}`)),
  ]);

  const packed = [
    context,
    site.brief.slice(0, 5000),
    local.brief.slice(0, 8000),
  ]
    .filter(Boolean)
    .join("\n\n");

  const deep = wantsRootServer(q);
  const cursor = await cursorRecommend({
    question: q,
    context: packed,
    env,
    deep,
  });
  if (cursor.ok && cursor.text) return cursor.text;
  console.warn("Ava cursor:", cursor.reason);
  return heuristicRecommend(q);
}

/** Clear address to Ava — not mid-sentence gossip. */
export function looksLikeSexiTrigger(contentOrMsg, botUserId) {
  if (contentOrMsg && typeof contentOrMsg === "object") {
    const msg = contentOrMsg;
    if (botUserId && Array.isArray(msg.mentions)) {
      if (msg.mentions.some((u) => String(u?.id) === String(botUserId))) return true;
    }
    if (msg.message_reference?.message_id && botUserId) {
      // reply-to handled by poller when ref author is Ava
    }
    return looksLikeSexiTrigger(msg.content || "", botUserId);
  }
  const raw = String(contentOrMsg || "").trim();
  if (!raw) return false;
  if (botUserId && (raw.includes(`<@${botUserId}>`) || raw.includes(`<@!${botUserId}>`))) {
    return true;
  }
  if (/\b@?sexi\b/i.test(raw) || /sexi\s+assistant/i.test(raw)) return true;
  // "Ava" / "Ava Ivy" as address — start of message, or short ping
  if (/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?([,:!?]|\s|$)/i.test(raw)) {
    return true;
  }
  if (/^ava(\s+ivy)?[!?.]*$/i.test(raw)) return true;
  return false;
}

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/\b@?sexi\b/gi, "")
    .replace(/sexi\s+assistant/gi, "")
    .replace(/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?[,:!]?\s*/i, "")
    .trim();
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WEB_PUBLIC = path.resolve(__dirname, "../../rootmc-web/public");

/** Curated public RootMC pages Sexi can cite. */
export const SITE_CATALOG = [
  { id: "wiki-hub", url: "https://rootmc.net/wiki/", local: "wiki/index.html", keywords: ["wiki", "guide", "docs", "help"] },
  { id: "wiki-economy", url: "https://rootmc.net/wiki/economy/", local: "wiki/economy/index.html", keywords: ["economy", "gold", "g ", "shop", "reserve", "loan", "tax", "baltop", "mint", "note"] },
  { id: "wiki-player", url: "https://rootmc.net/wiki/player/", local: "wiki/player/index.html", keywords: ["player", "join", "link", "howto", "new"] },
  { id: "wiki-claims", url: "https://rootmc.net/wiki/claims/", local: "wiki/claims/index.html", keywords: ["claim", "claims", "land", "chunk"] },
  { id: "wiki-territories", url: "https://rootmc.net/wiki/territories/", local: "wiki/territories/index.html", keywords: ["territory", "territories", "influence"] },
  { id: "wiki-constitution", url: "https://rootmc.net/wiki/constitution/", local: "wiki/constitution/index.html", keywords: ["constitution", "governance", "rules", "treasury"] },
  { id: "wiki-plugins", url: "https://rootmc.net/wiki/plugins/", local: "wiki/plugins/index.html", keywords: ["plugin", "plugins", "suite", "install", "command", "commands"] },
  { id: "wiki-api", url: "https://rootmc.net/wiki/plugins/api/", local: "wiki/plugins/api/index.html", keywords: ["api", "manifest", "updater", "heartbeat"] },
  { id: "wiki-versioning", url: "https://rootmc.net/wiki/versioning/", local: "wiki/versioning/index.html", keywords: ["version", "versioning"] },
  { id: "wiki-awards", url: "https://rootmc.net/wiki/weekly-awards/", local: "wiki/weekly-awards/index.html", keywords: ["award", "weekly", "prize"] },
  { id: "thanks", url: "https://rootmc.net/thanks/", local: "thanks/index.html", keywords: ["thanks", "token", "appreciation", "redeem", "vote", "bonus"] },
  { id: "plugins-catalog", url: "https://rootmc.net/plugins/", local: "plugins/index.html", keywords: ["catalog", "download", "jar"] },
  { id: "economy-live", url: "https://rootmc.net/economy/", local: "economy/index.html", keywords: ["economy", "dashboard", "live"] },
  { id: "heads", url: "https://rootmc.net/wiki/", local: "wiki/index.html", keywords: ["head", "heads", "mobhead", "skull"] },
];

function htmlToText(html) {
  return String(html || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

function readLocal(rel) {
  const full = path.join(WEB_PUBLIC, rel);
  if (!fs.existsSync(full)) return null;
  try {
    return htmlToText(fs.readFileSync(full, "utf8"));
  } catch {
    return null;
  }
}

async function fetchRemote(url) {
  try {
    const res = await fetch(url, {
      headers: { "User-Agent": "RootMC-Ava/0.4 (+https://rootmc.net)" },
      signal: AbortSignal.timeout(2500),
    });
    if (!res.ok) return null;
    return htmlToText(await res.text());
  } catch {
    return null;
  }
}

/** Score catalog pages against the question; return top snippets. Prefers local files for speed. */
export async function gatherSiteContext(question, { maxPages = 3, maxChars = 6500 } = {}) {
  const q = String(question || "").toLowerCase();
  const scored = SITE_CATALOG.map((page) => {
    let score = 0;
    for (const kw of page.keywords) {
      if (q.includes(kw.toLowerCase())) score += kw.length > 4 ? 3 : 2;
    }
    if (score === 0 && /wiki|site|docs|guide|how/.test(q)) score = 1;
    return { ...page, score };
  })
    .filter((p) => p.score > 0)
    .sort((a, b) => b.score - a.score);

  const picks = (
    scored.length
      ? scored
      : SITE_CATALOG.filter((p) => p.id === "wiki-hub" || p.id === "wiki-economy")
  ).slice(0, maxPages);

  const loaded = await Promise.all(
    picks.map(async (page) => {
      let text = readLocal(page.local);
      if (!text || text.length < 80) {
        text = await fetchRemote(page.url);
      }
      if (!text) return null;
      return { page, text: text.slice(0, 2000) };
    }),
  );

  const blocks = [];
  let used = 0;
  for (const item of loaded) {
    if (!item) continue;
    const block = `### ${item.page.id} (${item.page.url})\n${item.text}`;
    if (used + block.length > maxChars) break;
    blocks.push(block);
    used += block.length;
  }

  const index = SITE_CATALOG.map((p) => `- ${p.url} [${p.keywords.slice(0, 4).join(", ")}]`).join("\n");
  return {
    pages: picks.map((p) => p.url),
    brief: `Public RootMC resource index:\n${index}\n\nPulled page text (prefer these facts):\n${blocks.join("\n\n") || "(none pulled — say you're not sure, don't invent)"}`,
  };
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { AVA_HANDOFF } from "./config.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "../../..");

function safeRead(file, max = 8000) {
  try {
    if (!fs.existsSync(file) || !fs.statSync(file).isFile()) return null;
    const raw = fs.readFileSync(file, "utf8");
    const cleaned = raw
      .split(/\r?\n/)
      .filter((line) => !/(password|token|secret|api[_-]?key|jdbc:|Bearer\s)/i.test(line))
      .join("\n");
    return cleaned.slice(-max);
  } catch {
    return null;
  }
}

function listNewest(dir, pred, limit = 5) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs
      .readdirSync(dir)
      .map((name) => ({ name, full: path.join(dir, name) }))
      .filter((e) => {
        try {
          return pred(e.full, e.name);
        } catch {
          return false;
        }
      })
      .map((e) => ({ ...e, mtime: fs.statSync(e.full).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, limit);
  } catch {
    return [];
  }
}

function findLatestLogs() {
  const fixed = [
    path.join(ROOT, "Server Live Backups", "1. RootMC - Claims", "logs", "latest.log"),
    path.join(ROOT, "Server Live Backups", "2. RootMC - Towny", "logs", "latest.log"),
    path.join(ROOT, "Server Live Backups", "3. RootMC - Test Server", "logs", "latest.log"),
    path.join(ROOT, "Server Handoffs", "1. RootMC - Claims", "logs", "latest.log"),
    path.join(ROOT, "Server Handoffs", "2. RootMC - Towny", "logs", "latest.log"),
  ];
  return fixed
    .filter((full) => {
      try {
        return fs.existsSync(full);
      } catch {
        return false;
      }
    })
    .map((full) => ({
      name: path.relative(ROOT, full).replace(/\\/g, "/"),
      full,
      mtime: fs.statSync(full).mtimeMs,
    }))
    .sort((a, b) => b.mtime - a.mtime)
    .slice(0, 2);
}

/** Tiny always-on accuracy anchors (no secrets). */
function coreFacts() {
  return `### RootMC facts (must not contradict)
- Currency: Gold (G), never dollars in player-facing copy
- Game: play.rootmc.net | API: https://api.rootmc.net | Site: https://rootmc.net | Map: https://map.rootmc.net
- Live hosts: Claims + Towny; Gen2 retired → Claims
- Features need proposals + votes; bugs: verify then fix
- Ava handoff drop zone: Server Handoffs/Ava Ivy (uploads/, plans/, data/)`;
}

/**
 * Pull local workspace snippets Ava can discuss (scrubbed).
 * Keyword-route for accuracy; keep packs lean for speed.
 */
export function gatherLocalContext(question = "") {
  const q = String(question || "").toLowerCase();
  const blocks = [coreFacts()];
  const wantLogs = /log|weird|error|crash|exception|console|stack/.test(q);
  const wantHeads = /head|mobhead|skull/.test(q);
  const wantThanks = /token|thanks|appreciation|redeem|bonus|vote/.test(q);
  const wantGamble = /lotto|gamble|casino|bet/.test(q);
  const wantOps = /restart|ops|admin|kick|ban/.test(q);
  const wantLead =
    /proposal|vote|plan|lead.?dev|handoff|upload|governance|autonomy|offline/.test(q);
  const wantChangelog = /changelog|what.?changed|update|version|shipped|release/.test(q);

  const changeDir = path.join(ROOT, "Change Logs", "plugins");
  const changelogLimit = wantChangelog || wantLogs || wantHeads || wantThanks ? 4 : 2;
  const changelogs = listNewest(changeDir, (full, name) => name.endsWith(".md"), 8);
  for (const c of changelogs.slice(0, changelogLimit)) {
    // Prefer matching names when question hints a plugin
    const nameHit =
      !wantChangelog ||
      q.includes(c.name.replace(/\.md$/i, "").replace(/^root-/, "")) ||
      wantHeads ||
      wantThanks ||
      wantGamble ||
      wantOps;
    if (!nameHit && changelogLimit <= 2 && changelogs.indexOf(c) >= 2) continue;
    const text = safeRead(c.full, 2200);
    if (text) blocks.push(`### changelog ${c.name}\n${text}`);
  }

  const extras = [];
  if (wantHeads) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-heads.md"));
    extras.push(
      path.join(
        ROOT,
        "Plugin Building",
        "Minecraft",
        "plugins",
        "root-heads",
        "src",
        "main",
        "resources",
        "root-heads.yml",
      ),
    );
  }
  if (wantThanks) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-appreciation.md"));
  }
  if (wantGamble) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-gamble.md"));
  }
  if (wantOps) {
    extras.push(path.join(ROOT, "Change Logs", "plugins", "root-ops.md"));
  }
  for (const file of extras) {
    const text = safeRead(file, 2800);
    if (text) blocks.push(`### ${path.basename(file)}\n${text}`);
  }

  if (wantLogs) {
    for (const log of findLatestLogs()) {
      const text = safeRead(log.full, 3500);
      if (text) blocks.push(`### log tail (${log.name})\n${text}`);
    }
  }

  if (wantLead) {
    const handoffNotes = path.join(AVA_HANDOFF || "", "rootmc-lead-dev-bot-notes.md");
    const notes = safeRead(handoffNotes, 3500);
    if (notes) blocks.push(`### Ava Ivy lead-dev notes (excerpt)\n${notes}`);
  }

  const uploadsDir = path.join(AVA_HANDOFF || "", "uploads");
  const plansDir = path.join(AVA_HANDOFF || "", "plans");
  for (const f of listNewest(uploadsDir, (full) => fs.statSync(full).isFile(), 3)) {
    const text = safeRead(f.full, 2500);
    if (text) blocks.push(`### upload ${f.name}\n${text}`);
  }
  if (wantLead || /plan/.test(q)) {
    for (const f of listNewest(plansDir, (full, name) => name.endsWith(".md"), 3)) {
      const text = safeRead(f.full, 2800);
      if (text) blocks.push(`### plan ${f.name}\n${text}`);
    }
  }

  const joined = blocks.join("\n\n").slice(0, 12000);
  return {
    hasFiles: blocks.length > 1,
    brief: `Local RootMC workspace pack (scrubbed; prefer these facts; don't invent):\n${joined}`,
  };
}

