/** Jobs waiting + running on the Root Server brain. */
export function brainQueueDepth() {
  return pending;
}

function enqueue(fn) {
  pending += 1;
  const run = queue.then(
    async () => {
      try {
        return await fn();
      } finally {
        pending = Math.max(0, pending - 1);
      }
    },
