  );

  state.timers.push(
    setTimeout(() => {
      if (state.done) return;
      reply(channelId, pickHold(3), refId).catch(() => {});
    }, delays.beat3),
  );

  return {
    stop() {
      state.done = true;
      for (const t of state.timers) clearTimeout(t);
