export function endAsk() {
  asksOpen = Math.max(0, asksOpen - 1);
}

function enqueue(fn) {
  pending += 1;
  const run = queue.then(
    async () => {
      try {
        return await fn();
      } finally {
        pending = Math.max(0, pending - 1);
      }
    },
    async () => {
      try {
        return await fn();
      } finally {
        pending = Math.max(0, pending - 1);
      }
    },
  );
  queue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

