import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** Reuse RootMC realm-api env loader without publishing a package. */
export async function loadEnv() {
  const loaderPath = path.resolve(
    __dirname,
    "../../rootmc-realm-api/scripts/lib/rootmc-env.mjs",
  );
  if (!fs.existsSync(loaderPath)) {
    throw new Error(`Missing env loader at ${loaderPath}`);
  }
  const m = await import(pathToFileURL(loaderPath).href);
  return m.loadRootMcEnv();
}

function firstEnv(env, keys) {
  for (const key of keys) {
    const v = String(process.env[key] || env[key] || "").trim();
    if (v) return v;
  }
  return "";
}

export function botToken(env) {
  // Prefer Ava_* ; legacy SEXI_* still accepted.
  return firstEnv(env, [
    "AVA_DISCORD_BOT_TOKEN",
    "SEXI_DISCORD_BOT_TOKEN",
    "DISCORD_ROOTMC_BOT_TOKEN",
    "DISCORD_BOT_TOKEN",
  ]).replace(/^bot\s+/i, "");
}

/** Discord application / bot user id for Ava (mentions + self-skip). */
export function avaBotAppId(env = {}) {
  return (
    firstEnv(env, [
      "AVA_DISCORD_APPLICATION_ID",
      "AVA_DISCORD_CLIENT_ID",
      "SEXI_DISCORD_APPLICATION_ID",
      "SEXI_DISCORD_CLIENT_ID",
    ]) || AVA_BOT_APP_ID
  );
}

/** @deprecated use avaBotAppId */
export const sexiBotAppId = avaBotAppId;

export function grokToken(env) {
  return firstEnv(env, [
    "AVA_XAI_API_KEY",
    "SEXI_XAI_API_KEY",
    "XAI_API_KEY",
    "GROK_API_BEARER_TOKEN",
    "GROK_ROOT_ASK_BEARER_TOKEN",
  ]);
}

/** Cursor user / service-account API key (Dashboard → Integrations). */
export function cursorApiKey(env) {
  return firstEnv(env, ["CURSOR_API_KEY", "CURSOR_SDK_API_KEY"]);
}

export const AVA_MODEL = String(
  process.env.AVA_MODEL || process.env.SEXI_MODEL || "composer-2.5",
).trim();
/** @deprecated */
export const SEXI_MODEL = AVA_MODEL;

export const AVA_GROK_MODEL = String(
  process.env.AVA_GROK_MODEL || process.env.SEXI_GROK_MODEL || "grok-3-mini",
).trim();
/** @deprecated */
export const SEXI_GROK_MODEL = AVA_GROK_MODEL;

/** Default brain is Cursor — Grok unplugged. */
export const AVA_BRAIN_DEFAULT = "cursor";
/** @deprecated */
export const SEXI_BRAIN_DEFAULT = AVA_BRAIN_DEFAULT;

/** Override workspace cwd for the local Cursor agent (defaults to RootMC root). */
export const AVA_WORKSPACE = String(
  process.env.AVA_WORKSPACE || process.env.SEXI_WORKSPACE || "",
).trim();
/** @deprecated */
export const SEXI_WORKSPACE = AVA_WORKSPACE;

/** Ava Ivy handoff folder — lead-dev notes + future agent assets. */
export const AVA_HANDOFF = String(
  process.env.AVA_HANDOFF ||
    process.env.SEXI_HANDOFF ||
    "D:\\.1 Work Stations\\RootMC\\Server Handoffs\\Ava Ivy",
).trim();

/** Discord user IDs Ava must never @mention. */
export const NEVER_MENTION = new Set([
  "788153722198294618", // asked not to be tagged
]);

export const DISCORD_API = "https://discord.com/api/v10";
export const ROOTMC_GUILD_ID = "1516108585740800042";
/** Legacy RootMC bot — not used for Ava replies when AVA_DISCORD_* is set. */
export const ROOTMC_BOT_APP_ID = "1511794429986345020";
/** Dedicated Ava Discord application / bot user id. */
export const AVA_BOT_APP_ID = "1532751879875072070";
/** @deprecated */
export const SEXI_BOT_APP_ID = AVA_BOT_APP_ID;

/** Default watch list — proposals, admins, general. */
export const DEFAULT_WATCH_CHANNELS = [
  "1526664180491358419", // proposals
  "1516121832493678612", // admins
  "1516108586307158088", // #general
];

/** Resolve watch channels from env + defaults. */
export function watchChannels(env = {}) {
  const fromEnv = String(
    process.env.AVA_WATCH_CHANNELS ||
      env.AVA_WATCH_CHANNELS ||
      process.env.SEXI_WATCH_CHANNELS ||
      env.SEXI_WATCH_CHANNELS ||
      "",
  )
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const extras = [
    env.DISCORD_ROOTMC_GENERAL_CHAT_CHANNEL_ID,
    process.env.DISCORD_ROOTMC_GENERAL_CHAT_CHANNEL_ID,
  ]
    .map((s) => String(s || "").trim())
    .filter(Boolean);
  return [...new Set([...DEFAULT_WATCH_CHANNELS, ...fromEnv, ...extras])];
}

export const AVA_PORT = Number(process.env.AVA_PORT || process.env.SEXI_PORT || 8787);
/** @deprecated */
export const SEXI_PORT = AVA_PORT;

import { cursorApiKey } from "./config.mjs";
import { cursorRecommend } from "./cursorBrain.mjs";
import { scrubPublicReply } from "./scrub.mjs";
import { gatherSiteContext } from "./siteContext.mjs";
import { gatherLocalContext } from "./localContext.mjs";

export { scrubPublicReply } from "./scrub.mjs";
export { stripForbiddenMentions } from "./scrub.mjs";

export function wantsRootServer(question) {
  const q = String(question || "").toLowerCase();
  if (String(process.env.AVA_FORCE_CURSOR || process.env.SEXI_FORCE_CURSOR || "").trim() === "1") {
    return true;
  }
  return (
    /\broot\s*server\b/.test(q) ||
    /\b(implement|code\s+this|build\s+it|ship\s+it|dig\s+into\s+(the\s+)?(repo|code|source))\b/.test(q) ||
    /\b(check|read|scan|look\s+at|verify|find)\s+(the\s+)?(repo|codebase|source|plugins?|logs?|files?)\b/.test(q) ||
    /\b(why\s+(is|did|does)|stack\s*trace|exception|crash|npe)\b/.test(q)
  );
}

export function isHushCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    (/\b(stop|hush|quiet|sleep|go\s+offline|shut\s+up)\b/.test(q) && /\bava\b/.test(q)) ||
    /^(stop|hush|quiet)\s*(ava)?[!?.]*$/i.test(q.trim())
  );
}

export function isWakeCommand(content) {
  const q = String(content || "").toLowerCase();
  return /\b(wake|come\s+back|you'?re\s+active|unmute)\b/.test(q) && /\bava\b/.test(q);
}

export function heuristicRecommend(question) {
  const q = String(question || "").toLowerCase();
  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }
  return scrubPublicReply(
    "I'm a bit offline on the deep-dig side — ask again when the Root Server's up, or leave notes in my handoff folder.",
  );
}

/**
 * Cursor-only brain. Wiki + local packs go into the Cursor prompt.
 * Pack gather is parallel; deep dig only when needed (speed default).
 */
export async function recommend({ question, context = "", env }) {
  const q = String(question || "").trim();
  if (!q) {
    return scrubPublicReply(
      "What's up? Wiki, design, logs, proposals — fire away. Give me a sec when you ping; I think before I talk.",
    );
  }

  if (/frisky|dtf|sexy|smash|date\s+me|hook\s*up|nudes?|onlyfans|(come|get)\s+over\s+here/i.test(q)) {
    return scrubPublicReply("Fuck off.");
  }

  if (!cursorApiKey(env || {})) {
    return heuristicRecommend(q);
  }

  const [site, local] = await Promise.all([
    gatherSiteContext(q, { maxPages: 3, maxChars: 6500 }),
    Promise.resolve(gatherLocalContext(`${q}\n${context}`)),
  ]);

  const packed = [
    context,
    site.brief.slice(0, 5000),
    local.brief.slice(0, 8000),
  ]
    .filter(Boolean)
    .join("\n\n");

  const deep = wantsRootServer(q);
  const cursor = await cursorRecommend({
    question: q,
    context: packed,
    env,
    deep,
  });
  if (cursor.ok && cursor.text) return cursor.text;
  console.warn("Ava cursor:", cursor.reason);
  return heuristicRecommend(q);
}

/** Clear address to Ava — bot mention, reply handled by poller, or Ava / Ava Ivy. */
export function looksLikeAvaTrigger(contentOrMsg, botUserId) {
  if (contentOrMsg && typeof contentOrMsg === "object") {
    const msg = contentOrMsg;
    if (botUserId && Array.isArray(msg.mentions)) {
      if (msg.mentions.some((u) => String(u?.id) === String(botUserId))) return true;
    }
    return looksLikeAvaTrigger(msg.content || "", botUserId);
  }
  const raw = String(contentOrMsg || "").trim();
  if (!raw) return false;
  if (botUserId && (raw.includes(`<@${botUserId}>`) || raw.includes(`<@!${botUserId}>`))) {
    return true;
  }
  if (/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?([,:!?]|\s|$)/i.test(raw)) {
    return true;
  }
  if (/^ava(\s+ivy)?[!?.]*$/i.test(raw)) return true;
  return false;
}

/** @deprecated */
export const looksLikeSexiTrigger = looksLikeAvaTrigger;

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?[,:!]?\s*/i, "")
    .trim();
}

