import { scrubPublicReply } from "./scrub.mjs";

/**
 * Legacy Grok brain — unplugged from recommend path. Kept for reference only.
 */
export async function grokRecommend({ question, context = "", env }) {
  const key = grokToken(env || {});
  if (!key) {
    return { ok: false, reason: "missing_xai_key", text: null };
  }

  const site = await gatherSiteContext(question);
  const local = gatherLocalContext(`${question}\n${context}`);

  const system = `${AVA_PERSONA}

${AVA_HARD_RULES}

Mode: unused legacy path. Prefer Root Server (Cursor) in production.`;

  const user = `Discord conversation context:
${String(context || "(none)").slice(0, 6500)}

Latest ask:
${String(question).trim()}

Site/wiki pack:
${site.brief.slice(0, 7000)}

${local.brief.slice(0, 12000)}

Write Ava's Discord reply now.`;

  try {
    const res = await fetch("https://api.x.ai/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: AVA_GROK_MODEL,
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
        temperature: 0.55,
      }),
      signal: AbortSignal.timeout(45_000),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      return { ok: false, reason: `http_${res.status}`, text: null };
    }
    const text = scrubPublicReply(data?.choices?.[0]?.message?.content || "");
    if (!text) return { ok: false, reason: "empty", text: null };
    return { ok: true, reason: "ok", text };
  } catch (err) {
    return { ok: false, reason: String(err?.message || err), text: null };
  }
}

