      const s = Math.max(0, Math.floor((Date.now() - ms) / 1000));
      if (s < 60) return s + "s ago";
      if (s < 3600) return Math.floor(s / 60) + "m ago";
      return Math.floor(s / 3600) + "h ago";
    }
    function cells(rows) {
      return rows.map(([k, v]) =>
        '<div class="cell"><label>' + k + '</label><strong>' + v + '</strong></div>'
      ).join("");
    }
    async function tick() {
      try {
        const res = await fetch("/api/status", { cache: "no-store" });
        const d = await res.json();
        const hb = d.heartbeat || {};
        const age = d.heartbeatAgeMs;
        const stale = age == null || age > 45000;
        const hushed = Boolean(d.hushed || hb.hushed);
        const onBreak = Boolean(hb.onBreak);
        const live = Boolean(hb.live) && !stale;
        const dig = Number(hb.queueDepth || 0) > 0;

        let label = "offline";
        let cls = "";
        if (stale || !hb.updatedAt) { label = "poller offline"; cls = ""; }
        else if (hushed) { label = "hushed"; cls = "hush"; }
        else if (onBreak) { label = "on break"; cls = "break"; }
        else if (dig) { label = "digging · live"; cls = "live"; }
        else if (live) { label = "live · hot"; cls = "live"; }
        else { label = "starting…"; cls = "break"; }

        $("dot").className = "dot " + cls;
        $("state").textContent = label;

        $("grid").innerHTML = cells([
          ["Mode", hb.mode || (onBreak ? "break" : live ? "hot" : "—")],
          ["Poll", (hb.pollMs != null ? (hb.pollMs / 1000) + "s" : "—")],
          ["Queue", String(hb.queueDepth ?? "—")],
          ["Last activity", ago(hb.lastActivityAt)],
          ["Heartbeat", ago(hb.updatedAt)],
          ["Last ask", hb.lastAsk || "—"],
          ["Cursor key", d.cursor ? "yes" : "missing"],
          ["Model", d.cursorModel || "—"],
          ["Channels", String(hb.watchCount ?? "—")],
          ["PID", String(hb.pid ?? "—")],
        ]);

        $("events").innerHTML = (d.events || []).map((line) => {
          const parts = line.split("\\t");
          const ts = parts[0] || "";
          const msg = parts.slice(1).join("\\t") || line;
          return "<li>" + ts.slice(11, 19) + " · <span>" + msg.replace(/</g, "&lt;") + "</span></li>";
        }).join("") || "<li>no events yet</li>";
      } catch (e) {
        $("dot").className = "dot";
        $("state").textContent = "HTTP down";
      }
    }
    tick();
    setInterval(tick, 2000);
  </script>
</body>
</html>`;
}

import http from "node:http";
import {
  loadEnv,
  AVA_PORT,
  cursorApiKey,
  AVA_MODEL,
  AVA_HANDOFF,
} from "./config.mjs";
import { workspaceRoot } from "./cursorBrain.mjs";
import { recommend } from "./recommend.mjs";
import {
  storePaths,
  loadHeartbeat,
  loadStatusEvents,
  isHushed,
} from "./store.mjs";
import { statusPageHtml } from "./statusPage.mjs";

const env = await loadEnv();
storePaths();

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://127.0.0.1:${AVA_PORT}`);

  if (req.method === "GET" && (url.pathname === "/" || url.pathname === "/status")) {
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.setHeader("Cache-Control", "no-store");
    res.end(statusPageHtml());
    return;
  }

  res.setHeader("Content-Type", "application/json; charset=utf-8");

  if (req.method === "GET" && url.pathname === "/api/status") {
    const heartbeat = loadHeartbeat();
    const updatedAt = heartbeat?.updatedAt || 0;
    res.end(
      JSON.stringify({
        ok: true,
        service: "ava-ivy",
        version: "0.4.0",
        httpUp: true,
        cursor: Boolean(cursorApiKey(env)),
        cursorModel: AVA_MODEL,
        workspace: workspaceRoot(),
        handoff: AVA_HANDOFF,
        hushed: isHushed(),
        heartbeat,
        heartbeatAgeMs: updatedAt ? Date.now() - updatedAt : null,
        events: loadStatusEvents(24),
      }),
    );
    return;
  }

  if (req.method === "GET" && url.pathname === "/health") {
    const heartbeat = loadHeartbeat();
    res.end(
      JSON.stringify({
        ok: true,
        service: "ava-ivy",
        version: "0.4.0",
        brain: "cursor",
        cursor: Boolean(cursorApiKey(env)),
        cursorModel: AVA_MODEL,
        workspace: workspaceRoot(),
        handoff: AVA_HANDOFF,
        pollerLive: Boolean(heartbeat?.live),
        heartbeatAgeMs: heartbeat?.updatedAt ? Date.now() - heartbeat.updatedAt : null,
        note: "Open / for the status window.",
      }),
    );
    return;
  }

  if (req.method === "POST" && url.pathname === "/v1/recommend") {
    let body = "";
    for await (const chunk of req) body += chunk;
    let parsed = {};
    try {
      parsed = body ? JSON.parse(body) : {};
    } catch {
      res.statusCode = 400;
      res.end(JSON.stringify({ error: "invalid_json" }));
      return;
    }
    const answer = await recommend({
      question: parsed.question || parsed.prompt || "",
      context: parsed.context || "",
      env,
      authorId: parsed.authorId || parsed.discordId || "",
      authorName: parsed.authorName || parsed.username || "",
    });
    res.end(JSON.stringify({ answer }));
    return;
  }

  res.statusCode = 404;
  res.end(JSON.stringify({ error: "not_found" }));
});

server.listen(AVA_PORT, "127.0.0.1", () => {
  console.log(`ava-ivy status window http://127.0.0.1:${AVA_PORT}/`);
});

