import { spawn } from "node:child_process";
import { exec } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { AVA_PORT } from "./config.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const statusUrl = `http://127.0.0.1:${AVA_PORT}/`;

function run(script) {
  const child = spawn(process.execPath, [path.join(__dirname, script)], {
    cwd: root,
    stdio: "inherit",
    env: process.env,
  });
  child.on("exit", (code) => {
    console.error(`${script} exited`, code);
    process.exit(code || 1);
  });
  return child;
}

/** Open a dedicated app window (Edge/Chrome) or default browser. */
function openStatusWindow() {
  if (String(process.env.AVA_NO_STATUS_WINDOW || "").trim() === "1") return;
  const ps = `
$u = '${statusUrl}'
$edge = @(
  "$env:ProgramFiles(x86)\\Microsoft\\Edge\\Application\\msedge.exe",
  "$env:ProgramFiles\\Microsoft\\Edge\\Application\\msedge.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
$chrome = @(
  "$env:ProgramFiles\\Google\\Chrome\\Application\\chrome.exe",
  "$env:ProgramFiles(x86)\\Google\\Chrome\\Application\\chrome.exe",
  "$env:LocalAppData\\Google\\Chrome\\Application\\chrome.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
if ($edge) { Start-Process $edge -ArgumentList "--app=$u","--new-window" }
elseif ($chrome) { Start-Process $chrome -ArgumentList "--app=$u","--new-window" }
else { Start-Process $u }
`;
  exec(
    `powershell -NoProfile -ExecutionPolicy Bypass -Command ${JSON.stringify(ps)}`,
    () => {},
  );
}

