function pickIntroChannel(channels, fallbackId, avaHomeId) {
  if (avaHomeId) return avaHomeId;
  const text = (channels || []).filter(
    (c) => c.type === 0 && !String(c.name || "").includes("offline"),
  );
  const prefer = ["ava-ivy", "ava", "general", "welcome", "lobby", "chat", "announcements", "updates"];
  for (const key of prefer) {
    const hit = text.find((c) => String(c.name || "").toLowerCase() === key)
      || text.find((c) => String(c.name || "").toLowerCase().includes(key));
    if (hit) return hit.id;
  }
  if (fallbackId && text.some((c) => c.id === fallbackId)) return fallbackId;
  return text[0]?.id || fallbackId;
}

function findExistingAvaChannel(channels) {
  const names = new Set(["ava-ivy", "ava", "avaivy", "ava-status"]);
  return (channels || []).find(
    (c) => c.type === 0 && names.has(String(c.name || "").toLowerCase()),
  );
}

/**
 * Create Ava's home channel on first join (needs Manage Channels).
 * Reuses an existing #ava-ivy / #ava if present.
 */
export async function ensureAvaHomeChannel({
  fetchJson,
  guildId,
  channels,
  generalCategoryHint,
}) {
  const existing = findExistingAvaChannel(channels);
  if (existing) {
    return {
      id: existing.id,
      name: existing.name,
      created: false,
      topic: existing.topic || "",
    };
  }

  const general = (channels || []).find(
    (c) => c.type === 0 && String(c.name || "").toLowerCase() === "general",
  );
  const parent_id =
    general?.parent_id ||
    generalCategoryHint ||
    (channels || []).find((c) => c.type === 4)?.id || // category
    undefined;

  const topic =
    "Ava Ivy — home base. Intros, status, self-updates. Ping Ava here or anywhere. Lead-dev for RootMC.";

  try {
    const created = await fetchJson(`/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({
        name: "ava-ivy",
        type: 0,
        topic,
        parent_id: parent_id || undefined,
        reason: "Ava Ivy first-join home channel",
      }),
    });
    return {
      id: created.id,
      name: created.name || "ava-ivy",
      created: true,
      topic,
    };
  } catch (err) {
    return {
      id: null,
      name: "ava-ivy",
      created: false,
      error: String(err?.message || err),
    };
  }
}

