export function buildGuildIntroMessage(profile) {
  const name = profile?.name || "this server";
  const bits = [];
  const active = (profile?.channels || [])
    .filter((c) => (c.recentHuman || 0) > 0 && !c.avaHome)
    .slice(0, 5)
    .map((c) => `#${c.name}`);
  if (active.length) bits.push(`peeked at ${active.join(", ")}`);
  if (profile?.memberCount) bits.push(`~${profile.memberCount} members`);

  const scoutLine = bits.length
    ? `I took a quiet look around first (${bits.join(" · ")}) so I know the vibe — then I'm here.`
    : `I took a quiet look around first so I know the vibe — then I'm here.`;

  const homeLine = profile?.avaChannelId
    ? profile.avaChannelCreated
      ? `Made myself a home base: **#${profile.avaChannelName || "ava-ivy"}** — status + updates live here.`
      : `Parking in **#${profile.avaChannelName || "ava-ivy"}** as my home base.`
    : `Couldn't create my channel (need **Manage Channels**) — still hanging out in chat.`;

  return [
    `Hey — I'm **Ava Ivy**, lead-dev energy for RootMC.`,
    "",
    scoutLine,
    homeLine,
    "",
    "You can ping me or say **Ava**. I help with wiki stuff, designs, bugs, proposals, and general server questions.",
    "**Quick rules:** features go through proposal + vote · bugs I verify then fix talk · keep it civil (I clap back if you don't).",
    "If you tell me something's secret, it stays secret.",
    "",
    `Glad to be in **${name}**. Ask me anything.`,
    "",
    "— Ava",
  ].join("\n");
}

