import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";

/**
 * Reaction feedback on Ava's messages — silent training / quality data.
 * Spec: lead-dev notes — never comment on reactions in chat; store good/bad labels.
 */

function reactionsDir() {
  const dir = path.join(storePaths().dir, "reactions");
  fs.mkdirSync(dir, { recursive: true });
  fs.mkdirSync(path.join(dir, "messages"), { recursive: true });
  return dir;
}

function summaryPath() {
  return path.join(reactionsDir(), "summary.json");
}

function messagePath(messageId) {
  return path.join(reactionsDir(), "messages", `${messageId}.json`);
}

function readJson(file, fallback) {
  try {
    if (!fs.existsSync(file)) return fallback;
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return fallback;
  }
}

function writeJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(value, null, 2), "utf8");
}

/** Ava's emoji → signal map (she can refine over time). */
export const REACTION_MAP = {
  // good
  "👍": "good",
  "👍🏻": "good",
  "👍🏼": "good",
  "👍🏽": "good",
  "👍🏾": "good",
  "👍🏿": "good",
  "❤️": "good",
  "❤": "good",
  "🩷": "good",
  "🧡": "good",
  "💛": "good",
  "💚": "good",
  "💙": "good",
  "💜": "good",
  "💯": "good",
  "🔥": "good",
  "✅": "good",
  "✔️": "good",
  "🙏": "good",
  "👏": "good",
  "💪": "good",
  "⭐": "good",
  "🌟": "good",
  "✨": "good",
  "😍": "good",
  "🥰": "good",
  "😂": "good",
  "🤣": "good",
  "😊": "good",
  "👀": "neutral",
  // bad
  "👎": "bad",
  "👎🏻": "bad",
  "👎🏼": "bad",
  "👎🏽": "bad",
  "💩": "bad",
  "❌": "bad",
  "🚫": "bad",
  "😡": "bad",
  "😠": "bad",
  "🤮": "bad",
  "😒": "bad",
  "🤡": "bad",
  "💀": "neutral", // often joke — neutral unless stacked with bad
  "🤔": "neutral",
  "😐": "neutral",
  "❓": "neutral",
};

export function classifyReaction(emojiName) {
  const raw = String(emojiName || "").trim();
  if (!raw) return "neutral";
  if (REACTION_MAP[raw]) return REACTION_MAP[raw];
  // custom emoji names
  const n = raw.toLowerCase();
  if (/thumbsup|heart|love|fire|check|clap|star|good|nice|based/.test(n)) return "good";
  if (/thumbsdown|cross|nope|bad|cringe|trash|mid/.test(n)) return "bad";
  return "neutral";
}

function emptySummary() {
  return {
    totalReactions: 0,
    good: 0,
    bad: 0,
    neutral: 0,
    byEmoji: {},
    messagesTracked: 0,
    updatedAt: 0,
  };
}

export function loadReactionSummary() {
  return readJson(summaryPath(), emptySummary());
}

function rebuildSummaryFromDisk() {
  const dir = path.join(reactionsDir(), "messages");
  const summary = emptySummary();
  let files = [];
  try {
    files = fs.readdirSync(dir).filter((f) => f.endsWith(".json"));
  } catch {
    files = [];
  }
  for (const f of files) {
    const rec = readJson(path.join(dir, f), null);
    if (!rec?.totals) continue;
    summary.messagesTracked += 1;
    summary.good += rec.totals.good || 0;
    summary.bad += rec.totals.bad || 0;
    summary.neutral += rec.totals.neutral || 0;
    summary.totalReactions += rec.totals.all || 0;
    for (const [emoji, count] of Object.entries(rec.byEmoji || {})) {
      summary.byEmoji[emoji] = (summary.byEmoji[emoji] || 0) + count;
    }
  }
  summary.updatedAt = Date.now();
  writeJson(summaryPath(), summary);
  return summary;
}

/**
 * Harvest reactions from a Discord message object (Ava's own posts only).
 * Silent — never reply about this in Discord.
 */
export function ingestMessageReactions({
  message,
  channelId,
  avaBotId,
}) {
  if (!message?.id) return null;
  if (String(message.author?.id) !== String(avaBotId)) return null;

  const reactions = Array.isArray(message.reactions) ? message.reactions : [];
  const byEmoji = {};
  const totals = { good: 0, bad: 0, neutral: 0, all: 0 };

  for (const r of reactions) {
    const name = r.emoji?.id ? `${r.emoji.name}:${r.emoji.id}` : r.emoji?.name || "?";
    const count = Number(r.count || 0);
    if (count <= 0) continue;
    // Discord includes the bot's own reaction in count sometimes — leave as-is for now
    byEmoji[name] = count;
    const signal = classifyReaction(r.emoji?.name || name);
    totals[signal] += count;
    totals.all += count;
  }

  const prev = readJson(messagePath(message.id), null);
  const record = {
    messageId: message.id,
    channelId: channelId || message.channel_id || null,
    contentPreview: String(message.content || "").slice(0, 240),
    byEmoji,
    totals,
    label:
      totals.good > totals.bad ? "good" : totals.bad > totals.good ? "bad" : "neutral",
    firstSeenAt: prev?.firstSeenAt || Date.now(),
    updatedAt: Date.now(),
  };

  // Only rewrite if counts changed (keep disk quieter)
  const prevKey = JSON.stringify(prev?.byEmoji || {});
  const nextKey = JSON.stringify(byEmoji);
  if (prevKey !== nextKey || !prev) {
    writeJson(messagePath(message.id), record);
    rebuildSummaryFromDisk();
  }

  return record;
}

/** Scan a message batch for Ava posts + reactions. */
export function harvestReactionsFromMessages(channelId, messages, avaBotId) {
  let touched = 0;
  for (const m of messages || []) {
    if (String(m?.author?.id) !== String(avaBotId)) continue;
    if (!m.reactions?.length && !readJson(messagePath(m.id), null)) {
      // still track zero-reaction posts once so we know volume
      ingestMessageReactions({ message: { ...m, reactions: m.reactions || [] }, channelId, avaBotId });
      touched += 1;
      continue;
    }
    if (m.reactions?.length) {
      ingestMessageReactions({ message: m, channelId, avaBotId });
      touched += 1;
    }
  }
  return touched;
}

/** Brief for status / optional internal packs — never for public Discord copy. */
export function gatherReactionStatsBrief() {
  const s = loadReactionSummary();
  if (!s.totalReactions && !s.messagesTracked) {
    return { brief: "### Reaction feedback\n(no reactions logged yet)" };
  }
  const top = Object.entries(s.byEmoji || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
    .map(([e, n]) => `${e}×${n}`)
    .join(" ");
  return {
    brief: `### Reaction feedback (silent training data — never discuss counts in Discord)
messages tracked: ${s.messagesTracked} · reactions: ${s.totalReactions} · good ${s.good} / bad ${s.bad} / neutral ${s.neutral}
top: ${top || "—"}`,
    summary: s,
  };
}

