/**
 * Shared Discord REST helpers for Ava (poller + gateway).
 */
import { DISCORD_API } from "./config.mjs";

export function authHeaders(token) {
  return {
    Authorization: `Bot ${token}`,
    "Content-Type": "application/json",
    "User-Agent": "AvaIvyRootMC (rootmc.net, 0.5)",
  };
}

export function makeFetchJson(token) {
  const headers = authHeaders(token);
  return async function fetchJson(path, init = {}) {
    const res = await fetch(`${DISCORD_API}${path}`, {
      ...init,
      headers: { ...headers, ...(init.headers || {}) },
    });
    const text = await res.text();
    if (!res.ok) throw new Error(`${path} ${res.status}: ${text.slice(0, 200)}`);
    return text ? JSON.parse(text) : null;
  };
}

export async function postMessage(fetchJson, channelId, content, refId) {
  return fetchJson(`/channels/${channelId}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: String(content).slice(0, 2000),
      message_reference: refId ? { message_id: refId } : undefined,
      allowed_mentions: { parse: [] },
    }),
  });
}

export async function createDmChannel(fetchJson, userId) {
  return fetchJson(`/users/@me/channels`, {
    method: "POST",
    body: JSON.stringify({ recipient_id: String(userId) }),
  });
}

export async function sendDm(fetchJson, userId, content) {
  const ch = await createDmChannel(fetchJson, userId);
  if (!ch?.id) throw new Error("dm_channel_failed");
  return postMessage(fetchJson, ch.id, content, null);
}

/** Download Discord attachment into Ava uploads/. */
export async function downloadAttachment(url, destPath) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`download ${res.status}`);
  const buf = Buffer.from(await res.arrayBuffer());
  const fs = await import("node:fs");
  const path = await import("node:path");
  fs.mkdirSync(path.dirname(destPath), { recursive: true });
  fs.writeFileSync(destPath, buf);
  return destPath;
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";

/**
 * Persist conversation turns for training + audit (JSONL + simple index).
 * Spec: local first; MySQL later.
 */

function turnsPath() {
  const dir = path.join(storePaths().dir, "conversations");
  fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, "turns.jsonl");
}

function indexPath() {
  return path.join(storePaths().dir, "conversations", "index.json");
}

function readIndex() {
  try {
    if (!fs.existsSync(indexPath())) return { turns: 0, byUser: {}, updatedAt: 0 };
    return JSON.parse(fs.readFileSync(indexPath(), "utf8"));
  } catch {
    return { turns: 0, byUser: {}, updatedAt: 0 };
  }
}

function writeIndex(idx) {
  fs.mkdirSync(path.dirname(indexPath()), { recursive: true });
  fs.writeFileSync(indexPath(), JSON.stringify(idx, null, 2), "utf8");
}

/**
 * @param {{ channelId, messageId, authorId, authorName, question, answer, intent?, jobId? }} turn
 */
export function persistTurn(turn) {
  const row = {
    at: Date.now(),
    channelId: turn.channelId || null,
    messageId: turn.messageId || null,
    authorId: turn.authorId || null,
    authorName: turn.authorName || null,
    question: String(turn.question || "").slice(0, 4000),
    answer: String(turn.answer || "").slice(0, 4000),
    intent: turn.intent || null,
    jobId: turn.jobId || null,
    quality: turn.quality || null,
  };
  fs.appendFileSync(turnsPath(), JSON.stringify(row) + "\n", "utf8");
  const idx = readIndex();
  idx.turns = (idx.turns || 0) + 1;
  idx.updatedAt = Date.now();
  if (row.authorId) {
    idx.byUser[row.authorId] = (idx.byUser[row.authorId] || 0) + 1;
  }
  writeIndex(idx);
  return row;
}

export function conversationStats() {
  return readIndex();
}

import fs from "node:fs";
import path from "node:path";
import { AVA_HANDOFF } from "./config.mjs";
import { downloadAttachment } from "./discordApi.mjs";

/**
 * Save Discord attachments pinged at Ava into Server Handoffs/Ava Ivy/uploads/
 */
export function uploadsDir() {
  const dir = path.join(AVA_HANDOFF, "uploads");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

export function plansDir() {
  const dir = path.join(AVA_HANDOFF, "plans");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function safeName(name) {
  return String(name || "file")
    .replace(/[^\w.\-]+/g, "_")
    .slice(0, 120);
}

/**
 * @returns {Promise<string[]>} saved relative paths
 */
export async function saveMessageAttachments(msg) {
  const atts = Array.isArray(msg?.attachments) ? msg.attachments : [];
  if (!atts.length) return [];
  const saved = [];
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  for (const a of atts) {
    if (!a?.url || !a?.id) continue;
    const base = `${stamp}_${a.id}_${safeName(a.filename || "att")}`;
    const dest = path.join(uploadsDir(), base);
    try {
      await downloadAttachment(a.url, dest);
      saved.push(path.relative(AVA_HANDOFF, dest).replace(/\\/g, "/"));
    } catch (err) {
      console.warn("upload save failed:", err.message);
    }
  }
  return saved;
}

/** List newest upload filenames for packs. */
export function listRecentUploads(limit = 8) {
  try {
    return fs
      .readdirSync(uploadsDir())
      .map((name) => ({
        name,
        full: path.join(uploadsDir(), name),
        mtime: fs.statSync(path.join(uploadsDir(), name)).mtimeMs,
      }))
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, limit)
      .map((e) => e.name);
  } catch {
    return [];
  }
}

export function listRecentPlans(limit = 6) {
  try {
    return fs
      .readdirSync(plansDir())
      .filter((n) => n.endsWith(".md"))
      .map((name) => ({
        name,
        full: path.join(plansDir(), name),
        mtime: fs.statSync(path.join(plansDir(), name)).mtimeMs,
      }))
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, limit)
