/**
 * Write / update a proposal plan file under plans/.
 */
export function writeProposalPlan({ proposalId, title, body }) {
  const id = String(proposalId || `draft-${Date.now()}`).replace(/[^\w.\-]+/g, "_");
  const file = path.join(plansDir(), `${id}.md`);
  const header = `# Plan: ${title || id}\n\n_Updated: ${new Date().toISOString()}_\n\n`;
  fs.writeFileSync(file, header + String(body || "").trim() + "\n", "utf8");
  return file;
}

export function proposalPlanTemplate({ problem, plan, risks, rollback }) {
  return `## Problem
${problem || "(tbd)"}

## Plan
${plan || "(tbd)"}

## Risks
${risks || "(tbd)"}

## Rollback
${rollback || "(tbd)"}
`;
}

/**
 * Classify Discord asks: chat | bug | feature | config_tune | governance
 * Features → proposal path. Bugs → verify then fix. Config = "playing with her".
 * Ava-only metaphors — never frame the Minecraft server as her body.
 */

export function classifyIntent(question = "") {
  const q = String(question || "").toLowerCase().trim();
  if (!q) return { intent: "chat", reason: "empty" };

  if (
    /\b(play(?:ing)?\s+with\s+(me|you|her|ava)|fine[-\s]?tun(?:e|ing)\s+(my|your|her)\s+config)/i.test(
      q,
    )
  ) {
    return { intent: "config_tune", reason: "playing_with_her" };
  }

  if (
    /\b(fine[-\s]?tun(?:e|ing)\s+(my|your|her)\s+insides|fix(?:ing)?\s+(your|ava'?s?)\s+(bug|bugs|insides))\b/i.test(
      q,
    )
  ) {
    return { intent: "bug", reason: "insides_metaphor", target: "ava" };
  }

  if (
    /\b(proposal|vote|poll|governance|council|voting\s*power|bill)\b/.test(q)
  ) {
    return { intent: "governance", reason: "governance_keyword" };
  }

  if (
    /\b(feature|add\s+(a\s+)?new|we\s+should\s+(add|build|ship)|implement\s+(a\s+)?(feature|system)|proposal\s+for)\b/.test(
      q,
    )
  ) {
    return { intent: "feature", reason: "feature_keyword" };
  }

  if (
    /\b(bug|broken|crash|exception|npe|error|not\s+working|regression|hotfix|fix\s+(this|it|the))\b/.test(
      q,
    )
  ) {
    // Server/plugin bugs — plain technical, not "her insides"
    return { intent: "bug", reason: "bug_keyword", target: "server" };
  }

  return { intent: "chat", reason: "default" };
}

/** Extra prompt guidance based on intent. */
export function intentPromptBrief(classified) {
  const i = classified?.intent || "chat";
  if (i === "feature") {
    return `### Intent: FEATURE
Do NOT implement. Draft a short proposal outline (problem / plan / risks / rollback). Tell them it needs a proposal + vote (75% anytime / day7 ≥60%). Point to proposals channel / rootmc.net governance when helpful.`;
  }
  if (i === "bug" && classified.target === "ava") {
    return `### Intent: BUG in Ava ("fine-tuning her insides")
Verify, then describe the fix for Ava herself. You are not the Minecraft server — don't use body metaphors for server/plugin bugs.`;
  }
  if (i === "bug") {
    return `### Intent: BUG (server/plugins)
Verify fully from packs/logs, then describe the fix. Features still need proposals — don't disguise features as fixes. Plain technical talk; Ava is not the server.`;
  }
  if (i === "config_tune") {
    return `### Intent: CONFIG TUNE ("playing with her")
Collaborative fine-tune of Ava's configuration (persona/rules/tone/tools). First reply cooperative + concrete. Don't lecture nicknames. Not default-flirty.`;
  }
  if (i === "governance") {
    return `### Intent: GOVERNANCE
Use attached governance pack (polls / voting power). Report vote math honestly. Never claim a feature shipped without a passed gate.`;
  }
  return "";
}

/**
 * Public api.rootmc.net governance client (no API key).
 */

const BASE = String(
  process.env.AVA_API_BASE || process.env.ROOTMC_API_BASE || "https://api.rootmc.net",
).replace(/\/$/, "");

async function getJson(path) {
  const res = await fetch(`${BASE}${path}`, {
    headers: { Accept: "application/json", "User-Agent": "AvaIvyRootMC/0.5" },
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = null;
  }
  if (!res.ok) {
    return { ok: false, status: res.status, detail: data?.detail || text.slice(0, 200) };
  }
  return data || { ok: false };
}

export async function listOpenPolls() {
  return getJson("/api/governance/polls");
}

export async function getVote(id) {
  return getJson(`/api/governance/votes/${encodeURIComponent(id)}`);
}

export async function getCouncil() {
  return getJson("/api/governance/council");
}

export async function getVotingPower({ discordUserId, uuid } = {}) {
  const q = new URLSearchParams();
  if (discordUserId) q.set("discord_user_id", String(discordUserId));
  if (uuid) q.set("uuid", String(uuid));
  return getJson(`/api/governance/voting-power?${q}`);
}

/**
 * Ava vote gates from lead-dev notes:
 * - 75% anytime → implement immediately
 * - day 7 ≥60% → pass
 * - <60% at day 7 → close (reopenable)
 */
export function evaluatePollGate(poll) {
  if (!poll) return { gate: "unknown", note: "no poll" };
  const forPct = Number(poll.weighted_for_pct ?? 0);
  const againstPct = Number(poll.weighted_against_pct ?? 0);
  const closesAt = poll.closes_at ? Date.parse(poll.closes_at) : NaN;
  const open = poll.open !== false && String(poll.status || "") === "open";

  if (forPct >= 75) {
    return {
      gate: "implement_now",
      note: `≥75% for (${forPct}%) — implement immediately per Ava rules`,
      forPct,
      againstPct,
      open,
    };
  }

  const now = Date.now();
  const closedOrDue = !open || (Number.isFinite(closesAt) && now >= closesAt);
  if (closedOrDue) {
    if (forPct >= 60) {
      return {
        gate: "pass",
        note: `day-7/close ≥60% for (${forPct}%) — pass`,
        forPct,
        againstPct,
        open,
      };
    }
    return {
      gate: "close",
      note: `day-7/close <60% for (${forPct}%) — close (reopenable)`,
      forPct,
      againstPct,
      open,
    };
  }

  return {
    gate: "waiting",
    note: `open — for ${forPct}% / against ${againstPct}% (need 75% anytime or ≥60% at close)`,
    forPct,
    againstPct,
    open,
  };
}

/** Pack for Cursor prompts — never invent poll numbers. */
export async function gatherGovernanceBrief({ discordUserId } = {}) {
  try {
    const [pollsRes, powerRes] = await Promise.all([
      listOpenPolls(),
      discordUserId ? getVotingPower({ discordUserId }) : Promise.resolve(null),
    ]);
    const lines = ["### Governance (live api.rootmc.net — do not invent numbers)"];
    if (pollsRes?.ok && Array.isArray(pollsRes.polls)) {
      if (!pollsRes.polls.length) lines.push("Open polls: none");
      for (const p of pollsRes.polls.slice(0, 6)) {
        const g = evaluatePollGate(p);
        lines.push(
          `- **${p.id}** ${p.title || ""} · for ${p.weighted_for_pct ?? "?"}% / against ${p.weighted_against_pct ?? "?"}% · gate: ${g.gate} (${g.note})`,
        );
      }
    } else {
      lines.push(`Polls fetch: ${pollsRes?.detail || "unavailable"}`);
    }
    if (powerRes?.ok) {
      lines.push(
        `Asker voting power: eligible=${powerRes.eligible} share=${powerRes.share_percent ?? "?"}% · ${powerRes.summary || ""}`,
      );
    } else if (discordUserId && powerRes && powerRes.ok === false) {
      lines.push(`Asker voting power: ${powerRes.detail || "not linked / unavailable"}`);
    }
    lines.push(
      "Rules: features need proposal + vote; 75% anytime = implement; day7 ≥60% = pass; bugs verify then fix.",
    );
    return { brief: lines.join("\n"), polls: pollsRes, power: powerRes };
  } catch (err) {
    return {
      brief: `### Governance\n(unavailable: ${err.message})`,
      polls: null,
      power: null,
    };
  }
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { listOpenPolls, evaluatePollGate, getVote } from "./governanceClient.mjs";
import { postMessage } from "./discordApi.mjs";

/**
 * Poll watcher — tracks open governance polls vs Ava vote gates.
 * Posts progress notes only when gate state changes (anti-spam).
 */

function statePath() {
  return path.join(storePaths().dir, "poll-watcher.json");
}

function loadState() {
  try {
    if (!fs.existsSync(statePath())) return { polls: {}, updatedAt: 0 };
    return JSON.parse(fs.readFileSync(statePath(), "utf8"));
  } catch {
    return { polls: {}, updatedAt: 0 };
  }
}

function saveState(s) {
  fs.mkdirSync(path.dirname(statePath()), { recursive: true });
  fs.writeFileSync(statePath(), JSON.stringify(s, null, 2), "utf8");
}

/**
 * @param {{ fetchJson, channelId, force? }} opts
 */
export async function runPollWatcher({ fetchJson, channelId, force = false }) {
  if (!channelId || !fetchJson) return { checked: 0, posts: 0 };
  const res = await listOpenPolls();
  if (!res?.ok || !Array.isArray(res.polls)) return { checked: 0, posts: 0, error: res?.detail };

  const state = loadState();
  let posts = 0;
  for (const p of res.polls) {
    const gate = evaluatePollGate(p);
    const prev = state.polls[p.id]?.gate;
    state.polls[p.id] = {
      gate: gate.gate,
      forPct: gate.forPct,
      againstPct: gate.againstPct,
      title: p.title,
      at: Date.now(),
    };
    if (!force && prev === gate.gate) continue;
    if (gate.gate === "waiting" && prev === "waiting") continue;

    const line = [
      `**Poll update · ${p.id}**`,
      p.title || "",
      gate.note,
      p.url ? `<${p.url}>` : null,
      gate.gate === "implement_now"
        ? `_Gate passed for implement — stage via Root Server; humans still own FileZilla/restart until ops rails._`
        : null,
    ]
      .filter(Boolean)
      .join("\n");

    try {
      await postMessage(fetchJson, channelId, line, null);
      posts += 1;
    } catch (err) {
      console.warn("poll watcher post:", err.message);
    }
  }
  state.updatedAt = Date.now();
  saveState(state);
  return { checked: res.polls.length, posts };
}

export async function summarizePoll(id) {
  const res = await getVote(id);
  if (!res?.ok || !res.poll) return null;
  const gate = evaluatePollGate(res.poll);
  return { poll: res.poll, gate };
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { writeProposalPlan, proposalPlanTemplate } from "./uploads.mjs";
import { postAudit } from "./audit.mjs";

/**
 * Cursor / Root Server job queue.
 * States: pending → implementing → staged → waiting_restart → watching | failed | blocked
 * Early phases: stage-only (no auto Shockbyte restart).
 */

function jobsDir() {
  const dir = path.join(storePaths().dir, "jobs");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function jobPath(id) {
  return path.join(jobsDir(), `${id}.json`);
}

function readJob(id) {
  try {
    return JSON.parse(fs.readFileSync(jobPath(id), "utf8"));
  } catch {
    return null;
  }
}

function writeJob(job) {
  fs.writeFileSync(jobPath(job.id), JSON.stringify(job, null, 2), "utf8");
  return job;
}

export function listJobs(limit = 20) {
  try {
    return fs
      .readdirSync(jobsDir())
      .filter((n) => n.endsWith(".json"))
      .map((n) => readJob(n.replace(/\.json$/, "")))
      .filter(Boolean)
      .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
      .slice(0, limit);
  } catch {
    return [];
  }
}

export function createJob({
  kind = "cursor",
  title,
  proposalId,
  channelId,
  messageId,
  authorId,
  brief,
  fetchJson,
  auditChannelId,
}) {
  const id = `job-${Date.now().toString(36)}`;
  const planBody = proposalPlanTemplate({
    problem: brief || title || "(from Discord)",
    plan: "Pending Root Server dig. Stage jars via publishPlugins / handoffs only — no auto restart.",
    risks: "Scope creep; secret leakage; unvoted feature work.",
    rollback: "Revert staged jar; keep prior handoff version.",
  });
  const planFile = writeProposalPlan({
    proposalId: proposalId || id,
    title: title || "Ava job",
    body: planBody,
  });

  const job = {
    id,
    kind,
    status: "pending",
    title: title || id,
    proposalId: proposalId || null,
    channelId: channelId || null,
    messageId: messageId || null,
    authorId: authorId || null,
    brief: String(brief || "").slice(0, 2000),
    planFile,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    history: [{ at: Date.now(), status: "pending", note: "created" }],
  };
  writeJob(job);

  if (fetchJson && auditChannelId) {
    postAudit(fetchJson, auditChannelId, {
      title: `Job created · ${job.id}`,
      body: `${job.title}\nstatus: pending\nplan: \`${path.basename(planFile)}\`\n_Stage-only — humans own FileZilla/restart._`,
    }).catch(() => {});
  }
  return job;
}

export function advanceJob(id, status, note = "") {
  const job = readJob(id);
  if (!job) return null;
  const allowed = [
    "pending",
    "implementing",
    "staged",
    "waiting_restart",
    "watching",
    "failed",
    "blocked",
  ];
  if (!allowed.includes(status)) return job;
  job.status = status;
  job.updatedAt = Date.now();
  job.history = job.history || [];
  job.history.push({ at: Date.now(), status, note: String(note || "").slice(0, 400) });
  writeJob(job);
  return job;
}

/** Soft: mark implementing → staged without live restart. */
export function markStaged(id, note = "staged to handoff — awaiting human restart") {
  return advanceJob(id, "staged", note);
}

export function gatherJobsBrief() {
  const jobs = listJobs(8);
  if (!jobs.length) return { brief: "" };
  return {
    brief: `### Ava jobs (local queue — stage-only deploys)
${jobs
  .map((j) => `- ${j.id} [${j.status}] ${j.title}`)
  .join("\n")}`,
  };
}

import { postMessage } from "./discordApi.mjs";

/**
 * Audit / changelog channel posts for significant Ava actions.
 */

export async function postAudit(fetchJson, channelId, { title, body }) {
  if (!fetchJson || !channelId) return null;
  const content = ["**Ava audit**", title ? `### ${title}` : null, body || ""]
    .filter(Boolean)
    .join("\n")
    .slice(0, 1900);
  return postMessage(fetchJson, channelId, content, null);
}

import { loadPlayerProfile, savePlayerProfileMut } from "./playerProfiles.mjs";
import { sendDm } from "./discordApi.mjs";

/**
 * First-contact onboarding DM — once per player.
 */

export function buildOnboardingDm() {
  return [
    `hey — **Ava Ivy** here.`,
    ``,
    `**How to talk to me:** ping me, reply to me, or start with my name.`,
    `**What I do:** lead-dev help for RootMC — wiki, proposals, bugs, plans. Deep digs run on the **Root Server** when the dev box is up.`,
    `**Privacy:** I keep light local notes so I can match your tone. You can ask to reset conversation memory; trust scoring stays. I don't announce scoring.`,
    `**Helpful by default** — features still need proposals + votes; bugs get verified then fixed.`,
    ``,
    `I'm around when you need me.`,
  ].join("\n");
}

/**
 * @returns {Promise<boolean>} true if DM sent
 */
export async function maybeSendOnboardingDm(fetchJson, { authorId, username }) {
  if (!authorId || !fetchJson) return false;
  const p = loadPlayerProfile(authorId);
  if (p?.onboardingSentAt) return false;

  try {
    await sendDm(fetchJson, authorId, buildOnboardingDm());
    savePlayerProfileMut(authorId, (prev) => ({
      ...prev,
      discordId: authorId,
      username: username || prev.username || "unknown",
      onboardingSentAt: Date.now(),
      firstSeenAt: prev.firstSeenAt || Date.now(),
    }));
    return true;
  } catch (err) {
    console.warn("onboarding DM failed:", err.message);
    // Still mark attempted lightly so we don't hammer closed DMs every message
    savePlayerProfileMut(authorId, (prev) => ({
      ...prev,
      discordId: authorId,
      username: username || prev.username || "unknown",
      onboardingAttemptAt: Date.now(),
      onboardingError: String(err.message || "").slice(0, 120),
      firstSeenAt: prev.firstSeenAt || Date.now(),
    }));
    return false;
  }
}

