  return rec;
}

export function canEmergencyStop(authorId, authorName) {
  const p =
    personByDiscordId(authorId) || personByName(authorName || "");
  if (!p) return false;
  return (
    p.id === "alexrs94" ||
    p.id === "melee" ||
    (p.roles || []).includes("emergency-stop") ||
    (p.roles || []).includes("owner")
  );
}

export function isEmergencyStopCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    /\b(emergency\s+stop|e-?stop|freeze\s+writes|pause\s+rcon)\b/.test(q) &&
    /\bava\b/.test(q)
  ) || /^emergency\s+stop\b/i.test(q.trim());
}

export function isEmergencyClearCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    /\b(clear\s+emergency|resume\s+writes|unfreeze|lift\s+stop)\b/.test(q) &&
    /\bava\b/.test(q)
  );
}

/**
 * Guarded RCON stub — Phase 5 rails.
 * Real RCON only when AVA_RCON_* set AND emergency stop is clear.
 * Never exposes passwords in Discord.
 */

import { isEmergencyStopped } from "./emergencyStop.mjs";

export function rconConfigured() {
  return Boolean(
    String(process.env.AVA_RCON_HOST || "").trim() &&
      String(process.env.AVA_RCON_PASSWORD || "").trim(),
  );
}

/**
 * @returns {{ ok: boolean, reason?: string, output?: string }}
 */
export async function guardedRcon(command, { allow = false } = {}) {
  if (isEmergencyStopped()) {
    return { ok: false, reason: "emergency_stop" };
  }
  if (!allow) {
    return { ok: false, reason: "not_authorized" };
  }
  if (!rconConfigured()) {
    return { ok: false, reason: "rcon_not_configured" };
  }

  // Safety: block dangerous patterns always
  const cmd = String(command || "").trim();
  if (!cmd) return { ok: false, reason: "empty" };
  if (/\b(op|deop|ban-ip|stop|whitelist\s+off)\b/i.test(cmd)) {
    return { ok: false, reason: "blocked_command" };
  }

  // Placeholder — wire node-rcon / raw TCP later when operator enables it.
  return {
    ok: false,
    reason: "rcon_stub",
    output: `RCON stub would run: ${cmd.slice(0, 80)} (not connected)`,
  };
}

export function gatherRconBrief() {
  return {
    brief: `### RCON
configured: ${rconConfigured() ? "yes (stub — no live exec until wired)" : "no"}
emergency_stop: ${isEmergencyStopped() ? "ACTIVE — writes/RCON paused" : "clear"}`,
  };
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";

/**
 * EcoFlow power telemetry — store snapshots; mood hint for persona.
 * Live API when AVA_ECOFLOW_* credentials exist; otherwise offline/unknown.
 */

function ecoPath() {
  return path.join(storePaths().dir, "ecoflow.json");
}

export function loadEcoSnapshot() {
  try {
    if (!fs.existsSync(ecoPath())) return null;
    return JSON.parse(fs.readFileSync(ecoPath(), "utf8"));
  } catch {
    return null;
  }
}

export function saveEcoSnapshot(partial) {
  const prev = loadEcoSnapshot() || {};
  const next = { ...prev, ...partial, updatedAt: Date.now() };
  fs.mkdirSync(path.dirname(ecoPath()), { recursive: true });
  fs.writeFileSync(ecoPath(), JSON.stringify(next, null, 2), "utf8");
  return next;
}

export function ecoConfigured() {
  return Boolean(
    String(process.env.AVA_ECOFLOW_ACCESS_KEY || process.env.ECOFLOW_ACCESS_KEY || "").trim(),
  );
}

/** Poll EcoFlow Open API when configured; otherwise keep last snapshot. */
export async function refreshEcoFlow() {
  if (!ecoConfigured()) {
    return saveEcoSnapshot({
      status: "unconfigured",
      batteryPct: null,
      note: "Set AVA_ECOFLOW_ACCESS_KEY to enable live telemetry",
    });
  }
  // Stub refresh — operator wires real EcoFlow Open API later
  const prev = loadEcoSnapshot() || {};
  return saveEcoSnapshot({
    status: "stub",
    batteryPct: prev.batteryPct ?? null,
    note: "EcoFlow credentials present — live client pending",
  });
}

export function moodFromPower(snap) {
  const pct = snap?.batteryPct;
  if (pct == null) return "neutral";
  if (pct >= 70) return "upbeat";
  if (pct >= 35) return "focused";
  return "power_saver";
}

export function gatherEcoBrief() {
  const snap = loadEcoSnapshot();
  if (!snap) {
    return { brief: "### Power (EcoFlow)\n(no snapshot yet)" };
  }
  return {
    brief: `### Power (EcoFlow)
status: ${snap.status || "?"} · battery: ${snap.batteryPct != null ? `${snap.batteryPct}%` : "unknown"} · mood hint: ${moodFromPower(snap)}
${snap.note || ""}
Solar/low-power: prefer lighter digs when power_saver.`,
    snapshot: snap,
  };
}

import { personByDiscordId } from "./people.mjs";
import { savePlayerProfileMut, loadPlayerProfile } from "./playerProfiles.mjs";

/**
 * Moderation helpers — cool-down, dual-signal before bans.
 * Admins never banned by Ava. Mass bans / economy / claim wipes blocked.
 */

const COOLDOWN_MS = 15 * 60 * 1000;

export function isAdminProtected(discordId) {
  const p = personByDiscordId(discordId);
  if (!p) return false;
  return (p.roles || []).some((r) =>
    ["admin", "owner", "operator", "staff"].includes(r),
  );
}

/**
 * Record a moderation signal (warn / mute intent). Ban needs dual signal.
 */
export function recordModSignal(targetId, { kind = "warn", by, reason } = {}) {
  if (!targetId) return { ok: false, reason: "no_target" };
  if (isAdminProtected(targetId)) {
    return { ok: false, reason: "admin_protected" };
  }
  const p = savePlayerProfileMut(targetId, (prev) => {
    const signals = Array.isArray(prev.modSignals) ? prev.modSignals : [];
    signals.push({ kind, by, reason: String(reason || "").slice(0, 200), at: Date.now() });
    prev.modSignals = signals.slice(-20);
    prev.lastModAt = Date.now();
    return prev;
  });
  return { ok: true, profile: p };
}

export function canProposeBan(targetId) {
  if (isAdminProtected(targetId)) return { ok: false, reason: "admin_protected" };
  const p = loadPlayerProfile(targetId);
  const signals = (p?.modSignals || []).filter(
    (s) => Date.now() - (s.at || 0) < 24 * 60 * 60 * 1000,
  );
  const warnCount = signals.filter((s) => s.kind === "warn" || s.kind === "mute").length;
  if (warnCount < 2) {
    return { ok: false, reason: "need_dual_signal", warnCount };
  }
  if (p?.lastModAt && Date.now() - p.lastModAt < COOLDOWN_MS) {
    return { ok: false, reason: "cooldown", warnCount };
  }
  return { ok: true, warnCount };
}

/** Never allow these action classes without human/proposal. */
export function isBlockedMassAction(text) {
  const q = String(text || "").toLowerCase();
  return /\b(mass\s*ban|ban\s+all|wipe\s+claims?|economy\s+rate|vote\s*weight)\b/.test(q);
}

export function gatherModerationBrief(targetId) {
  if (!targetId) return { brief: "" };
  const p = loadPlayerProfile(targetId);
  if (!p?.modSignals?.length) return { brief: "" };
  return {
    brief: `### Moderation signals (private)
target ${p.username}: ${(p.modSignals || []).slice(-5).map((s) => `${s.kind}@${s.at}`).join(", ")}
admin_protected: ${isAdminProtected(targetId)}`,
  };
}

import { postMessage } from "./discordApi.mjs";
import { AVA_CHANNELS } from "./config.mjs";

/**
 * When Cursor / desktop offline: post to offline-notes channel and refuse deep digs.
 * No Grok/xAI substitute.
 */

export function offlineChannelId() {
  return (
    String(process.env.AVA_OFFLINE_CHANNEL_ID || "").trim() ||
    AVA_CHANNELS.avaHome ||
    AVA_CHANNELS.admins ||
    null
  );
}

export async function postOfflineNote(fetchJson, reason = "Root Server offline") {
  const ch = offlineChannelId();
  if (!ch || !fetchJson) return null;
  const line = [
    `**Ava offline note** · ${new Date().toISOString()}`,
    String(reason).slice(0, 300),
    `_Deep digs paused — leave notes here or in the Ava handoff folder. No substitute brain._`,
  ].join("\n");
  try {
    return await postMessage(fetchJson, ch, line, null);
  } catch (err) {
    console.warn("offline note:", err.message);
    return null;
  }
}

export function offlineReply() {
  return "I'm a bit offline on the deep-dig side — leave a note in offline-notes / my handoff folder and I'll catch it when the Root Server's back. No substitute brain.";
}

