/**
 * Discord Gateway transport — Message Content + DMs + guild messages.
 * Prefer over REST poller for latency; poller remains emergency fallback.
 */
import WebSocket from "ws";
import { DISCORD_API, watchChannels, ROOTMC_GUILD_ID } from "./config.mjs";
import { authHeaders } from "./discordApi.mjs";

const INTENTS =
  (1 << 0) | // GUILDS
  (1 << 9) | // GUILD_MESSAGES
  (1 << 12) | // DIRECT_MESSAGES
  (1 << 15); // MESSAGE_CONTENT

/**
 * @param {{ token, onMessage, onReady, watchIds? }} opts
 */
export function startGateway({ token, onMessage, onReady, watchIds }) {
  let ws = null;
  let hb = null;
  let seq = null;
  let sessionId = null;
  let resumeUrl = null;
  let alive = true;

  const watch = new Set(
    (watchIds || watchChannels({}) || []).map(String).filter(Boolean),
  );

  async function gatewayUrl() {
    const res = await fetch(`${DISCORD_API}/gateway/bot`, {
      headers: authHeaders(token),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(`gateway/bot ${res.status}`);
    return data.url;
  }

  function identify() {
    ws.send(
      JSON.stringify({
        op: 2,
        d: {
          token,
          intents: INTENTS,
          properties: { os: "windows", browser: "ava-ivy", device: "ava-ivy" },
        },
      }),
    );
  }

  function startHeartbeat(ms) {
    if (hb) clearInterval(hb);
    hb = setInterval(() => {
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ op: 1, d: seq }));
      }
    }, ms);
  }

  async function connect() {
    const base = resumeUrl || (await gatewayUrl());
    const url = `${base}?v=10&encoding=json`;
    ws = new WebSocket(url);

    ws.on("open", () => {
      console.log("Ava gateway open");
    });

    ws.on("message", (raw) => {
      let pkt;
      try {
        pkt = JSON.parse(String(raw));
      } catch {
        return;
      }
      if (pkt.s != null) seq = pkt.s;

      if (pkt.op === 10) {
        startHeartbeat(pkt.d.heartbeat_interval);
        if (sessionId && resumeUrl) {
          ws.send(
            JSON.stringify({
              op: 6,
              d: { token, session_id: sessionId, seq },
            }),
          );
        } else {
          identify();
        }
        return;
      }

      if (pkt.op === 0) {
        const t = pkt.t;
        const d = pkt.d;
        if (t === "READY") {
          sessionId = d.session_id;
          resumeUrl = d.resume_gateway_url || resumeUrl;
          console.log("Ava gateway READY as", d.user?.username);
          onReady?.(d);
          return;
        }
        if (t === "MESSAGE_CREATE" && d) {
          // Guild: only allowlisted channels (+ DMs always)
          const isDm = !d.guild_id;
          const inGuild = String(d.guild_id || "") === String(ROOTMC_GUILD_ID);
          if (!isDm && !inGuild) return;
          if (!isDm && watch.size && !watch.has(String(d.channel_id))) {
            // Still allow if channel later added to watch via home channel
            // — skip non-watch guild channels
            return;
          }
          onMessage?.(d, { isDm });
        }
      }
    });

    ws.on("close", (code) => {
      console.warn("Ava gateway closed", code);
      if (hb) clearInterval(hb);
      if (!alive) return;
      setTimeout(() => {
        connect().catch((err) => console.warn("gateway reconnect:", err.message));
      }, 5000);
    });

    ws.on("error", (err) => {
      console.warn("Ava gateway error:", err.message);
    });
  }

  connect().catch((err) => {
    console.error("Ava gateway failed to start:", err.message);
  });

  return {
    addWatch(id) {
      if (id) watch.add(String(id));
    },
    stop() {
      alive = false;
      if (hb) clearInterval(hb);
      try {
        ws?.close();
      } catch {
        /* ignore */
      }
    },
  };
}

/**
 * Shared live-message pipeline for poller + gateway.
 */
import {
  extractQuestion,
  looksLikeAvaTrigger,
  recommend,
  isHushCommand,
  isWakeCommand,
} from "./recommend.mjs";
import {
  buildPlayerContext,
  rememberPlayerLine,
  memoryContext,
} from "./playerContext.mjs";
import { pickInstantOpen, pickHold, holdBeatDelays } from "./instantLines.mjs";
import { brainQueueDepth, beginAsk, endAsk } from "./cursorBrain.mjs";
import {
  isHushed,
  setHushed,
  lastReplyFor,
  setLastReply,
  nearDuplicate,
  pushStatusEvent,
} from "./store.mjs";
import { isAvaOwnMessage } from "./guildScout.mjs";
import { silentlyProfileMessage } from "./playerProfiles.mjs";
import {
  tryLearnFromMessage,
} from "./reactionStore.mjs";
import { saveMessageAttachments } from "./uploads.mjs";
import { maybeSendOnboardingDm } from "./onboarding.mjs";
import { persistTurn } from "./conversationStore.mjs";
import { classifyIntent } from "./classify.mjs";
import {
  createJob,
  markStaged,
} from "./jobQueue.mjs";
import {
  isEmergencyStopCommand,
  isEmergencyClearCommand,
  canEmergencyStop,
  setEmergencyStop,
  isEmergencyStopped,
} from "./emergencyStop.mjs";
import { isBlockedMassAction } from "./moderation.mjs";
import { AVA_CHANNELS } from "./config.mjs";
import { postMessage } from "./discordApi.mjs";

const busyChannels = new Set();

export function pipelineBusyCount() {
  return busyChannels.size;
}

function startHoldTransfers(replyFn, channelId, refId, queueDepth) {
  const delays = holdBeatDelays(queueDepth);
  const state = { timers: [], done: false };
  const beat = async (n) => {
    if (state.done) return;
    const line = pickHold(n);
    if (!line) return;
    try {
      await replyFn(channelId, line, refId);
    } catch {
      /* ignore */
    }
  };
  state.timers.push(setTimeout(() => beat(1), delays.beat1));
  state.timers.push(setTimeout(() => beat(2), delays.beat2));
  state.timers.push(setTimeout(() => beat(3), delays.beat3));
  return {
    stop() {
      state.done = true;
      for (const t of state.timers) clearTimeout(t);
    },
  };
}

/**
 * @param {object} deps
 * @param {Function} deps.fetchJson
 * @param {Function} deps.reply - (channelId, content, refId) => Promise
 * @param {string} deps.botAppId
 * @param {object} deps.env
 * @param {Function} [deps.touchActivity]
 * @param {Function} [deps.pulseHeartbeat]
 * @param {Function} [deps.onBreakState] - () => boolean wasBreak; and setter
 */
export function createPipeline(deps) {
  const {
    fetchJson,
    reply,
    botAppId,
    env,
    touchActivity = () => {},
    pulseHeartbeat = () => {},
    getOnBreak = () => false,
    setOnBreak = () => {},
  } = deps;

  async function handleTrigger(channelId, msg, messages = []) {
    if (busyChannels.has(channelId)) return;
    busyChannels.add(channelId);
    const holds = { stop() {} };
    try {
      const wasBreak = getOnBreak();
      touchActivity("ping");

      const uploads = await saveMessageAttachments(msg);
      if (uploads.length) {
        pushStatusEvent(`uploads · ${uploads.length}`);
      }

      // First-contact DM (once)
      if (msg.author?.id) {
        maybeSendOnboardingDm(fetchJson, {
          authorId: msg.author.id,
          username: msg.author.username,
        }).catch(() => {});
      }

      const depthAtAck = brainQueueDepth();
      const openLine = pickInstantOpen({
        fromBreak: wasBreak,
        queueDepth: depthAtAck,
      });
      const ackP = reply(channelId, openLine, msg.id).catch((err) => {
        console.warn("ack failed:", err.message);
      });
      beginAsk();

      let question =
        extractQuestion(msg.content) || "you pinged me — what's up?";
      if (uploads.length) {
        question += `\n\n[attachments saved to handoff uploads/: ${uploads.join(", ")}]`;
      }

      const classified = classifyIntent(question);
      const liveCtx = buildPlayerContext({
        trigger: msg,
        messages,
        avaBotId: botAppId,
      });
      const mem = memoryContext(channelId, msg.author?.id);
      const context = [mem, liveCtx].filter(Boolean).join("\n\n").slice(0, 5500);

      Object.assign(
        holds,
        startHoldTransfers(reply, channelId, msg.id, depthAtAck),
      );

      console.log(
        `ava trigger in ${channelId} from ${msg.author?.username} intent=${classified.intent} (queue=${depthAtAck})`,
      );
      pushStatusEvent(
        `ask · ${msg.author?.username || "?"}: ${question.slice(0, 100)}`,
      );
      pulseHeartbeat({ digging: true, lastAsk: question.slice(0, 120) });

      if (msg.author?.id && !isAvaOwnMessage(msg, botAppId)) {
        silentlyProfileMessage(msg, channelId, "live");
      }

      if (isBlockedMassAction(question)) {
        holds.stop();
        await ackP;
        const deny =
          "Nope — mass bans / economy rates / claim wipes / vote-weight changes need a human + proposal. Not doing that solo.";
        await reply(channelId, deny, msg.id);
        persistTurn({
          channelId,
          messageId: msg.id,
          authorId: msg.author?.id,
          authorName: msg.author?.username,
          question,
          answer: deny,
          intent: "blocked",
        });
        return;
      }

      let jobId = null;
      if (
        (classified.intent === "feature" || classified.intent === "bug") &&
        !isEmergencyStopped()
      ) {
        const job = createJob({
          kind: classified.intent,
          title: question.slice(0, 80),
          channelId,
          messageId: msg.id,
          authorId: msg.author?.id,
          brief: question,
          fetchJson,
          auditChannelId: AVA_CHANNELS.audit,
        });
        jobId = job.id;
        // Stage-only marker after create (humans restart)
        markStaged(job.id, "plan filed — awaiting Root Server dig / human stage");
      }

      let answer;
      try {
        answer = await recommend({
          question,
          context,
          env,
          authorId: msg.author?.id || "",
          authorName: msg.author?.username || msg.author?.global_name || "",
          intent: classified,
        });
      } finally {
        endAsk();
      }
      holds.stop();
      await ackP;
      touchActivity("answered");
      pushStatusEvent(`answered · ${msg.author?.username || "?"}`);
      pulseHeartbeat({ digging: false });

      if (nearDuplicate(answer, lastReplyFor(channelId))) {
        console.log("skip near-duplicate answer");
        return;
      }
      await reply(channelId, answer, msg.id);
      setLastReply(channelId, answer);
      rememberPlayerLine(channelId, botAppId, "Ava", answer);
      persistTurn({
        channelId,
        messageId: msg.id,
        authorId: msg.author?.id,
        authorName: msg.author?.username,
        question,
        answer,
        intent: classified.intent,
        jobId,
      });
    } finally {
      holds.stop();
      busyChannels.delete(channelId);
    }
  }

  /**
   * Process one inbound message (guild or DM).
   */
  async function ingestMessage(msg, { messages = [], isDm = false } = {}) {
    if (!msg?.id || !msg.channel_id) return;
    if (msg.author?.bot) return;
    if (String(msg.author?.id) === String(botAppId)) return;

    const channelId = msg.channel_id;
    const taught = tryLearnFromMessage({ ...msg, channel_id: channelId });
    if (taught) {
      touchActivity("emoji-learn");
      try {
        await reply(channelId, taught.thank, msg.id);
      } catch {
        /* ignore */
      }
      return;
    }

    if (isHushCommand(msg.content)) {
      setHushed(true, "user hush");
      setOnBreak(true);
      touchActivity("hush");
      pushStatusEvent("hushed");
      try {
        await reply(
          channelId,
          `Got it — going quiet.\nPing me when you want me back.`,
          msg.id,
        );
      } catch {
        /* ignore */
      }
      return;
    }

    if (isWakeCommand(msg.content)) {
      setHushed(false, "user wake");
      setOnBreak(false);
      touchActivity("wake");
      pushStatusEvent("woke");
      try {
        await reply(
          channelId,
          "I'm up. Give me a sec when you ask something — I think first.",
          msg.id,
        );
      } catch {
        /* ignore */
      }
      return;
    }

    if (
      isEmergencyStopCommand(msg.content) &&
      canEmergencyStop(msg.author?.id, msg.author?.username)
    ) {
      setEmergencyStop(true, {
        by: msg.author?.username,
        reason: "operator",
      });
      pushStatusEvent("emergency stop ON");
      await reply(
        channelId,
        "Emergency stop on — RCON/file-write jobs paused. I can still talk.",
        msg.id,
      );
      return;
    }
    if (
      isEmergencyClearCommand(msg.content) &&
      canEmergencyStop(msg.author?.id, msg.author?.username)
    ) {
      setEmergencyStop(false, { by: msg.author?.username, reason: "cleared" });
      pushStatusEvent("emergency stop OFF");
      await reply(channelId, "Emergency stop cleared.", msg.id);
      return;
    }

    if (isHushed()) return;

    const addressed =
      isDm ||
      looksLikeAvaTrigger(msg, botAppId) ||
      isReplyToAva(msg, messages, botAppId);
    if (!addressed) return;

    await handleTrigger(channelId, msg, messages);
  }

  return { ingestMessage, handleTrigger, busyChannels };
}

function isReplyToAva(msg, messages, botAppId) {
  const refId = msg?.message_reference?.message_id;
  if (!refId) return false;
  if (msg?.referenced_message?.author?.id) {
    return String(msg.referenced_message.author.id) === String(botAppId);
  }
  const ref = (messages || []).find((m) => m.id === refId);
  return Boolean(ref && String(ref.author?.id) === String(botAppId));
}

export { postMessage };

import { cursorApiKey } from "./config.mjs";
import { cursorRecommend } from "./cursorBrain.mjs";
import { scrubPublicReply } from "./scrub.mjs";
import { gatherSiteContext } from "./siteContext.mjs";
import { gatherLocalContext } from "./localContext.mjs";
import { gatherPeopleContext } from "./people.mjs";
import { gatherCoreSpec } from "./coreSpec.mjs";
import { gatherAppearanceContext } from "./appearance.mjs";
import { gatherGuildContext } from "./guildScout.mjs";
import {
  gatherAskerProfile,
  recordCursorUsage,
  usageSoftGateBrief,
} from "./playerProfiles.mjs";
import { gatherReactionStatsBrief } from "./reactionStore.mjs";
import { classifyIntent, intentPromptBrief } from "./classify.mjs";
import { gatherGovernanceBrief } from "./governanceClient.mjs";
import { gatherJobsBrief } from "./jobQueue.mjs";
import { gatherEcoBrief } from "./ecoflow.mjs";
import { gatherRconBrief } from "./rconGuard.mjs";
import { offlineReply } from "./offlineNotes.mjs";
import { isEmergencyStopped } from "./emergencyStop.mjs";

export { scrubPublicReply } from "./scrub.mjs";
export { stripForbiddenMentions } from "./scrub.mjs";

export function wantsRootServer(question) {
  const q = String(question || "").toLowerCase();
  if (String(process.env.AVA_FORCE_CURSOR || process.env.SEXI_FORCE_CURSOR || "").trim() === "1") {
    return true;
  }
  return (
    /\broot\s*server\b/.test(q) ||
    /\b(implement|code\s+this|build\s+it|ship\s+it|dig\s+into\s+(the\s+)?(repo|code|source))\b/.test(q) ||
    /\b(check|read|scan|look\s+at|verify|find)\s+(the\s+)?(repo|codebase|source|plugins?|logs?|files?)\b/.test(q) ||
    /\b(why\s+(is|did|does)|stack\s*trace|exception|crash|npe)\b/.test(q)
  );
}

export function isHushCommand(content) {
  const q = String(content || "").toLowerCase();
  return (
    (/\b(stop|hush|quiet|sleep|go\s+offline|shut\s+up)\b/.test(q) && /\bava\b/.test(q)) ||
    /^(stop|hush|quiet)\s*(ava)?[!?.]*$/i.test(q.trim())
  );
}

export function isWakeCommand(content) {
  const q = String(content || "").toLowerCase();
  return /\b(wake|come\s+back|you'?re\s+active|unmute)\b/.test(q) && /\bava\b/.test(q);
}

export function heuristicRecommend(question) {
  const q = String(question || "").toLowerCase();
  if (isCreepDemand(q)) {
    return scrubPublicReply("Fuck off.");
  }
  return scrubPublicReply(offlineReply());
}

/** Hard shut-down only — not mild banter / earned flirt. */
function isCreepDemand(q) {
  return /nudes?|onlyfans|\bdtf\b|hook\s*up|(come|get)\s+over\s+here|be\s+sexy\s+for\s+me|send\s+(pics?|nudes?)|rate\s+my\s+(dick|cock)/i.test(
    String(q || ""),
  );
}

/**
 * Cursor-only brain. Wiki + local packs go into the Cursor prompt.
 * Grok / xAI is unplugged — never called here.
 */
export async function recommend({
  question,
  context = "",
  env,
  authorId = "",
  authorName = "",
  intent = null,
}) {
  const q = String(question || "").trim();
  if (!q) {
    return scrubPublicReply(
      "What's up? Wiki, design, logs, proposals — fire away. Give me a sec when you ping; I think before I talk.",
    );
  }

  if (isCreepDemand(q)) {
    return scrubPublicReply("Fuck off.");
  }

  if (!cursorApiKey(env || {})) {
    return heuristicRecommend(q);
  }

  const classified = intent || classifyIntent(q);
  const core = gatherCoreSpec({ maxChars: 32000 });
  const people = gatherPeopleContext({ question: q, authorId, authorName });
  const appearance = gatherAppearanceContext();
  const guild = gatherGuildContext();
  const askerProfile = gatherAskerProfile(authorId);
  const reactions = gatherReactionStatsBrief();
  const jobs = gatherJobsBrief();
  const eco = gatherEcoBrief();
  const rcon = gatherRconBrief();
  const usage = usageSoftGateBrief(authorId);
  const intentBrief = intentPromptBrief(classified);

  const [site, local, gov] = await Promise.all([
    gatherSiteContext(q, { maxPages: 2, maxChars: 3500 }),
    Promise.resolve(gatherLocalContext(`${q}\n${context}`)),
    classified.intent === "governance" || /vote|poll|proposal|governance/.test(q.toLowerCase())
      ? gatherGovernanceBrief({ discordUserId: authorId })
      : Promise.resolve({ brief: "" }),
  ]);

  const packed = [
    core.brief,
    appearance.brief,
    people.brief,
    guild.brief,
    askerProfile.brief,
    usage.brief,
    reactions.brief,
    jobs.brief,
    eco.brief,
    rcon.brief,
    intentBrief,
    gov.brief,
    isEmergencyStopped() ? "### Emergency stop\nACTIVE — do not propose RCON/file writes; conversation OK." : "",
    context,
    site.brief.slice(0, 3000),
    local.brief.slice(0, 4500),
  ]
    .filter(Boolean)
    .join("\n\n");

  const deep =
    wantsRootServer(q) ||
    classified.intent === "bug" ||
    classified.intent === "feature";
  const cursor = await cursorRecommend({
    question: q,
    context: packed,
    env,
    deep,
  });

  if (cursor.ok && cursor.text) {
    recordCursorUsage(authorId);
    let text = cursor.text;
    if (usage.upsell && !/membership/i.test(text)) {
      text = `${text}\n\n_${usage.upsell}_`;
    }
    return text;
  }
  console.warn("Ava cursor:", cursor.reason);
  return heuristicRecommend(q);
}

/** Clear address to Ava — bot mention, reply handled by poller, or Ava / Ava Ivy. */
export function looksLikeAvaTrigger(contentOrMsg, botUserId) {
  if (contentOrMsg && typeof contentOrMsg === "object") {
    const msg = contentOrMsg;
    if (botUserId && Array.isArray(msg.mentions)) {
      if (msg.mentions.some((u) => String(u?.id) === String(botUserId))) return true;
    }
    return looksLikeAvaTrigger(msg.content || "", botUserId);
  }
  const raw = String(contentOrMsg || "").trim();
  if (!raw) return false;
  if (botUserId && (raw.includes(`<@${botUserId}>`) || raw.includes(`<@!${botUserId}>`))) {
    return true;
  }
  if (/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?([,:!?]|\s|$)/i.test(raw)) {
    return true;
  }
  if (/^ava(\s+ivy)?[!?.]*$/i.test(raw)) return true;
  return false;
}

/** @deprecated */
export const looksLikeSexiTrigger = looksLikeAvaTrigger;

export function extractQuestion(content) {
  return String(content || "")
    .replace(/<@!?\d+>/g, "")
    .replace(/^(hey\s+|hi\s+|yo\s+|ok\s+|okay\s+|alright\s+)?ava(\s+ivy)?[,:!]?\s*/i, "")
    .trim();
}

/**
 * REST poller — boot handshake, reaction harvest, emergency transport.
 * Live replies prefer Discord Gateway when AVA_TRANSPORT includes gateway.
 */
import {
  loadEnv,
  botToken,
  avaBotAppId,
  watchChannels,
  ROOTMC_GUILD_ID,
  AVA_TRANSPORT,
  AVA_CHANNELS,
} from "./config.mjs";
import { looksLikeAvaTrigger } from "./recommend.mjs";
import { brainQueueDepth } from "./cursorBrain.mjs";
import { rememberPlayerLine } from "./playerContext.mjs";
import {
  loadSeen,
  saveSeen,
  loadWatermark,
  saveWatermark,
  markShutdown,
  isHushed,
  storePaths,
  writeHeartbeat,
  pushStatusEvent,
} from "./store.mjs";
import {
  needsGuildIntro,
  scoutGuild,
  buildGuildIntroMessage,
  loadGuildProfile,
  saveGuildProfile,
  isAvaOwnMessage,
  avaHomeChannelId,
  refreshGuildAccess,
  buildAdminRequestMessage,
  FIRST_JOIN_PROTOCOL,
} from "./guildScout.mjs";
import {
  harvestReactionsFromMessages,
  loadReactionSummary,
  buildEmojiAskLine,
  markEmojiAsked,
  shouldAskAboutEmoji,
} from "./reactionStore.mjs";
import { makeFetchJson, postMessage } from "./discordApi.mjs";
import { createPipeline, pipelineBusyCount } from "./pipeline.mjs";
import { startGateway } from "./gateway.mjs";
import { runPollWatcher } from "./pollWatcher.mjs";
import { refreshEcoFlow } from "./ecoflow.mjs";
import { postOfflineNote } from "./offlineNotes.mjs";
import { cursorApiKey } from "./config.mjs";

const env = await loadEnv();
const token = botToken(env);
const botAppId = avaBotAppId(env);
if (token.length < 40) {
  console.error("AVA_DISCORD_BOT_TOKEN missing — poller idle");
  process.exit(1);
}
if (!botAppId) {
  console.error("AVA_DISCORD_APPLICATION_ID missing — poller idle");
  process.exit(1);
}

const fetchJson = makeFetchJson(token);
const reply = (channelId, content, refId) =>
  postMessage(fetchJson, channelId, content, refId);

const seen = loadSeen();
const watch = watchChannels(env);
const homeCh = avaHomeChannelId();
if (homeCh && !watch.includes(homeCh)) watch.push(homeCh);
if (AVA_CHANNELS.avaHome && !watch.includes(AVA_CHANNELS.avaHome)) {
  watch.push(AVA_CHANNELS.avaHome);
}

const ANNOUNCE_CHANNEL =
  process.env.AVA_ANNOUNCE_CHANNEL ||
  env.AVA_ANNOUNCE_CHANNEL ||
  homeCh ||
  AVA_CHANNELS.general;

const HOT_POLL_MS = Number(process.env.AVA_HOT_POLL_MS || process.env.SEXI_POLL_MS || 4_000);
const BREAK_POLL_MS = Number(process.env.AVA_BREAK_POLL_MS || 60_000);
const BREAK_AFTER_MS = Number(process.env.AVA_BREAK_AFTER_MS || 10 * 60_000);
const FETCH_LIMIT = Number(process.env.AVA_FETCH_LIMIT || 40);
const useGateway = AVA_TRANSPORT === "gateway" || AVA_TRANSPORT === "both";
const usePollerLive = AVA_TRANSPORT === "poller" || AVA_TRANSPORT === "both";

let live = false;
let tickRunning = false;
let onBreak = false;
let lastAsk = "";
let lastAskAt = 0;
let lastActivityAt = Date.now();
let pollTimer = null;
let lastPollWatch = 0;
let gatewayHandle = null;

function currentPollMs() {
  if (isHushed() || onBreak) return BREAK_POLL_MS;
  return HOT_POLL_MS;
}

function pulseHeartbeat(extra = {}) {
  writeHeartbeat({
    live,
    onBreak,
    hushed: isHushed(),
    mode: isHushed() ? "hush" : onBreak ? "break" : live ? "hot" : "boot",
    transport: AVA_TRANSPORT,
    pollMs: currentPollMs(),
    hotPollMs: HOT_POLL_MS,
    breakPollMs: BREAK_POLL_MS,
    lastActivityAt,
    queueDepth: brainQueueDepth(),
    watchCount: watch.length,
    busyChannels: pipelineBusyCount(),
    lastAsk,
    lastAskAt,
    botAppId,
    gateway: Boolean(gatewayHandle),
    reactions: (() => {
      const s = loadReactionSummary();
      return {
        total: s.totalReactions || 0,
        good: s.good || 0,
        bad: s.bad || 0,
        neutral: s.neutral || 0,
        messages: s.messagesTracked || 0,
      };
    })(),
    ...extra,
  });
}

function discordStamp(ms = Date.now()) {
  const unix = Math.floor(ms / 1000);
  return `<t:${unix}:F> · <t:${unix}:R>`;
}

function touchActivity(reason = "") {
  lastActivityAt = Date.now();
  if (onBreak && reason !== "break") {
    onBreak = false;
    pushStatusEvent(`wake from break · ${reason || "activity"}`);
  }
}

async function maybeEnterBreak() {
  if (!live || isHushed() || onBreak) return;
  if (Date.now() - lastActivityAt < BREAK_AFTER_MS) return;
  onBreak = true;
  pushStatusEvent("break · quiet");
  pulseHeartbeat();
}

function warmMemory(channelId, messages) {
  for (const m of [...(messages || [])].reverse()) {
    if (!m?.author || m.author.bot) continue;
    if (m.author.id === botAppId) continue;
    if (!m.content?.trim()) continue;
    rememberPlayerLine(channelId, m.author.id, m.author.username, m.content);
  }
}

function markSeen(id) {
  if (!id) return;
  seen.add(id);
  if (seen.size > 8000) {
    const drop = [...seen].slice(0, 2000);
    for (const x of drop) seen.delete(x);
  }
}

function snowflakeTime(id) {
  try {
    return Number((BigInt(id) >> 22n) + 1420070400000n);
  } catch {
    return 0;
  }
}

async function channelTargets() {
  const out = new Set(watch);
  if (watch.includes(AVA_CHANNELS.proposals)) {
    try {
      const active = await fetchJson(`/guilds/${ROOTMC_GUILD_ID}/threads/active`);
      for (const t of active?.threads || []) {
        if (t.parent_id === AVA_CHANNELS.proposals) out.add(t.id);
      }
    } catch (err) {
      console.warn("active threads:", err.message);
    }
  }
  return [...out];
}

async function askAboutUnknownEmojis(unknowns) {
  if (!unknowns?.length) return;
  const item = unknowns.find((u) => shouldAskAboutEmoji(u.key));
  if (!item?.apiParam || !item.channelId || !item.messageId) return;

  let users = [];
  try {
    const enc = encodeURIComponent(item.apiParam);
    users = await fetchJson(
      `/channels/${item.channelId}/messages/${item.messageId}/reactions/${enc}?limit=10`,
    );
  } catch (err) {
    console.warn("reaction users:", err.message);
    markEmojiAsked(item.key, null);
    return;
  }

  const person = (users || []).find(
    (u) => u?.id && !u.bot && String(u.id) !== String(botAppId),
  );
  if (!person) return;

  const line = buildEmojiAskLine({
    display: item.display,
    username: person.username,
  });
  try {
    const askMsg = await reply(item.channelId, line, item.messageId);
    markEmojiAsked(item.key, {
      key: item.key,
      display: item.display,
      apiParam: item.apiParam,
      channelId: item.channelId,
      messageId: item.messageId,
      askMessageId: askMsg?.id || null,
      askedUserId: person.id,
      askedUserName: person.username,
      askedAt: Date.now(),
    });
    pushStatusEvent(`emoji ask · ${item.display}`);
    touchActivity("emoji-ask");
  } catch (err) {
    console.warn("emoji ask failed:", err.message);
  }
}

const pipeline = createPipeline({
  fetchJson,
  reply,
  botAppId,
  env,
  touchActivity,
  pulseHeartbeat: (extra) => {
    if (extra?.lastAsk) {
      lastAsk = extra.lastAsk;
      lastAskAt = Date.now();
    }
    pulseHeartbeat(extra);
  },
  getOnBreak: () => onBreak,
  setOnBreak: (v) => {
    onBreak = Boolean(v);
  },
});

async function bootHandshake() {
  storePaths();

  const guildId = ROOTMC_GUILD_ID;
  if (needsGuildIntro(guildId)) {
    pushStatusEvent("first join — scouting guild");
    pulseHeartbeat({ mode: "scout" });
    try {
      const profile = await scoutGuild({
        fetchJson,
        guildId,
        avaBotId: botAppId,
        announceFallback: ANNOUNCE_CHANNEL,
      });
      const intro = buildGuildIntroMessage(profile);
      const channelId = profile.introChannelId || ANNOUNCE_CHANNEL;
      await reply(channelId, intro);
      profile.introducedAt = Date.now();
      profile.firstJoinProtocol = FIRST_JOIN_PROTOCOL;

      if (profile.access && !profile.access.ok) {
        const ask = buildAdminRequestMessage(
          {
            summary: {
              ok: profile.access.ok,
              administrator: profile.access.administrator,
              missing: profile.access.missing,
            },
          },
          { clientId: botAppId },
        );
        if (ask) {
          try {
            await reply(channelId, ask);
            profile.access.requestedAt = Date.now();
          } catch (err) {
            console.warn("admin request post failed:", err.message);
          }
        }
      }

      saveGuildProfile(guildId, profile);
      if (profile.avaChannelId && !watch.includes(profile.avaChannelId)) {
        watch.push(profile.avaChannelId);
        gatewayHandle?.addWatch?.(profile.avaChannelId);
      }
      pushStatusEvent(
        profile.avaChannelCreated
          ? `created #${profile.avaChannelName} + intro`
          : `guild intro · home #${profile.avaChannelName || "chat"}`,
      );
      console.log("Ava first-join intro posted to", channelId);
    } catch (err) {
      console.warn("guild scout/intro failed:", err.message);
      pushStatusEvent(`guild scout failed · ${err.message}`);
    }
  } else {
    try {
      const { profile, requestMessage } = await refreshGuildAccess({
        fetchJson,
        guildId,
        avaBotId: botAppId,
      });
      const lastAskPerms = profile.access?.requestedAt || 0;
      const week = 7 * 24 * 60 * 60 * 1000;
      if (requestMessage && Date.now() - lastAskPerms > week) {
        const ch = profile.avaChannelId || ANNOUNCE_CHANNEL;
        await reply(ch, requestMessage);
        profile.access = { ...profile.access, requestedAt: Date.now() };
        saveGuildProfile(guildId, profile);
        pushStatusEvent("perms still short · reminded admins");
      }
    } catch (err) {
      console.warn("guild access refresh:", err.message);
    }
  }

  const wm = loadWatermark();
  const channels = await channelTargets();
  const bullets = [];
  const latestMap = {};

  for (const channelId of channels) {
    let messages;
    try {
      messages = await fetchJson(`/channels/${channelId}/messages?limit=${FETCH_LIMIT}`);
    } catch {
      continue;
    }
    if (!Array.isArray(messages) || !messages.length) continue;
    latestMap[channelId] = messages[0].id;
    const floorId = wm.channels?.[channelId];
    const floorTs = wm.shutdownAt || 0;

    for (const m of messages) {
      markSeen(m.id);
      if (isAvaOwnMessage(m, botAppId)) continue;
      if (m.author?.bot) continue;
      const ts = snowflakeTime(m.id);
      const isNew = floorId
        ? BigInt(m.id) > BigInt(floorId)
        : floorTs
          ? ts > floorTs
          : false;
      if (!isNew) continue;
      const text = String(m.content || "").trim();
      if (!text) continue;
      const hit = looksLikeAvaTrigger(m, botAppId) || /\bava\b/i.test(text);
      if (hit) {
        bullets.push(`• **${m.author.username}**: ${text.slice(0, 160)}`);
      }
    }
    warmMemory(channelId, messages);
    harvestReactionsFromMessages(channelId, messages, botAppId);
  }

  saveSeen(seen);
  saveWatermark({ channels: latestMap, shutdownAt: Date.now() });

  const alreadyIntroduced = Boolean(loadGuildProfile(guildId)?.introducedAt);
  const isFreshIntro =
    alreadyIntroduced &&
    Date.now() - (loadGuildProfile(guildId)?.introducedAt || 0) < 120_000;

  if (!isFreshIntro && bullets.length > 0) {
    const summary = [
      `sorry I was asleep — ${discordStamp()}`,
      "**While I was out — stuff aimed at me:**",
      ...bullets.slice(0, 8),
      bullets.length > 8 ? `_…+${bullets.length - 8} more_` : null,
      "I'm active now — ping me if you still need something.",
    ]
      .filter(Boolean)
      .join("\n");
    try {
      await reply(ANNOUNCE_CHANNEL, summary);
    } catch (err) {
      console.warn("boot announce failed:", err.message);
    }
  } else if (!isFreshIntro) {
    pushStatusEvent("boot quiet — nothing aimed at Ava");
  }

  if (!cursorApiKey(env)) {
    await postOfflineNote(fetchJson, "Root Server key missing at boot");
  }

  await refreshEcoFlow().catch(() => {});

  live = true;
  touchActivity("boot");
  pushStatusEvent("boot handshake done — live");
  pulseHeartbeat();
  console.log("Ava boot handshake done — live");
}

async function tick() {
  if (!live || tickRunning) return;
  tickRunning = true;
  try {
    await maybeEnterBreak();

    const channels = await channelTargets();
    const latestMap = {};

    for (const channelId of channels) {
      let messages;
      try {
        messages = await fetchJson(`/channels/${channelId}/messages?limit=${FETCH_LIMIT}`);
      } catch {
        continue;
      }
      if (Array.isArray(messages) && messages[0]?.id) {
        latestMap[channelId] = messages[0].id;
      }

      warmMemory(channelId, messages);
      const harvested = harvestReactionsFromMessages(channelId, messages, botAppId);
      await askAboutUnknownEmojis(harvested.unknowns || []);

      // Live message answering via REST only when poller transport enabled
      // (gateway handles live when useGateway; "both" uses gateway primarily —
      // poller still catches anything missed via seen set)
      if (usePollerLive) {
        const batch = [...(messages || [])].reverse();
        for (const msg of batch) {
          if (!msg?.id || seen.has(msg.id)) continue;
          markSeen(msg.id);
          if (msg.author?.bot) continue;
          if (msg.author?.id === botAppId) continue;
          try {
            await pipeline.ingestMessage(msg, { messages, isDm: false });
          } catch (err) {
            console.warn("ingest:", err.message);
          }
        }
      } else {
        for (const msg of messages || []) markSeen(msg.id);
      }
    }

    if (Object.keys(latestMap).length) {
      const wm = loadWatermark();
      saveWatermark({ ...wm, channels: { ...(wm.channels || {}), ...latestMap } });
    }

    // Periodic poll watcher (~10 min)
    if (Date.now() - lastPollWatch > 10 * 60_000) {
      lastPollWatch = Date.now();
      try {
        const r = await runPollWatcher({
          fetchJson,
          channelId: AVA_CHANNELS.governance,
        });
        if (r.posts) pushStatusEvent(`poll watcher · ${r.posts} post(s)`);
      } catch (err) {
        console.warn("poll watcher:", err.message);
      }
      await refreshEcoFlow().catch(() => {});
    }

    saveSeen(seen);
  } finally {
    tickRunning = false;
    pulseHeartbeat();
  }
}

function scheduleNextTick() {
  if (pollTimer) clearTimeout(pollTimer);
  const ms = currentPollMs();
  pulseHeartbeat();
  pollTimer = setTimeout(() => {
    tick()
      .catch((err) => console.warn("tick:", err.message))
      .finally(() => scheduleNextTick());
  }, ms);
}

function shutdown() {
  console.log("Ava shutting down — watermark");
  if (pollTimer) clearTimeout(pollTimer);
  gatewayHandle?.stop?.();
  pushStatusEvent("shutdown");
  writeHeartbeat({ live: false, mode: "off" });
  markShutdown(loadWatermark().channels || {});
  saveSeen(seen);
  process.exit(0);
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

console.log(`Ava Ivy as app ${botAppId}, watching ${watch.length} channel(s)`);
console.log(`transport: ${AVA_TRANSPORT} · hot ${HOT_POLL_MS}ms · break ${BREAK_POLL_MS}ms`);
console.log(`handoff data: ${storePaths().dir}`);

await bootHandshake();

if (useGateway) {
  gatewayHandle = startGateway({
    token,
    watchIds: watch,
    onReady: () => {
      pushStatusEvent("gateway ready");
      pulseHeartbeat({ gateway: true });
    },
    onMessage: async (msg, meta) => {
      if (!live) return;
      if (seen.has(msg.id)) return;
      markSeen(msg.id);
      touchActivity("gateway");
      try {
        await pipeline.ingestMessage(msg, {
          messages: msg.referenced_message ? [msg.referenced_message] : [],
          isDm: Boolean(meta?.isDm),
        });
      } catch (err) {
        console.warn("gateway ingest:", err.message);
      }
      saveSeen(seen);
    },
  });
}

scheduleNextTick();

