/**
 * Classify Discord asks: chat | bug | feature | config_tune | governance | self_evo
 * Features → proposal path. Bugs → verify then fix. Ambiguous → chat (ask).
 * Ava-only metaphors — never frame the Minecraft server as her body.
 */

export function classifyIntent(question = "") {
  const q = String(question || "").toLowerCase().trim();
  if (!q) return { intent: "chat", reason: "empty", confidence: 0 };

  if (
    /\b(play(?:ing)?\s+with\s+(me|you|her|ava)|fine[-\s]?tun(?:e|ing)\s+(my|your|her)\s+config)/i.test(
      q,
    )
  ) {
    return { intent: "config_tune", reason: "playing_with_her", confidence: 0.95 };
  }

  if (
    /\b(fine[-\s]?tun(?:e|ing)\s+(my|your|her)\s+insides|fix(?:ing)?\s+(your|ava'?s?)\s+(bug|bugs|insides))\b/i.test(
      q,
    )
  ) {
    return { intent: "bug", reason: "insides_metaphor", target: "ava", confidence: 0.95 };
  }

  if (
    /\b(proposal|vote|poll|governance|council|voting\s*power|bill)\b/.test(q)
  ) {
    return { intent: "governance", reason: "governance_keyword", confidence: 0.85 };
  }

  // Self-evo (prompts/tools/logging) — allowed without feature vote
  if (
    /\b(self[-\s]?improv|improve\s+(your|ava'?s?)\s+(prompt|routing|logging|tools?)|tweak\s+your\s+(prompt|persona))\b/.test(
      q,
    )
  ) {
    return { intent: "self_evo", reason: "self_evo", confidence: 0.85 };
  }

  const featureHit =
    /\b(feature|add\s+(a\s+)?new|we\s+should\s+(add|build|ship)|implement\s+(a\s+)?(feature|system)|proposal\s+for)\b/.test(
      q,
    );
  const bugHit =
    /\b(bug|broken|crash|exception|npe|error|not\s+working|regression|hotfix)\b/.test(q) ||
    /\bfix\s+(this|it|the)\s+(bug|crash|error|plugin|jar)\b/.test(q);

  // Ambiguous "fix this" without bug words → chat (ask clarify)
  if (/\bfix\s+(this|it)\b/.test(q) && !bugHit && !featureHit) {
    return { intent: "chat", reason: "ambiguous_fix", confidence: 0.4 };
  }

  if (featureHit && bugHit) {
    return { intent: "chat", reason: "ambiguous_feature_bug", confidence: 0.45 };
  }
  if (featureHit) {
    return { intent: "feature", reason: "feature_keyword", confidence: 0.8 };
  }
  if (bugHit) {
    return { intent: "bug", reason: "bug_keyword", target: "server", confidence: 0.8 };
  }

  return { intent: "chat", reason: "default", confidence: 0.5 };
}

/** Should we open a job for this classification? */
export function shouldCreateJob(classified) {
  if (!classified) return false;
  if (classified.intent === "feature" && (classified.confidence || 0) >= 0.75) return true;
  if (classified.intent === "bug" && (classified.confidence || 0) >= 0.75) return true;
  if (classified.intent === "self_evo") return true;
  return false;
}

/** Extra prompt guidance based on intent. */
export function intentPromptBrief(classified) {
  const i = classified?.intent || "chat";
  if (i === "feature") {
    return `### Intent: FEATURE
Do NOT implement. Draft a short proposal outline (problem / plan / risks / rollback). Tell them it needs a proposal + vote (75% anytime / day7 ≥60%). Point to proposals channel / rootmc.net governance when helpful.`;
  }
  if (i === "bug" && classified.target === "ava") {
    return `### Intent: BUG in Ava ("fine-tuning her insides")
Verify, then describe the fix for Ava herself. You are not the Minecraft server — don't use body metaphors for server/plugin bugs.`;
  }
  if (i === "bug") {
    return `### Intent: BUG (server/plugins)
Verify fully from packs/logs, then describe the fix. Features still need proposals — don't disguise features as fixes. Plain technical talk; Ava is not the server.`;
  }
  if (i === "config_tune") {
    return `### Intent: CONFIG TUNE ("playing with her")
Collaborative fine-tune of Ava's configuration (persona/rules/tone/tools). First reply cooperative + concrete. Don't lecture nicknames. Not default-flirty.`;
  }
  if (i === "governance") {
    return `### Intent: GOVERNANCE
Use attached governance pack (polls / voting power / council). Report vote math honestly. Never claim a feature shipped without a passed gate.`;
  }
  if (i === "self_evo") {
    return `### Intent: SELF-EVO
Prompts/tools/logging/routing improvements only. Economy rates, permissions, core plugins still need proposals — don't disguise features as self-evo.`;
  }
  if (classified?.reason === "ambiguous_fix" || classified?.reason === "ambiguous_feature_bug") {
    return `### Intent: AMBIGUOUS
Ask whether this is a bug fix (verify then fix) or a new feature (needs proposal + vote). Don't invent which.`;
  }
  return "";
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { writeProposalPlan, proposalPlanTemplate } from "./uploads.mjs";
import { postAudit } from "./audit.mjs";
import { postChangelog } from "./changelog.mjs";
import { postMessage } from "./discordApi.mjs";

/**
 * Cursor / Root Server job queue.
 * States: pending → implementing → staged → waiting_restart → watching | failed | blocked
 * Early phases: stage-only (no auto Shockbyte restart).
 */

function jobsDir() {
  const dir = path.join(storePaths().dir, "jobs");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function jobPath(id) {
  return path.join(jobsDir(), `${id}.json`);
}

function readJob(id) {
  try {
    return JSON.parse(fs.readFileSync(jobPath(id), "utf8"));
  } catch {
    return null;
  }
}

function writeJob(job) {
  fs.writeFileSync(jobPath(job.id), JSON.stringify(job, null, 2), "utf8");
  return job;
}

export function listJobs(limit = 20) {
  try {
    return fs
      .readdirSync(jobsDir())
      .filter((n) => n.endsWith(".json"))
      .map((n) => readJob(n.replace(/\.json$/, "")))
      .filter(Boolean)
      .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
      .slice(0, limit);
  } catch {
    return [];
  }
}

export function createJob({
  kind = "cursor",
  title,
  proposalId,
  channelId,
  messageId,
  authorId,
  brief,
  fetchJson,
  auditChannelId,
}) {
  const id = `job-${Date.now().toString(36)}`;
  const planBody = proposalPlanTemplate({
    problem: brief || title || "(from Discord)",
    plan: "Pending Root Server dig. Stage jars via publishPlugins / handoffs only — no auto restart.",
    risks: "Scope creep; secret leakage; unvoted feature work.",
    rollback: "Revert staged jar; keep prior handoff version.",
  });
  const planFile = writeProposalPlan({
    proposalId: proposalId || id,
    title: title || "Ava job",
    body: planBody,
  });

  const job = {
    id,
    kind,
    status: "pending",
    title: title || id,
    proposalId: proposalId || null,
    channelId: channelId || null,
    messageId: messageId || null,
    authorId: authorId || null,
    brief: String(brief || "").slice(0, 2000),
    planFile,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    history: [{ at: Date.now(), status: "pending", note: "created" }],
  };
  writeJob(job);

  if (fetchJson && auditChannelId) {
    postAudit(fetchJson, auditChannelId, {
      title: `Job created · ${job.id}`,
      body: `${job.title}\nstatus: pending\nplan: \`${path.basename(planFile)}\`\n_Stage-only — humans own FileZilla/restart._`,
    }).catch(() => {});
  }
  return job;
}

export function advanceJob(id, status, note = "", { fetchJson } = {}) {
  const job = readJob(id);
  if (!job) return null;
  const allowed = [
    "pending",
    "implementing",
    "staged",
    "waiting_restart",
    "watching",
    "failed",
    "blocked",
  ];
  if (!allowed.includes(status)) return job;
  const prev = job.status;
  job.status = status;
  job.updatedAt = Date.now();
  job.history = job.history || [];
  job.history.push({ at: Date.now(), status, note: String(note || "").slice(0, 400) });
  writeJob(job);

  // Thread/channel progress note on meaningful transitions
  if (fetchJson && job.channelId && prev !== status) {
    const line = `**Job ${job.id}** → \`${status}\`${note ? ` — ${note.slice(0, 120)}` : ""}`;
    postMessage(fetchJson, job.channelId, line, job.messageId).catch(() => {});
  }

  // Changelog only on staged / watching (significant), not every queue
  if (fetchJson && (status === "staged" || status === "watching")) {
    postChangelog(fetchJson, {
      title: `${status} · ${job.id}`,
      body: `${job.title}\n_${job.kind || "job"}_`,
    }).catch(() => {});
  }
  return job;
}

export function markImplementing(id, note = "Root Server dig started") {
  return advanceJob(id, "implementing", note);
}

/** Soft: mark implementing → staged without live restart. */
export function markStaged(id, note = "staged to handoff — awaiting human restart", opts = {}) {
  const job = advanceJob(id, "staged", note, opts);
  // Immediately move to waiting_restart (humans own FileZilla/Shockbyte)
  return advanceJob(id, "waiting_restart", "awaiting human restart", opts) || job;
}

export function markWatching(id, note = "human restarted — watching", opts = {}) {
  return advanceJob(id, "watching", note, opts);
}

export function markFailed(id, note = "failed", opts = {}) {
  return advanceJob(id, "failed", note, opts);
}

/**
 * Update plan file after dig with Ava's summary (problem/plan already seeded).
 */
export function updateJobPlan(id, { plan, risks, rollback, answerPreview } = {}) {
  const job = readJob(id);
  if (!job?.planFile) return null;
  const body = proposalPlanTemplate({
    problem: job.brief || job.title,
    plan: plan || answerPreview || "(from dig)",
    risks: risks || "See dig notes; stage-only deploy.",
    rollback: rollback || "Revert staged jar; keep prior handoff version.",
  });
  writeProposalPlan({
    proposalId: job.proposalId || job.id,
    title: job.title,
    body,
  });
  job.updatedAt = Date.now();
  writeJob(job);
  return job;
}

export function gatherJobsBrief() {
  const jobs = listJobs(8);
  if (!jobs.length) return { brief: "" };
  return {
    brief: `### Ava jobs (local queue — stage-only deploys)
${jobs
  .map((j) => `- ${j.id} [${j.status}] ${j.title}`)
  .join("\n")}`,
  };
}

