/**
 * Shared live-message pipeline for poller + gateway.
 */
import {
  extractQuestion,
  looksLikeAvaTrigger,
  recommend,
  isHushCommand,
  isWakeCommand,
} from "./recommend.mjs";
import {
  buildPlayerContext,
  rememberPlayerLine,
  memoryContext,
} from "./playerContext.mjs";
import { pickInstantOpen, pickHold, holdBeatDelays } from "./instantLines.mjs";
import { brainQueueDepth, beginAsk, endAsk } from "./cursorBrain.mjs";
import {
  isHushed,
  setHushed,
  lastReplyFor,
  setLastReply,
  nearDuplicate,
  pushStatusEvent,
  markShutdown,
  loadWatermark,
} from "./store.mjs";
import { isAvaOwnMessage } from "./guildScout.mjs";
import { silentlyProfileMessage } from "./playerProfiles.mjs";
import { tryLearnFromMessage } from "./reactionStore.mjs";
import { saveMessageAttachments } from "./uploads.mjs";
import { maybeSendOnboardingDm } from "./onboarding.mjs";
import { persistTurn } from "./conversationStore.mjs";
import { classifyIntent, shouldCreateJob } from "./classify.mjs";
import {
  createJob,
  markImplementing,
  markStaged,
  markFailed,
  updateJobPlan,
} from "./jobQueue.mjs";
import {
  isEmergencyStopCommand,
  isEmergencyClearCommand,
  canEmergencyStop,
  setEmergencyStop,
  isEmergencyStopped,
} from "./emergencyStop.mjs";
import {
  isBlockedMassAction,
  isBlockedEconomyOrCore,
  tryModerationCommand,
} from "./moderation.mjs";
import { AVA_CHANNELS, ROOTMC_GUILD_ID } from "./config.mjs";
import { postOfflineNote } from "./offlineNotes.mjs";
import { resolveMembership } from "./membership.mjs";
import { postAudit } from "./audit.mjs";

const busyChannels = new Set();
const CHANNEL_COOLDOWN_MS = Number(process.env.AVA_CHANNEL_COOLDOWN_MS || 20_000);
const channelCooldownUntil = new Map();
let lastOfflineNoteAt = 0;

export function pipelineBusyCount() {
  return busyChannels.size;
}

function onCooldown(channelId) {
  const until = channelCooldownUntil.get(String(channelId)) || 0;
  return Date.now() < until;
}

function armCooldown(channelId) {
  channelCooldownUntil.set(String(channelId), Date.now() + CHANNEL_COOLDOWN_MS);
}

/** One hold beat max (plan: ack + answer, not spam). */
function startHoldTransfers(replyFn, channelId, refId, queueDepth) {
  const delays = holdBeatDelays(queueDepth);
  const state = { timers: [], done: false };
  state.timers.push(
    setTimeout(async () => {
      if (state.done) return;
      const line = pickHold(1);
      if (!line) return;
      try {
        await replyFn(channelId, line, refId);
      } catch {
        /* ignore */
      }
    }, delays.beat1),
  );
  return {
    stop() {
      state.done = true;
      for (const t of state.timers) clearTimeout(t);
    },
  };
}

export function createPipeline(deps) {
  const {
    fetchJson,
    reply,
    botAppId,
    env,
    touchActivity = () => {},
    pulseHeartbeat = () => {},
    getOnBreak = () => false,
    setOnBreak = () => {},
  } = deps;

  async function handleTrigger(channelId, msg, messages = []) {
    if (busyChannels.has(channelId)) {
      try {
        await reply(
          channelId,
          "still on your last ask in here — gimme a sec.",
          msg.id,
        );
      } catch {
        /* ignore */
      }
      return;
    }
    if (onCooldown(channelId)) {
      pushStatusEvent(`cooldown · ${channelId}`);
      try {
        await reply(channelId, "cooldown — ask again in a few seconds.", msg.id);
      } catch {
        /* ignore */
      }
      return;
    }
    busyChannels.add(channelId);
    const holds = { stop() {} };
    try {
      const wasBreak = getOnBreak();
      touchActivity("ping");

      const uploads = await saveMessageAttachments(msg);
      if (uploads.length) pushStatusEvent(`uploads · ${uploads.length}`);

      if (msg.author?.id) {
        maybeSendOnboardingDm(fetchJson, {
          authorId: msg.author.id,
          username: msg.author.username,
        }).catch(() => {});
      }

      let question =
        extractQuestion(msg.content) || "you pinged me — what's up?";
      if (uploads.length) {
        question += `\n\n[attachments saved to handoff uploads/: ${uploads.join(", ")}]`;
      }

      // Near-dupe of last answer intent — skip dig early
      if (nearDuplicate(question, lastReplyFor(channelId))) {
        await reply(
          channelId,
          "same ask as last time — skipping the redo. ping with something new if you need more.",
          msg.id,
        );
        return;
      }

      const classified = classifyIntent(question);
      const member = await resolveMembership(fetchJson, {
        guildId: ROOTMC_GUILD_ID,
        userId: msg.author?.id,
        env,
      });

      const depthAtAck = brainQueueDepth();
      const openLine = pickInstantOpen({
        fromBreak: wasBreak,
        queueDepth: depthAtAck,
      });
      const ackP = reply(channelId, openLine, msg.id).catch((err) => {
        console.warn("ack failed:", err.message);
      });
      beginAsk();

      const liveCtx = buildPlayerContext({
        trigger: msg,
        messages,
        avaBotId: botAppId,
      });
      const mem = memoryContext(channelId, msg.author?.id);
      const context = [mem, liveCtx].filter(Boolean).join("\n\n").slice(0, 5500);

      Object.assign(
        holds,
        startHoldTransfers(reply, channelId, msg.id, depthAtAck),
      );

      console.log(
        `ava trigger in ${channelId} from ${msg.author?.username} intent=${classified.intent} (queue=${depthAtAck})`,
      );
      pushStatusEvent(
        `ask · ${msg.author?.username || "?"}: ${question.slice(0, 100)}`,
      );
      pulseHeartbeat({ digging: true, lastAsk: question.slice(0, 120) });

      if (msg.author?.id && !isAvaOwnMessage(msg, botAppId)) {
        silentlyProfileMessage(msg, channelId, "live");
      }

      if (isBlockedMassAction(question) || isBlockedEconomyOrCore(question)) {
        holds.stop();
        await ackP;
        const deny = isBlockedEconomyOrCore(question)
          ? "Economy rates / permissions / core-plugin changes need a proposal + vote. I won't disguise that as a fix."
          : "Nope — mass bans / claim wipes / vote-weight changes need a human + proposal. Not doing that solo.";
        await reply(channelId, deny, msg.id);
        persistTurn({
          channelId,
          messageId: msg.id,
          authorId: msg.author?.id,
          authorName: msg.author?.username,
          question,
          answer: deny,
          intent: "blocked",
        });
        return;
      }

      let jobId = null;
      if (shouldCreateJob(classified) && !isEmergencyStopped()) {
        // Features still need vote — job is proposal/plan tracking, not implement
        const job = createJob({
          kind: classified.intent,
          title: question.slice(0, 80),
          channelId,
          messageId: msg.id,
          authorId: msg.author?.id,
          brief: question,
          fetchJson,
          auditChannelId: AVA_CHANNELS.audit,
        });
        jobId = job.id;
        markImplementing(job.id, "Root Server dig");
      }

      let answer;
      try {
        answer = await recommend({
          question,
          context,
          env,
          authorId: msg.author?.id || "",
          authorName: msg.author?.username || msg.author?.global_name || "",
          intent: classified,
          member: member.member,
        });
      } catch (err) {
        console.warn("recommend failed:", err.message);
        if (Date.now() - lastOfflineNoteAt > 15 * 60_000) {
          lastOfflineNoteAt = Date.now();
          postOfflineNote(fetchJson, `Root Server dig failed: ${err.message}`).catch(
            () => {},
          );
        }
        answer =
          "I'm a bit offline on the deep-dig side — left a note. Ask again when the Root Server's up.";
        if (jobId) markFailed(jobId, err.message, { fetchJson });
      } finally {
        endAsk();
      }
      holds.stop();
      await ackP;
      touchActivity("answered");
      pushStatusEvent(`answered · ${msg.author?.username || "?"}`);
      pulseHeartbeat({ digging: false });

      if (nearDuplicate(answer, lastReplyFor(channelId))) {
        await reply(
          channelId,
          "same answer as last — skipping the redo.",
          msg.id,
        );
        return;
      }

      if (jobId) {
        updateJobPlan(jobId, { answerPreview: String(answer).slice(0, 800) });
        // Stage-only: plan filed; humans restart. Features stay proposal-gated in copy.
        if (classified.intent === "bug" || classified.intent === "self_evo") {
          markStaged(jobId, "dig complete — stage jars via handoff; no auto restart", {
            fetchJson,
          });
        } else if (classified.intent === "feature") {
          markStaged(jobId, "plan filed — needs proposal + vote before implement", {
            fetchJson,
          });
        }
      }

      await reply(channelId, answer, msg.id);
      setLastReply(channelId, answer);
      rememberPlayerLine(channelId, botAppId, "Ava", answer);
      armCooldown(channelId);
      persistTurn({
        channelId,
        messageId: msg.id,
        authorId: msg.author?.id,
        authorName: msg.author?.username,
        question,
        answer,
        intent: classified.intent,
        jobId,
      });
    } finally {
      holds.stop();
      busyChannels.delete(channelId);
    }
  }

  async function ingestMessage(msg, { messages = [], isDm = false } = {}) {
    if (!msg?.id || !msg.channel_id) return;
    if (msg.author?.bot) return;
    if (String(msg.author?.id) === String(botAppId)) return;

    const channelId = msg.channel_id;
    const taught = tryLearnFromMessage({ ...msg, channel_id: channelId });
    if (taught) {
      touchActivity("emoji-learn");
      try {
        await reply(channelId, taught.thank, msg.id);
      } catch {
        /* ignore */
      }
      return;
    }

    // Moderation operator commands (warn/mute/ban propose)
    const mod = await tryModerationCommand({
      fetchJson,
      msg,
      channelId,
      reply,
    });
    if (mod.handled) {
      touchActivity("mod");
      return;
    }

    if (isHushCommand(msg.content)) {
      setHushed(true, "user hush");
      setOnBreak(true);
      touchActivity("hush");
      pushStatusEvent("hushed");
      try {
        markShutdown(loadWatermark().channels || {});
      } catch {
        /* ignore */
      }
      try {
        await reply(
          channelId,
          `Got it — going quiet.\nPing me when you want me back.`,
          msg.id,
        );
      } catch {
        /* ignore */
      }
      return;
    }

    if (isWakeCommand(msg.content)) {
      setHushed(false, "user wake");
      setOnBreak(false);
      touchActivity("wake");
      pushStatusEvent("woke");
      try {
        await reply(
          channelId,
          "I'm up. Give me a sec when you ask something — I think first.",
          msg.id,
        );
      } catch {
        /* ignore */
      }
      return;
    }

    if (
      isEmergencyStopCommand(msg.content) &&
      canEmergencyStop(msg.author?.id, msg.author?.username)
    ) {
      setEmergencyStop(true, {
        by: msg.author?.username,
        reason: "operator",
      });
      pushStatusEvent("emergency stop ON");
      postAudit(fetchJson, AVA_CHANNELS.audit, {
        title: "Emergency stop ON",
        body: `by ${msg.author?.username || "?"}`,
      }).catch(() => {});
      await reply(
        channelId,
        "Emergency stop on — RCON/file-write jobs paused. I can still talk.",
        msg.id,
      );
      return;
    }
    if (
      isEmergencyClearCommand(msg.content) &&
      canEmergencyStop(msg.author?.id, msg.author?.username)
    ) {
      setEmergencyStop(false, { by: msg.author?.username, reason: "cleared" });
      pushStatusEvent("emergency stop OFF");
      postAudit(fetchJson, AVA_CHANNELS.audit, {
        title: "Emergency stop OFF",
        body: `by ${msg.author?.username || "?"}`,
      }).catch(() => {});
      await reply(channelId, "Emergency stop cleared.", msg.id);
      return;
    }

    if (isHushed()) return;

    const addressed =
      isDm ||
      looksLikeAvaTrigger(msg, botAppId) ||
      isReplyToAva(msg, messages, botAppId);
    if (!addressed) return;

    await handleTrigger(channelId, msg, messages);
  }

  return { ingestMessage, handleTrigger, busyChannels };
}

function isReplyToAva(msg, messages, botAppId) {
  const refId = msg?.message_reference?.message_id;
  if (!refId) return false;
  if (msg?.referenced_message?.author?.id) {
    return String(msg.referenced_message.author.id) === String(botAppId);
  }
  const ref = (messages || []).find((m) => m.id === refId);
  return Boolean(ref && String(ref.author?.id) === String(botAppId));
}

/**
 * Resolve RootMC membership for Cursor soft-gate (unlimited when member).
 * Sources: AVA_MEMBER_ROLE_IDS (csv) on guild member, or profile.member flag.
 */
import { savePlayerProfileMut, loadPlayerProfile } from "./playerProfiles.mjs";

function memberRoleIds(env = {}) {
  const raw =
    process.env.AVA_MEMBER_ROLE_IDS ||
    env.AVA_MEMBER_ROLE_IDS ||
    process.env.DISCORD_ROOTMC_MEMBER_ROLE_ID ||
    "";
  return String(raw)
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

/**
 * @returns {Promise<{ member: boolean, source: string }>}
 */
export async function resolveMembership(fetchJson, { guildId, userId, env } = {}) {
  if (!userId) return { member: false, source: "none" };
  const prev = loadPlayerProfile(userId);
  if (prev?.member) return { member: true, source: "profile" };

  const roles = memberRoleIds(env || {});
  if (!roles.length || !fetchJson || !guildId) {
    return { member: false, source: "unconfigured" };
  }

  try {
    const m = await fetchJson(`/guilds/${guildId}/members/${userId}`);
    const have = new Set((m?.roles || []).map(String));
    const hit = roles.some((r) => have.has(String(r)));
    if (hit) {
      savePlayerProfileMut(userId, (p) => {
        p.member = true;
        return p;
      });
      return { member: true, source: "discord_role" };
    }
  } catch (err) {
    console.warn("membership lookup:", err.message);
  }
  return { member: false, source: "no_role" };
}

import { personByDiscordId } from "./people.mjs";
import { savePlayerProfileMut, loadPlayerProfile } from "./playerProfiles.mjs";
import { canEmergencyStop } from "./emergencyStop.mjs";

/**
 * Moderation helpers — cool-down, dual-signal before bans.
 * Admins never banned by Ava. Mass bans / economy / claim wipes blocked.
 */

const COOLDOWN_MS = 15 * 60 * 1000;

export function isAdminProtected(discordId) {
  const p = personByDiscordId(discordId);
  if (!p) return false;
  return (p.roles || []).some((r) =>
    ["admin", "owner", "operator", "staff"].includes(r),
  );
}

export function recordModSignal(targetId, { kind = "warn", by, reason } = {}) {
  if (!targetId) return { ok: false, reason: "no_target" };
  if (isAdminProtected(targetId)) {
    return { ok: false, reason: "admin_protected" };
  }
  const p = savePlayerProfileMut(targetId, (prev) => {
    const signals = Array.isArray(prev.modSignals) ? prev.modSignals : [];
    signals.push({ kind, by, reason: String(reason || "").slice(0, 200), at: Date.now() });
    prev.modSignals = signals.slice(-20);
    prev.lastModAt = Date.now();
    return prev;
  });
  return { ok: true, profile: p };
}

export function canProposeBan(targetId) {
  if (isAdminProtected(targetId)) return { ok: false, reason: "admin_protected" };
  const p = loadPlayerProfile(targetId);
  const signals = (p?.modSignals || []).filter(
    (s) => Date.now() - (s.at || 0) < 24 * 60 * 60 * 1000,
  );
  const warnCount = signals.filter((s) => s.kind === "warn" || s.kind === "mute").length;
  if (warnCount < 2) {
    return { ok: false, reason: "need_dual_signal", warnCount };
  }
  if (p?.lastModAt && Date.now() - p.lastModAt < COOLDOWN_MS) {
    return { ok: false, reason: "cooldown", warnCount };
  }
  return { ok: true, warnCount };
}

export function isBlockedMassAction(text) {
  const q = String(text || "").toLowerCase();
  return /\b(mass\s*ban|ban\s+all|wipe\s+claims?|vote\s*weight)\b/.test(q);
}

/** Economy / core-plugin / permissions — proposal-gated (not silent self-evo). */
export function isBlockedEconomyOrCore(text) {
  const q = String(text || "").toLowerCase();
  return /\b(economy\s+rate|change\s+(the\s+)?(tax|interest|shop\s+price)|permissions?\s+node|luckperms|core\s+plugin)\b/.test(
    q,
  );
}

/**
 * Operator mod commands (Alex / staff with emergency-stop power):
 *   Ava warn @user reason…
 *   Ava mute @user reason…
 *   Ava ban-check @user
 * Ban execute only if dual-signal + not admin — still posts propose, doesn't auto-ban unless AVA_MOD_EXECUTE=1
 */
export async function tryModerationCommand({ fetchJson, msg, channelId, reply }) {
  const content = String(msg?.content || "");
  if (!/\bava\b/i.test(content)) return { handled: false };
  if (!canEmergencyStop(msg.author?.id, msg.author?.username)) {
    // Only operators/staff run mod commands through Ava
    if (!/\b(warn|mute|ban-check|timeout)\b/i.test(content)) return { handled: false };
    // Non-operators: ignore as mod command (may still be normal chat)
    if (!/^(hey\s+|hi\s+)?ava\s+(warn|mute|ban-check|timeout)\b/i.test(content.trim())) {
      return { handled: false };
    }
    await reply(channelId, "Only operators can run mod commands through me.", msg.id);
    return { handled: true };
  }

  const m = content.match(
    /\bava\s+(warn|mute|timeout|ban-check)\s+<@!?(\d+)>\s*(.*)$/i,
  );
  if (!m) return { handled: false };

  const kind = m[1].toLowerCase();
  const targetId = m[2];
  const reason = (m[3] || "").trim() || "no reason given";

  if (isAdminProtected(targetId)) {
    await reply(channelId, "Admins are protected — I never ban/mute staff.", msg.id);
    return { handled: true };
  }

  if (kind === "ban-check") {
    const gate = canProposeBan(targetId);
    await reply(
      channelId,
      gate.ok
        ? `Ban gate OK for <@${targetId}> (${gate.warnCount} signals). Dual-signal + cooldown cleared.`
        : `Ban gate blocked: ${gate.reason}${gate.warnCount != null ? ` (signals=${gate.warnCount})` : ""}.`,
      msg.id,
    );
    return { handled: true };
  }

  const signalKind = kind === "timeout" ? "mute" : kind;
  const rec = recordModSignal(targetId, {
    kind: signalKind,
    by: msg.author?.id,
    reason,
  });
  if (!rec.ok) {
    await reply(channelId, `Couldn't record signal: ${rec.reason}`, msg.id);
    return { handled: true };
  }

  // Optional Discord timeout (mute) when enabled
  if (
    (kind === "mute" || kind === "timeout") &&
    String(process.env.AVA_MOD_EXECUTE || "").trim() === "1" &&
    fetchJson
  ) {
    try {
      const until = new Date(Date.now() + 10 * 60 * 1000).toISOString();
      await fetchJson(`/guilds/${msg.guild_id}/members/${targetId}`, {
        method: "PATCH",
        body: JSON.stringify({ communication_disabled_until: until }),
      });
      await reply(
        channelId,
        `Recorded **${signalKind}** + applied 10m timeout. Reason: ${reason.slice(0, 120)}`,
        msg.id,
      );
      return { handled: true };
    } catch (err) {
      await reply(
        channelId,
        `Recorded **${signalKind}** but Discord timeout failed (${err.message}).`,
        msg.id,
      );
      return { handled: true };
    }
  }

  await reply(
    channelId,
    `Recorded **${signalKind}** on that player (silent score). Reason: ${reason.slice(0, 120)}`,
    msg.id,
  );
  return { handled: true };
}

export function gatherModerationBrief(targetId) {
  if (!targetId) return { brief: "" };
  const p = loadPlayerProfile(targetId);
  if (!p?.modSignals?.length) return { brief: "" };
  return {
    brief: `### Moderation signals (private)
target ${p.username}: ${(p.modSignals || []).slice(-5).map((s) => `${s.kind}@${s.at}`).join(", ")}
admin_protected: ${isAdminProtected(targetId)}`,
  };
}

