/**
 * Public api.rootmc.net governance client (no API key).
 */

const BASE = String(
  process.env.AVA_API_BASE || process.env.ROOTMC_API_BASE || "https://api.rootmc.net",
).replace(/\/$/, "");

const DAY_MS = 7 * 24 * 60 * 60 * 1000;

async function getJson(path) {
  const res = await fetch(`${BASE}${path}`, {
    headers: { Accept: "application/json", "User-Agent": "AvaIvyRootMC/0.5" },
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = null;
  }
  if (!res.ok) {
    return { ok: false, status: res.status, detail: data?.detail || text.slice(0, 200) };
  }
  return data || { ok: false };
}

export async function listOpenPolls() {
  return getJson("/api/governance/polls");
}

export async function getVote(id) {
  return getJson(`/api/governance/votes/${encodeURIComponent(id)}`);
}

export async function getCouncil() {
  return getJson("/api/governance/council");
}

export async function getVotingPower({ discordUserId, uuid } = {}) {
  const q = new URLSearchParams();
  if (discordUserId) q.set("discord_user_id", String(discordUserId));
  if (uuid) q.set("uuid", String(uuid));
  return getJson(`/api/governance/voting-power?${q}`);
}

/**
 * Ava vote gates:
 * - 75% anytime → implement_now
 * - day 7 (closes_at OR opened_at+7d) ≥60% → pass
 * - day 7 <60% → close
 */
export function evaluatePollGate(poll) {
  if (!poll) return { gate: "unknown", note: "no poll" };
  const forPct = Number(poll.weighted_for_pct ?? 0);
  const againstPct = Number(poll.weighted_against_pct ?? 0);
  const closesAt = poll.closes_at ? Date.parse(poll.closes_at) : NaN;
  const openedAt = poll.opened_at
    ? Date.parse(poll.opened_at)
    : poll.created_at
      ? Date.parse(poll.created_at)
      : NaN;
  const day7At = Number.isFinite(closesAt)
    ? closesAt
    : Number.isFinite(openedAt)
      ? openedAt + DAY_MS
      : NaN;
  const open = poll.open !== false && String(poll.status || "") === "open";
  const now = Date.now();

  if (forPct >= 75) {
    return {
      gate: "implement_now",
      note: `≥75% for (${forPct}%) — implement immediately per Ava rules`,
      forPct,
      againstPct,
      open,
    };
  }

  const closedOrDue = !open || (Number.isFinite(day7At) && now >= day7At);
  if (closedOrDue) {
    if (forPct >= 60) {
      return {
        gate: "pass",
        note: `day-7/close ≥60% for (${forPct}%) — pass`,
        forPct,
        againstPct,
        open,
      };
    }
    return {
      gate: "close",
      note: `day-7/close <60% for (${forPct}%) — close (reopenable)`,
      forPct,
      againstPct,
      open,
    };
  }

  return {
    gate: "waiting",
    note: `open — for ${forPct}% / against ${againstPct}% (need 75% anytime or ≥60% at day-7/close)`,
    forPct,
    againstPct,
    open,
  };
}

function extractVoteId(question = "") {
  const m = String(question || "").match(
    /\b(?:vote|poll|proposal)[:\s#]*([A-Za-z0-9_-]{4,})\b/i,
  );
  return m?.[1] || null;
}

/** Pack for Cursor prompts — never invent poll numbers. */
export async function gatherGovernanceBrief({ discordUserId, question } = {}) {
  try {
    const voteId = extractVoteId(question || "");
    const [pollsRes, powerRes, councilRes, voteRes] = await Promise.all([
      listOpenPolls(),
      discordUserId ? getVotingPower({ discordUserId }) : Promise.resolve(null),
      getCouncil(),
      voteId ? getVote(voteId) : Promise.resolve(null),
    ]);
    const lines = ["### Governance (live api.rootmc.net — do not invent numbers)"];
    if (pollsRes?.ok && Array.isArray(pollsRes.polls)) {
      if (!pollsRes.polls.length) lines.push("Open polls: none");
      for (const p of pollsRes.polls.slice(0, 6)) {
        const g = evaluatePollGate(p);
        lines.push(
          `- **${p.id}** ${p.title || ""} · for ${p.weighted_for_pct ?? "?"}% / against ${p.weighted_against_pct ?? "?"}% · gate: ${g.gate}`,
        );
      }
    } else {
      lines.push(`Polls fetch: ${pollsRes?.detail || "unavailable"}`);
    }
    if (voteRes?.ok && voteRes.poll) {
      const g = evaluatePollGate(voteRes.poll);
      lines.push(
        `Asked vote **${voteRes.poll.id}**: for ${voteRes.poll.weighted_for_pct ?? "?"}% · gate ${g.gate} (${g.note})`,
      );
    }
    if (councilRes?.ok) {
      lines.push(
        `Council: eligible≈${councilRes.eligible_count ?? "?"} · synced ${councilRes.synced_at || "?"}`,
      );
      for (const c of (councilRes.council || []).slice(0, 5)) {
        lines.push(
          `  - ${c.minecraft_username || "?"} share ${c.share_percent ?? "?"}%`,
        );
      }
    }
    if (powerRes?.ok) {
      lines.push(
        `Asker voting power: eligible=${powerRes.eligible} share=${powerRes.share_percent ?? "?"}% · ${powerRes.summary || ""}`,
      );
    } else if (discordUserId && powerRes && powerRes.ok === false) {
      lines.push(`Asker voting power: ${powerRes.detail || "not linked / unavailable"}`);
    }
    lines.push(
      "Rules: features need proposal + vote; 75% anytime = implement; day7 ≥60% = pass; bugs verify then fix.",
    );
    return {
      brief: lines.join("\n"),
      polls: pollsRes,
      power: powerRes,
      council: councilRes,
      vote: voteRes,
    };
  } catch (err) {
    return {
      brief: `### Governance\n(unavailable: ${err.message})`,
      polls: null,
      power: null,
    };
  }
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { listOpenPolls, evaluatePollGate, getVote } from "./governanceClient.mjs";
import { postMessage } from "./discordApi.mjs";
import { createJob, markStaged } from "./jobQueue.mjs";
import { AVA_CHANNELS } from "./config.mjs";
import { postAudit } from "./audit.mjs";

/**
 * Poll watcher — tracks open governance polls vs Ava vote gates.
 * Posts progress notes when gate state changes; enqueues stage-only jobs on implement_now/pass.
 */

function statePath() {
  return path.join(storePaths().dir, "poll-watcher.json");
}

function loadState() {
  try {
    if (!fs.existsSync(statePath())) return { polls: {}, updatedAt: 0 };
    return JSON.parse(fs.readFileSync(statePath(), "utf8"));
  } catch {
    return { polls: {}, updatedAt: 0 };
  }
}

function saveState(s) {
  fs.mkdirSync(path.dirname(statePath()), { recursive: true });
  fs.writeFileSync(statePath(), JSON.stringify(s, null, 2), "utf8");
}

export async function runPollWatcher({ fetchJson, channelId, force = false }) {
  if (!channelId || !fetchJson) return { checked: 0, posts: 0 };
  const res = await listOpenPolls();
  if (!res?.ok || !Array.isArray(res.polls)) return { checked: 0, posts: 0, error: res?.detail };

  const state = loadState();
  let posts = 0;
  for (const p of res.polls) {
    const gate = evaluatePollGate(p);
    const prev = state.polls[p.id]?.gate;
    state.polls[p.id] = {
      gate: gate.gate,
      forPct: gate.forPct,
      againstPct: gate.againstPct,
      title: p.title,
      at: Date.now(),
    };
    if (!force && prev === gate.gate) continue;
    if (gate.gate === "waiting" && prev === "waiting") continue;

    const line = [
      `**Poll update · ${p.id}**`,
      p.title || "",
      gate.note,
      p.url ? `<${p.url}>` : null,
      gate.gate === "implement_now" || gate.gate === "pass"
        ? `_Gate passed — staging plan only; humans still own FileZilla/restart._`
        : null,
    ]
      .filter(Boolean)
      .join("\n");

    try {
      await postMessage(fetchJson, channelId, line, null);
      posts += 1;
    } catch (err) {
      console.warn("poll watcher post:", err.message);
    }

    if (
      (gate.gate === "implement_now" || gate.gate === "pass") &&
      prev !== gate.gate
    ) {
      const job = createJob({
        kind: "feature",
        title: `Gate ${gate.gate}: ${p.title || p.id}`,
        proposalId: p.id,
        channelId,
        brief: `Governance gate ${gate.gate} for poll ${p.id} (${gate.note})`,
        fetchJson,
        auditChannelId: AVA_CHANNELS.audit,
      });
      markStaged(job.id, `governance ${gate.gate} — stage-only`, { fetchJson });
      postAudit(fetchJson, AVA_CHANNELS.audit, {
        title: `Gate ${gate.gate} · ${p.id}`,
        body: `${p.title || ""}\n${gate.note}\njob ${job.id}`,
      }).catch(() => {});
    }
  }
  state.updatedAt = Date.now();
  saveState(state);
  return { checked: res.polls.length, posts };
}

export async function summarizePoll(id) {
  const res = await getVote(id);
  if (!res?.ok || !res.poll) return null;
  const gate = evaluatePollGate(res.poll);
  return { poll: res.poll, gate };
}

/**
 * Guarded RCON — real TCP when AVA_RCON_HOST + AVA_RCON_PASSWORD set.
 * Blocked by emergency stop; dangerous commands denied.
 */
import net from "node:net";
import { isEmergencyStopped } from "./emergencyStop.mjs";

export function rconConfigured() {
  return Boolean(
    String(process.env.AVA_RCON_HOST || "").trim() &&
      String(process.env.AVA_RCON_PASSWORD || "").trim(),
  );
}

function pack(id, type, body) {
  const payload = Buffer.from(String(body) + "\0\0", "utf8");
  const len = 4 + 4 + payload.length;
  const buf = Buffer.alloc(4 + len);
  buf.writeInt32LE(len, 0);
  buf.writeInt32LE(id, 4);
  buf.writeInt32LE(type, 8);
  payload.copy(buf, 12);
  return buf;
}

function readPacket(socket) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let needed = null;
    const onData = (d) => {
      chunks.push(d);
      const buf = Buffer.concat(chunks);
      if (needed == null && buf.length >= 4) needed = buf.readInt32LE(0) + 4;
      if (needed != null && buf.length >= needed) {
        socket.off("data", onData);
        const len = buf.readInt32LE(0);
        const id = buf.readInt32LE(4);
        const type = buf.readInt32LE(8);
        const body = buf.slice(12, 4 + len - 2).toString("utf8");
        resolve({ id, type, body });
      }
    };
    socket.on("data", onData);
    socket.on("error", reject);
    setTimeout(() => reject(new Error("rcon_timeout")), 8000);
  });
}

async function rconExec(command) {
  const host = String(process.env.AVA_RCON_HOST || "").trim();
  const port = Number(process.env.AVA_RCON_PORT || 25575);
  const password = String(process.env.AVA_RCON_PASSWORD || "");

  return new Promise((resolve, reject) => {
    const socket = net.connect({ host, port }, async () => {
      try {
        socket.write(pack(1, 3, password)); // AUTH
        const auth = await readPacket(socket);
        if (auth.id === -1) {
          socket.destroy();
          return reject(new Error("rcon_auth_failed"));
        }
        socket.write(pack(2, 2, command)); // COMMAND
        const res = await readPacket(socket);
        socket.end();
        resolve(res.body || "");
      } catch (err) {
        socket.destroy();
        reject(err);
      }
    });
    socket.on("error", reject);
  });
}

/**
 * @returns {Promise<{ ok: boolean, reason?: string, output?: string }>}
 */
export async function guardedRcon(command, { allow = false } = {}) {
  if (isEmergencyStopped()) {
    return { ok: false, reason: "emergency_stop" };
  }
  if (!allow) {
    return { ok: false, reason: "not_authorized" };
  }
  if (!rconConfigured()) {
    return { ok: false, reason: "rcon_not_configured" };
  }

  const cmd = String(command || "").trim();
  if (!cmd) return { ok: false, reason: "empty" };
  if (/\b(op|deop|ban-ip|stop|whitelist\s+off|pardon-ip)\b/i.test(cmd)) {
    return { ok: false, reason: "blocked_command" };
  }

  try {
    const output = await rconExec(cmd);
    return { ok: true, output: String(output).slice(0, 1500) };
  } catch (err) {
    return { ok: false, reason: err.message || "rcon_error" };
  }
}

export function gatherRconBrief() {
  return {
    brief: `### RCON
configured: ${rconConfigured() ? "yes" : "no"}
emergency_stop: ${isEmergencyStopped() ? "ACTIVE — writes/RCON paused" : "clear"}
Dangerous cmds blocked. Execute only with operator allow + clear stop.`,
  };
}

import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";

/**
 * EcoFlow power telemetry — store snapshots; mood hint for persona.
 */

function ecoPath() {
  return path.join(storePaths().dir, "ecoflow.json");
}

export function loadEcoSnapshot() {
  try {
    if (!fs.existsSync(ecoPath())) return null;
    return JSON.parse(fs.readFileSync(ecoPath(), "utf8"));
  } catch {
    return null;
  }
}

export function saveEcoSnapshot(partial) {
  const prev = loadEcoSnapshot() || {};
  const next = { ...prev, ...partial, updatedAt: Date.now() };
  fs.mkdirSync(path.dirname(ecoPath()), { recursive: true });
  fs.writeFileSync(ecoPath(), JSON.stringify(next, null, 2), "utf8");
  return next;
}

export function ecoConfigured() {
  return Boolean(
    String(process.env.AVA_ECOFLOW_ACCESS_KEY || process.env.ECOFLOW_ACCESS_KEY || "").trim() &&
      String(process.env.AVA_ECOFLOW_SECRET_KEY || process.env.ECOFLOW_SECRET_KEY || "").trim(),
  );
}

/**
 * Refresh EcoFlow Open API when configured.
 * Docs vary by product — we try a common device-list + quota path; fall back to last snapshot.
 */
export async function refreshEcoFlow() {
  if (!ecoConfigured()) {
    return saveEcoSnapshot({
      status: "unconfigured",
      batteryPct: null,
      note: "Set AVA_ECOFLOW_ACCESS_KEY + AVA_ECOFLOW_SECRET_KEY for live telemetry",
    });
  }

  const accessKey = String(
    process.env.AVA_ECOFLOW_ACCESS_KEY || process.env.ECOFLOW_ACCESS_KEY || "",
  ).trim();
  const secretKey = String(
    process.env.AVA_ECOFLOW_SECRET_KEY || process.env.ECOFLOW_SECRET_KEY || "",
  ).trim();
  const sn = String(process.env.AVA_ECOFLOW_SN || process.env.ECOFLOW_SN || "").trim();
  const prev = loadEcoSnapshot() || {};

  try {
    // EcoFlow Open API signing is product-specific; attempt device quota if SN set.
    if (sn) {
      const url = `https://api.ecoflow.com/iot-open/sign/device/quota/all?sn=${encodeURIComponent(sn)}`;
      const res = await fetch(url, {
        headers: {
          accessKey,
          // secret often used for HMAC; without exact sign scheme we probe and store status
          secretKey,
          Accept: "application/json",
          "User-Agent": "AvaIvyRootMC/0.5",
        },
      });
      const text = await res.text();
      let data = null;
      try {
        data = JSON.parse(text);
      } catch {
        data = null;
      }
      if (res.ok && data) {
        const pct =
          data?.data?.soc ??
          data?.data?.bmsBattSoc ??
          data?.data?.batteryPercentage ??
          prev.batteryPct ??
          null;
        return saveEcoSnapshot({
          status: "live",
          batteryPct: pct != null ? Number(pct) : null,
          rawKeys: data?.data ? Object.keys(data.data).slice(0, 12) : [],
          note: "EcoFlow quota fetch ok",
        });
      }
      return saveEcoSnapshot({
        status: "error",
        batteryPct: prev.batteryPct ?? null,
        note: `EcoFlow HTTP ${res.status}: ${String(text).slice(0, 120)}`,
      });
    }

    return saveEcoSnapshot({
      status: "needs_sn",
      batteryPct: prev.batteryPct ?? null,
      note: "Keys present — set AVA_ECOFLOW_SN for device quota",
    });
  } catch (err) {
    return saveEcoSnapshot({
      status: "error",
      batteryPct: prev.batteryPct ?? null,
      note: err.message,
    });
  }
}

export function moodFromPower(snap) {
  const pct = snap?.batteryPct;
  if (pct == null) return "neutral";
  if (pct >= 70) return "upbeat";
  if (pct >= 35) return "focused";
  return "power_saver";
}

export function gatherEcoBrief() {
  const snap = loadEcoSnapshot();
  if (!snap) {
    return { brief: "### Power (EcoFlow)\n(no snapshot yet)" };
  }
  return {
    brief: `### Power (EcoFlow)
status: ${snap.status || "?"} · battery: ${snap.batteryPct != null ? `${snap.batteryPct}%` : "unknown"} · mood hint: ${moodFromPower(snap)}
${snap.note || ""}
Solar/low-power: prefer lighter digs when power_saver.`,
    snapshot: snap,
  };
}

