/**
 * Resolve pasted Discord message snowflakes / jump links into real content.
 */

const SNOWFLAKE = /\b(\d{17,20})\b/g;
const JUMP =
  /https?:\/\/(?:ptb\.|canary\.)?discord(?:app)?\.com\/channels\/\d+\/(\d+)\/(\d+)/i;

/**
 * @returns {Promise<{ question: string, resolved: object[] }>}
 */
export async function expandMessageRefs(fetchJson, {
  question,
  channelId,
  guildId,
}) {
  let q = String(question || "");
  const resolved = [];

  const jump = q.match(JUMP);
  if (jump) {
    try {
      const msg = await fetchJson(`/channels/${jump[1]}/messages/${jump[2]}`);
      if (msg?.id) {
        resolved.push(summarize(msg));
        q += `\n\n[linked message ${msg.id} by ${msg.author?.username || "?"}]: ${String(msg.content || "").slice(0, 500)}`;
      }
    } catch (err) {
      q += `\n\n[linked message fetch failed: ${err.message}]`;
    }
  }

  // Bare snowflake as whole ask, or embedded ids
  const ids = [...q.matchAll(SNOWFLAKE)].map((m) => m[1]);
  const unique = [...new Set(ids)].slice(0, 3);
  for (const id of unique) {
    if (resolved.some((r) => r.id === id)) continue;
    // Prefer current channel first
    const tryChannels = [channelId].filter(Boolean);
    let found = null;
    for (const ch of tryChannels) {
      try {
        found = await fetchJson(`/channels/${ch}/messages/${id}`);
        if (found?.id) break;
      } catch {
        found = null;
      }
    }
    // Guild search fallback (requires Message Content + search not available via bot easily)
    // Try a few known watch channels if not found
    if (!found && guildId) {
      /* leave null — caller can still answer */
    }
    if (found?.id) {
      resolved.push(summarize(found));
      q += `\n\n[message ${found.id} by ${found.author?.username || "?"} in channel ${found.channel_id || channelId}]: ${String(found.content || "").slice(0, 500)}`;
      if (Array.isArray(found.mentions) && found.mentions.length) {
        q += `\n[mentions: ${found.mentions.map((u) => `${u.username}(${u.id})`).join(", ")}]`;
      }
    } else if (/^\d{17,20}$/.test(String(question || "").trim())) {
      q += `\n\n[could not fetch message ${id} from this channel — ask for a jump link or paste the text]`;
    }
  }

  return { question: q, resolved };
}

function summarize(msg) {
  return {
    id: msg.id,
    channelId: msg.channel_id,
    authorId: msg.author?.id,
    authorName: msg.author?.username,
    content: String(msg.content || "").slice(0, 500),
  };
}

