import fs from "node:fs";
import path from "node:path";
import { loadEnv, botToken, DISCORD_API } from "../src/config.mjs";
import { authHeaders, downloadAttachment } from "../src/discordApi.mjs";
import { uploadsDir, imagesForCursor } from "../src/uploads.mjs";
import { writeHeartbeat, pushStatusEvent, setHushed } from "../src/store.mjs";

const CHANNEL = "1516108586307158088";
const MSG_ID = "1532911963456278738";
const TOWNY = "15bbc057-4f8b-4761-abdb-7b7e4d9c7512";
const CLAIMS = "4963895e-0964-48b8-81b7-1f40a966e8be";

const env = await loadEnv();
const token = botToken(env);
const headers = authHeaders(token);

setHushed(false, "unfreeze");
writeHeartbeat({ digging: false, live: true, mode: "hot", hushed: false });

async function getReserve(sid, label) {
  const url = `https://rootmc.net/api/rootmc/treasury/${encodeURIComponent(sid)}/reserve`;
  const res = await fetch(url, { cache: "no-store" });
  const j = await res.json();
  const p = j.payable_supply || {};
  return {
    label,
    sid,
    synced_at: j.synced_at,
    balance: j.balance,
    vault: j.vault_balance,
    position: p.reserve_position_g ?? p.reserve_managed_g,
    page: label === "Claims" ? "https://rootmc.net/economy/claims/" : "https://rootmc.net/economy/towny/",
  };
}

const msgRes = await fetch(`${DISCORD_API}/channels/${CHANNEL}/messages/${MSG_ID}`, {
  headers,
});
const msg = await msgRes.json();
if (!msgRes.ok) throw new Error(`fetch msg ${msgRes.status}`);

const att = (msg.attachments || [])[0];
let visionNote = "(no attachment still on message)";
if (att?.url) {
  const dest = path.join(uploadsDir(), `unfreeze_${att.id}_${att.filename || "image.png"}`);
  await downloadAttachment(att.url, dest);
  const imgs = imagesForCursor([
    {
      full: dest,
      mime: att.content_type || "image/png",
      isImage: true,
      bytes: fs.statSync(dest).size,
      relative: dest,
    },
  ]);
  visionNote = imgs.length
    ? "I re-pulled your screenshot from Discord."
    : "Had the screenshot URL but couldn't load pixels this pass.";
}

const [towny, claims] = await Promise.all([
  getReserve(TOWNY, "Towny"),
  getReserve(CLAIMS, "Claims"),
]);

const fmt = (n) =>
  Number.isFinite(Number(n))
    ? `${Number(n).toLocaleString("en-US", { maximumFractionDigits: 1 })} G`
    : "—";

const content = [
  "sorry — I froze.",
  "",
  "I said **working**, then a restart mid-dig killed the image job before I answered. That's on me.",
  "",
  visionNote,
  "",
  "Re-hit the **live** treasury APIs the economy pages use (not a stale chat memory):",
  "",
  `**Towny** (\`${towny.sid.slice(0, 8)}…\`) · synced ${towny.synced_at || "?"} · ${towny.page}`,
  `· ledger balance **${fmt(towny.balance)}** · vault **${fmt(towny.vault)}** · reserve position **${fmt(towny.position)}**`,
  "",
  `**Claims** (\`${claims.sid.slice(0, 8)}…\`) · synced ${claims.synced_at || "?"} · ${claims.page}`,
  `· ledger balance **${fmt(claims.balance)}** · vault **${fmt(claims.vault)}** · reserve position **${fmt(claims.position)}**`,
  "",
  "Heads-up: both treasury endpoints are currently returning the same `server_id: rootmc` payload (same numbers). If your screenshot shows a different host split, the cloud sync/Hyperdrive side may be merging hosts — I can dig that next instead of guessing.",
  "",
  "I'm up again. Digs now time out instead of hanging forever.",
].join("\n");

const post = await fetch(`${DISCORD_API}/channels/${CHANNEL}/messages`, {
  method: "POST",
  headers,
  body: JSON.stringify({
    content: content.slice(0, 2000),
    message_reference: { message_id: MSG_ID },
    allowed_mentions: { parse: [] },
  }),
});
const text = await post.text();
if (!post.ok) throw new Error(`${post.status} ${text.slice(0, 300)}`);
const out = JSON.parse(text);
pushStatusEvent("unfreeze reply · reserves");
writeHeartbeat({ digging: false });
console.log("posted", out.id);

