const jobs = listJobs(100);
console.log('=== JOBS', jobs.length, '===');
for (const j of jobs) console.log(j.status, j.id, (j.title||'').slice(0,80));
console.log('=== SLOTS ===', cursorSlots());
console.log('=== WATCH ===', [...watch].join(','));

const chRes = await fetch(DISCORD_API+'/guilds/'+ROOTMC_GUILD_ID+'/channels', { headers });
const channels = await chRes.json();
const text = (channels||[]).filter(c => c.type===0 || c.type===5).sort((a,b)=>(a.position||0)-(b.position||0));
console.log('=== CHANNELS', text.length, '===');
for (const c of text) console.log((watch.has(String(c.id))?'*':' '), c.id, c.name);

// scan each channel for Ava mentions / unanswered threads
const openAsks = [];
for (const c of text) {
  const res = await fetch(DISCORD_API+'/channels/'+c.id+'/messages?limit=40', { headers });
  if (!res.ok) { console.log('FAIL', c.name, res.status); continue; }
  const msgs = await res.json();
  // walk newest->oldest, find human pings to Ava not followed by Ava reply
  for (let i=0;i<msgs.length;i++) {
    const m = msgs[i];
    if (m.author?.bot) continue;
    const content = String(m.content||'');
    const hit = content.includes('<@'+botId+'>') || content.includes('<@!'+botId+'>') || /\\bava(\\s+ivy)?\\b/i.test(content);
    if (!hit && !(m.referenced_message?.author?.id===botId)) continue;
    // was there an Ava reply after this message (newer = lower index)?
    let answered = false;
    for (let j=0;j<i;j++) {
      const n = msgs[j];
      if (String(n.author?.id)===String(botId) && (n.message_reference?.message_id===m.id || BigInt(n.id)>BigInt(m.id))) {
        // any Ava message newer than ask in channel counts soft; prefer ref
        if (n.message_reference?.message_id===m.id || (Date.parse(n.timestamp)-Date.parse(m.timestamp)<10*60*1000 && j<i)) {
          answered = true; break;
        }
      }
    }
    // stricter: Ava reply referencing this msg OR Ava message within 15min after
    answered = false;
    for (let j=0;j<i;j++) {
      const n = msgs[j];
      if (String(n.author?.id)!==String(botId)) continue;
      if (n.message_reference?.message_id===m.id) { answered=true; break; }
      const dt = Date.parse(n.timestamp)-Date.parse(m.timestamp);
      if (dt>=0 && dt < 20*60*1000) { answered=true; break; }
    }
    const atts = (m.attachments||[]).length;
    openAsks.push({ channel:c.name, channelId:c.id, id:m.id, who:m.author.username, answered, atts, content: content.slice(0,160).replace(/\\n/g,' / '), ts:m.timestamp });
  }
}
console.log('=== AVA-RELATED HUMAN MSGS', openAsks.length, '===');
const unanswered = openAsks.filter(a=>!a.answered);
console.log('UNANSWERED', unanswered.length);
for (const a of unanswered) console.log('!', a.channel, a.who, a.id, a.content);
fs.writeFileSync(path.join(storePaths().dir,'catchup-scan.json'), JSON.stringify({ jobs, unanswered, openAsks: openAsks.slice(0,80), scannedAt: Date.now() }, null, 2));
console.log('wrote catchup-scan.json');
"

