export function isHushCommand(content) {
  const q = String(content || "")
    .toLowerCase()
    .replace(new RegExp(`<@!?${AVA_BOT_APP_ID}>`, "g"), " ava ")
    .replace(/<@!?\d+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  // Must clearly tell Ava to stop — not "don't stop Ava" / "emergency stop" chatter
  if (/\b(don'?t|do\s+not|never|please\s+don'?t)\b.{0,40}\b(stop|hush|quiet|sleep|emergency\s+stop)\b/.test(q)) {
    return false;
  }
  if (/\bemergency\s+stop\b/.test(q)) return false;

  // "stop asking/telling/doing X" = cease an action, not hush Ava.
  // Allow only Ava-directed "stop talking/posting/spamming/replying".
  if (/\bstop\s+[a-z]+ing\b/.test(q)) {
    const avaCeaseNoise =
      /^(hey\s+|hi\s+|ok\s+|okay\s+)?ava[,:]?\s+stop\s+(talking|posting|spamming|replying)\b/.test(q) ||
      /^stop\s+(talking|posting|spamming|replying)[,.]?\s+ava\b/.test(q);
    if (avaCeaseNoise) return true;
    return false;
  }

  // Real hush: "ava stop", "stop ava", "hush ava", etc. (not "ava stop asking…")
  return (
    /^(hey\s+|hi\s+|ok\s+|okay\s+)?ava[,:]?\s+(stop|hush|quiet|sleep|go\s+offline|shut\s+up)\b/.test(
      q,
    ) ||
    /^(stop|hush|quiet|sleep|go\s+offline|shut\s+up)[,.]?\s+ava\b/.test(q)
  );
}

