    }
    try {
        Object service = economy.getClass().getMethod("doubleEnderChest").invoke(economy);
        if (service instanceof RootMcEnderChestService ec) {
            return ec;
        }
        return null;
    } catch (ReflectiveOperationException ex) {
        return null;
    }
}

