package com.rootrecord.minecraft.rootappreciation.voteshard;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.List;

/**
 * Vote Shard / Block / Geode — physical governance weight (mimics Appreciation tokens).
 * Only holdings in the double /ec count toward Council power.
 */
public final class VoteShardItem {

    public enum Form {
        SHARD(Material.AMETHYST_SHARD, "Vote Shard", "vote_shard"),
        BLOCK(Material.AMETHYST_BLOCK, "Vote Shard Block", "vote_shard_block"),
        GEODE(Material.BUDDING_AMETHYST, "Vote Geode", "vote_geode");

        final Material material;
        final String display;
        final String keyName;

        Form(Material material, String display, String keyName) {
            this.material = material;
            this.display = display;
            this.keyName = keyName;
        }
    }

    private static final LegacyComponentSerializer LEGACY = LegacyComponentSerializer.legacyAmpersand();

    private final NamespacedKey formKey;
    private final NamespacedKey weightKey;

    public VoteShardItem(JavaPlugin plugin) {
        this.formKey = new NamespacedKey(plugin, "vote_shard_form");
        this.weightKey = new NamespacedKey(plugin, "vote_shard_weight");
    }

    public boolean isVoteShardItem(ItemStack stack) {
        if (stack == null || !stack.hasItemMeta()) {
            return false;
        }
        return stack.getItemMeta().getPersistentDataContainer().has(formKey, PersistentDataType.STRING);
    }

    public Form formOf(ItemStack stack) {
        if (!isVoteShardItem(stack)) {
            return null;
        }
        String raw = stack.getItemMeta().getPersistentDataContainer().get(formKey, PersistentDataType.STRING);
        if (raw == null) {
            return null;
        }
        for (Form f : Form.values()) {
            if (f.keyName.equalsIgnoreCase(raw)) {
                return f;
            }
        }
        return null;
    }

    /** Per-item certificate weight (Block/Geode) or 1 for unit shards. */
    public int unitWeight(ItemStack stack) {
        if (!isVoteShardItem(stack)) {
            return 0;
        }
        Integer w = stack.getItemMeta().getPersistentDataContainer().get(weightKey, PersistentDataType.INTEGER);
        return w == null || w < 1 ? 1 : w;
    }

    /** Total voting power of this stack (amount × unit weight). */
    public int stackPower(ItemStack stack) {
        if (!isVoteShardItem(stack)) {
            return 0;
        }
        return Math.max(0, stack.getAmount()) * unitWeight(stack);
    }

    public ItemStack create(Form form, int unitWeight, int amount) {
        Form f = form == null ? Form.SHARD : form;
        int weight = Math.max(1, unitWeight);
        int amt = Math.max(1, Math.min(64, amount));
        // Blocks/Geodes are certificates — keep amount 1 with weight on PDC.
        if (f != Form.SHARD) {
            amt = 1;
        }
        ItemStack stack = new ItemStack(f.material, amt);
        applyMeta(stack, f, weight);
        return stack;
    }

    /** Maximally condensed form for an exact weight (Geode preferred). */
    public ItemStack condensed(int totalWeight) {
        int w = Math.max(1, totalWeight);
        if (w >= 64) {
            return create(Form.GEODE, w, 1);
        }
        if (w >= 4) {
            return create(Form.BLOCK, w, 1);
        }
        return create(Form.SHARD, 1, w);
    }

    public void refreshLore(ItemStack stack) {
        if (!isVoteShardItem(stack)) {
            return;
        }
        Form form = formOf(stack);
        if (form == null) {
            return;
        }
        applyMeta(stack, form, unitWeight(stack));
    }

    private void applyMeta(ItemStack stack, Form form, int unitWeight) {
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) {
            return;
        }
        int power = Math.max(1, stack.getAmount()) * Math.max(1, unitWeight);
        meta.displayName(Component.text(form.display, NamedTextColor.LIGHT_PURPLE)
                .decoration(TextDecoration.ITALIC, false));
        List<Component> lore = new ArrayList<>();
        lore.add(Component.text("Voting power: " + power, NamedTextColor.AQUA)
                .decoration(TextDecoration.ITALIC, false));
        lore.add(LEGACY.deserialize("&7Only counts in &f/ec &7(double ender chest).")
                .decoration(TextDecoration.ITALIC, false));
        lore.add(LEGACY.deserialize("&8Merge in /ec: shards → block → geode")
                .decoration(TextDecoration.ITALIC, false));
        meta.lore(lore);
        meta.getPersistentDataContainer().set(formKey, PersistentDataType.STRING, form.keyName);
        meta.getPersistentDataContainer().set(weightKey, PersistentDataType.INTEGER, Math.max(1, unitWeight));
        stack.setItemMeta(meta);
    }

    public int sumPower(ItemStack[] contents) {
        int total = 0;
        if (contents == null) {
            return 0;
        }
        for (ItemStack stack : contents) {
            total += stackPower(stack);
        }
        return total;
    }

    /** Remove all vote-shard forms from contents; return total power removed. Mutates array. */
    public int clearAllForms(ItemStack[] contents) {
        int power = 0;
        if (contents == null) {
            return 0;
        }
        for (int i = 0; i < contents.length; i++) {
            if (isVoteShardItem(contents[i])) {
                power += stackPower(contents[i]);
                contents[i] = null;
            }
        }
        return power;
    }
}

package com.rootrecord.minecraft.rootappreciation.voteshard;

import com.rootrecord.minecraft.common.RootMcEnderChestResolver;
import com.rootrecord.minecraft.common.RootMcEnderChestService;
import com.rootrecord.minecraft.common.config.RootMcDatabaseConfig;
import com.rootrecord.minecraft.common.mysql.MysqlConnections;
import com.rootrecord.minecraft.rootappreciation.AppreciationStore;
import com.rootrecord.minecraft.rootappreciation.RootAppreciationPlugin;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.UUID;
import java.util.logging.Level;

/** Mint, backfill, merge Vote Shards into double /ec (per-server). */
public final class VoteShardService {

    private final RootAppreciationPlugin plugin;
    private final VoteShardItem items;
    private final String issuedTable;
    private final String pendingTable;
    private final String votesTable;
    private volatile boolean ready;

    public VoteShardService(RootAppreciationPlugin plugin, VoteShardItem items, String tablePrefix) {
        this.plugin = plugin;
        this.items = items;
        String prefix = tablePrefix == null || tablePrefix.isBlank() ? "root_" : tablePrefix;
        this.issuedTable = prefix + "vote_shard_issued";
        this.pendingTable = prefix + "vote_shard_pending";
        this.votesTable = prefix + "rewards_votes";
    }

    public VoteShardItem items() {
        return items;
    }

    public void initSchema() {
        RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
        if (db == null || !db.isConfigured()) {
            ready = false;
            return;
        }
        try (Connection c = MysqlConnections.open(db); Statement st = c.createStatement()) {
            st.executeUpdate("""
                    CREATE TABLE IF NOT EXISTS %s (
                      player_uuid CHAR(36) NOT NULL PRIMARY KEY,
                      weight_issued INT NOT NULL DEFAULT 0,
                      updated_at DATETIME NOT NULL
                    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
                    """.formatted(issuedTable));
            st.executeUpdate("""
                    CREATE TABLE IF NOT EXISTS %s (
                      id BIGINT AUTO_INCREMENT PRIMARY KEY,
                      player_uuid CHAR(36) NOT NULL,
                      weight INT NOT NULL,
                      idempotency_key VARCHAR(96) NOT NULL,
                      created_at DATETIME NOT NULL,
                      delivered_at DATETIME NULL,
                      UNIQUE KEY uq_vs_pending (idempotency_key),
                      INDEX idx_vs_pending_player (player_uuid, delivered_at)
                    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
                    """.formatted(pendingTable));
            ready = true;
        } catch (Exception ex) {
            ready = false;
            plugin.getLogger().log(Level.SEVERE, "Vote shard schema failed: " + ex.getMessage());
        }
    }

    /** Soft-SPI: +1 weight per listing vote row (idempotent). */
    public boolean grantVoteShard(UUID uuid, String username, long voteRowId) {
        if (uuid == null || voteRowId <= 0 || !ready) {
            return false;
        }
        String key = "vote-shard:" + voteRowId;
        if (!enqueuePending(uuid, 1, key)) {
            deliverPending(uuid);
            return false;
        }
        bumpIssued(uuid, 1);
        Player online = Bukkit.getPlayer(uuid);
        if (online != null && online.isOnline()) {
            Bukkit.getScheduler().runTask(plugin, () -> {
                deliverPending(online.getUniqueId());
                ensureExactOwed(online);
            });
        }
        return true;
    }

    /**
     * Ensure EC holds condensed shards for exact owed = max(0, votes - already_in_ec) relative to
     * issued ledger: mint any shortfall of issued vs vote count into EC as condensed form.
     */
    public void ensureExactOwed(Player player) {
        if (player == null || !ready) {
            return;
        }
        UUID uuid = player.getUniqueId();
        int votes = countVotes(uuid);
        int issued = weightIssued(uuid);
        if (votes > issued) {
            int need = votes - issued;
            bumpIssued(uuid, need);
            enqueuePending(uuid, need, "backfill:" + uuid + ":" + votes);
        }
        deliverPending(uuid);
        // After pending delivery, collapse EC holdings to one condensed stack of total EC power
        // only when we just deposited and player has loose shards — optional auto-condense on backfill:
        condenseEnderIfNeeded(player);
    }

    public int ecPower(Player player) {
        RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
        ItemStack[] contents;
        if (ec != null) {
            contents = ec.contents(player.getUniqueId());
        } else {
            contents = player.getEnderChest().getContents();
        }
        return items.sumPower(contents);
    }

    public int mergeEnder(Player player) {
        if (player == null) {
            return 0;
        }
        RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
        ItemStack[] contents;
        Inventory inv = null;
        if (ec != null) {
            inv = ec.inventory(player);
            contents = inv.getContents().clone();
        } else {
            contents = player.getEnderChest().getContents().clone();
        }
        int power = items.clearAllForms(contents);
        if (power <= 0) {
            player.sendMessage(plugin.colorize("&eNo Vote Shards in &f/ec &eto merge."));
            return 0;
        }
        // Two-step: if only shards (no block/geode were present — we cleared all), produce block if <64 else geode.
        // Detect prior highest form from power alone after clear — use two-step by checking what was there:
        // Simpler: always produce next tier from total — if power was all unit shards, make BLOCK; if already had block+, make GEODE.
        // Caller passes priorMaxForm via scan before clear:
        ItemStack out = items.create(VoteShardItem.Form.GEODE, power, 1);
        // Prefer block when merging pure shards under 64 for mid-tier trade:
        // Re-read: two-step locked — first merge shards→block, second block→geode.
        // We need form before clear:
        return mergeEnderTwoStep(player);
    }

    public int mergeEnderTwoStep(Player player) {
        RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
        ItemStack[] contents;
        if (ec != null) {
            contents = ec.inventory(player).getContents().clone();
        } else {
            contents = player.getEnderChest().getContents().clone();
        }
        boolean hadBlockOrGeode = false;
        boolean hadShard = false;
        for (ItemStack stack : contents) {
            VoteShardItem.Form form = items.formOf(stack);
            if (form == VoteShardItem.Form.SHARD) {
                hadShard = true;
            } else if (form == VoteShardItem.Form.BLOCK || form == VoteShardItem.Form.GEODE) {
                hadBlockOrGeode = true;
            }
        }
        int power = items.clearAllForms(contents);
        if (power <= 0) {
            player.sendMessage(plugin.colorize("&eNo Vote Shards in &f/ec &eto merge."));
            return 0;
        }
        VoteShardItem.Form outForm;
        if (hadBlockOrGeode) {
            outForm = VoteShardItem.Form.GEODE;
        } else if (hadShard) {
            outForm = VoteShardItem.Form.BLOCK;
        } else {
            outForm = VoteShardItem.Form.GEODE;
        }
        ItemStack out = items.create(outForm, power, 1);
        // Place into first empty slot
        boolean placed = false;
        for (int i = 0; i < contents.length; i++) {
            if (contents[i] == null) {
                contents[i] = out;
                placed = true;
                break;
            }
        }
        if (!placed) {
            contents[0] = out;
        }
        if (ec != null) {
            Inventory inv = ec.inventory(player);
            inv.setContents(contents);
            ec.save(player);
        } else {
            player.getEnderChest().setContents(contents);
        }
        player.sendMessage(plugin.colorize(
                "&aMerged Vote Shards in /ec → &f" + outForm.display + " &7(power " + power + ")"));
        return power;
    }

    private void condenseEnderIfNeeded(Player player) {
        // On backfill deposit we add condensed already; skip auto full merge.
    }

    private void deliverPending(UUID uuid) {
        Player player = Bukkit.getPlayer(uuid);
        if (player == null || !player.isOnline() || !ready) {
            return;
        }
        RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
        if (db == null) {
            return;
        }
        try (Connection c = MysqlConnections.open(db);
             PreparedStatement ps = c.prepareStatement(
                     "SELECT id, weight FROM " + pendingTable
                             + " WHERE player_uuid = ? AND delivered_at IS NULL ORDER BY id ASC")) {
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    long id = rs.getLong(1);
                    int weight = rs.getInt(2);
                    ItemStack stack = items.condensed(weight);
                    RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
                    ItemStack[] left;
                    if (ec != null) {
                        left = ec.addItems(player, stack);
                    } else {
                        left = player.getEnderChest().addItem(stack).values().toArray(new ItemStack[0]);
                    }
                    if (left.length > 0) {
                        // EC full — leave pending
                        player.sendMessage(plugin.colorize(
                                "&e/ec full — Vote Shards pending. Clear space and rejoin."));
                        break;
                    }
                    try (PreparedStatement up = c.prepareStatement(
                            "UPDATE " + pendingTable + " SET delivered_at = UTC_TIMESTAMP() WHERE id = ?")) {
                        up.setLong(1, id);
                        up.executeUpdate();
                    }
                }
            }
        } catch (Exception ex) {
            plugin.getLogger().log(Level.WARNING, "Vote shard deliver: " + ex.getMessage());
        }
    }

    private boolean enqueuePending(UUID uuid, int weight, String key) {
        if (!ready || weight <= 0) {
            return false;
        }
        RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
        if (db == null) {
            return false;
        }
        try (Connection c = MysqlConnections.open(db);
             PreparedStatement ps = c.prepareStatement(
                     "INSERT IGNORE INTO " + pendingTable
                             + " (player_uuid, weight, idempotency_key, created_at) VALUES (?, ?, ?, UTC_TIMESTAMP())")) {
            ps.setString(1, uuid.toString());
            ps.setInt(2, weight);
            ps.setString(3, key);
            return ps.executeUpdate() > 0;
        } catch (Exception ex) {
            plugin.getLogger().log(Level.WARNING, "Vote shard enqueue: " + ex.getMessage());
            return false;
        }
    }

    private void bumpIssued(UUID uuid, int delta) {
        if (!ready || delta <= 0) {
            return;
        }
        RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
        if (db == null) {
            return;
        }
        try (Connection c = MysqlConnections.open(db);
             PreparedStatement ps = c.prepareStatement(
                     "INSERT INTO " + issuedTable + " (player_uuid, weight_issued, updated_at) VALUES (?, ?, UTC_TIMESTAMP())"
                             + " ON DUPLICATE KEY UPDATE weight_issued = weight_issued + ?, updated_at = UTC_TIMESTAMP()")) {
            ps.setString(1, uuid.toString());
            ps.setInt(2, delta);
            ps.setInt(3, delta);
            ps.executeUpdate();
        } catch (Exception ex) {
            plugin.getLogger().log(Level.WARNING, "Vote shard issued bump: " + ex.getMessage());
        }
    }

    private int weightIssued(UUID uuid) {
        if (!ready) {
            return 0;
        }
        RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
        if (db == null) {
            return 0;
        }
        try (Connection c = MysqlConnections.open(db);
             PreparedStatement ps = c.prepareStatement(
                     "SELECT weight_issued FROM " + issuedTable + " WHERE player_uuid = ? LIMIT 1")) {
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getInt(1) : 0;
            }
        } catch (Exception ex) {
            return 0;
        }
    }

    private int countVotes(UUID uuid) {
        // Reuse appreciation store votes when possible
        int n = 0;
        for (AppreciationStore.VoteRow ignored : plugin.store().listVotesForPlayer(uuid)) {
            n++;
        }
        return n;
    }
}

