        if (ec == null) {
            for (var p : player.getServer().getPluginManager().getPlugins()) {
                ec = RootMcEnderChestResolver.resolve(p);
                if (ec != null) {
                    break;
                }
            }
        }
        if (ec != null) {
            return ec.contents(player.getUniqueId());
        }
        return player.getEnderChest().getContents();
    }
}

