        return new MergeResult(true, MergeStatus.OK, slotByBond.size(), merged.principal());
    } catch (Exception ex) {
        plugin.getLogger().log(Level.WARNING, "Bond merge failed: " + ex.getMessage(), ex);
        return MergeResult.FAILED;
    }
}

