public void syncCloudWeights(java.util.Collection<UUID> uuids) {
    if (uuids == null || uuids.isEmpty()) {
        return;
    }
    plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
        try {
            var rootmc = Bukkit.getPluginManager().getPlugin("RootMC");
            if (rootmc == null || !rootmc.isEnabled()) {
                return;
            }
            Object bridge = rootmc.getClass().getMethod("rootStatBridge").invoke(rootmc);
            if (bridge == null) {
                try {
                    bridge = rootmc; // RootMcPlugin implements RootStatBridge
                } catch (Exception ignored) {
                }
            }
            Object cloud = null;
            try {
                cloud = rootmc.getClass().getMethod("cloud").invoke(rootmc);
            } catch (Exception ignored) {
            }
            if (cloud == null && bridge != null) {
                cloud = bridge.getClass().getMethod("cloud").invoke(bridge);
            }
            if (cloud == null) {
                return;
            }
            Class<?> rowClass = null;
            for (Class<?> nested : cloud.getClass().getDeclaredClasses()) {
                if (nested.getSimpleName().equals("EcVoteShardRow")) {
                    rowClass = nested;
                    break;
                }
            }
            if (rowClass == null) {
                return;
            }
            var ctor = rowClass.getConstructor(String.class, int.class);
            java.util.List<Object> rows = new java.util.ArrayList<>();
            for (UUID id : uuids) {
                if (id == null) {
                    continue;
                }
                rows.add(ctor.newInstance(id.toString(), ecPower(id)));
            }
            if (rows.isEmpty()) {
                return;
