            cloud.getClass().getMethod("syncEcVoteShards", java.util.List.class).invoke(cloud, rows);
        } catch (Exception ex) {
            plugin.getLogger().log(Level.FINE, "EC vote shard cloud sync: " + ex.getMessage());
        }
    });
}

