public int ecPower(UUID uuid) {
    if (uuid == null) {
        return 0;
    }
    RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
    ItemStack[] contents;
    if (ec != null) {
        contents = ec.contents(uuid);
    } else {
        Player online = Bukkit.getPlayer(uuid);
        contents = online != null ? online.getEnderChest().getContents() : new ItemStack[0];
    }
    return items.sumPower(contents);
}

public int mergeEnder(Player player) {
    return mergeEnderTwoStep(player);
}

public int mergeEnderTwoStep(Player player) {
    RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
    ItemStack[] contents;
    if (ec != null) {
        contents = ec.inventory(player).getContents().clone();
    } else {
        contents = player.getEnderChest().getContents().clone();
    }
    boolean hadBlockOrGeode = false;
    boolean hadShard = false;
    for (ItemStack stack : contents) {
        VoteShardItem.Form form = items.formOf(stack);
        if (form == VoteShardItem.Form.SHARD) {
            hadShard = true;
        } else if (form == VoteShardItem.Form.BLOCK || form == VoteShardItem.Form.GEODE) {
            hadBlockOrGeode = true;
        }
    }
    int power = items.clearAllForms(contents);
    if (power <= 0) {
        player.sendMessage(plugin.colorize("&eNo Vote Shards in &f/ec &eto merge."));
        return 0;
    }
    VoteShardItem.Form outForm;
    if (hadBlockOrGeode) {
        outForm = VoteShardItem.Form.GEODE;
    } else if (hadShard) {
        outForm = VoteShardItem.Form.BLOCK;
    } else {
        outForm = VoteShardItem.Form.GEODE;
    }
    ItemStack out = items.create(outForm, power, 1);
    // Place into first empty slot
    boolean placed = false;
    for (int i = 0; i < contents.length; i++) {
        if (contents[i] == null) {
            contents[i] = out;
            placed = true;
            break;
        }
    }
    if (!placed) {
        contents[0] = out;
    }
    if (ec != null) {
        Inventory inv = ec.inventory(player);
        inv.setContents(contents);
        ec.save(player);
    } else {
        player.getEnderChest().setContents(contents);
    }
    player.sendMessage(plugin.colorize(
            "&aMerged Vote Shards in /ec → &f" + outForm.display() + " &7(power " + power + ")"));
    syncCloudWeights(List.of(player.getUniqueId()));
    return power;
}

private void deliverPending(UUID uuid) {
    Player player = Bukkit.getPlayer(uuid);
    if (player == null || !player.isOnline() || !ready) {
        return;
    }
    RootMcDatabaseConfig.DatabaseSettings db = RootMcDatabaseConfig.resolve(plugin, plugin.yaml().config());
    if (db == null) {
        return;
    }
    try (Connection c = MysqlConnections.open(db);
         PreparedStatement ps = c.prepareStatement(
                 "SELECT id, weight FROM " + pendingTable
                         + " WHERE player_uuid = ? AND delivered_at IS NULL ORDER BY id ASC")) {
        ps.setString(1, uuid.toString());
        try (ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                long id = rs.getLong(1);
                int weight = rs.getInt(2);
                ItemStack stack = items.condensed(weight);
                RootMcEnderChestService ec = RootMcEnderChestResolver.resolve(plugin);
                ItemStack[] left;
                if (ec != null) {
                    left = ec.addItems(player, stack);
                } else {
                    left = player.getEnderChest().addItem(stack).values().toArray(new ItemStack[0]);
                }
                if (left.length > 0) {
                    // EC full — leave pending
                    player.sendMessage(plugin.colorize(
                            "&e/ec full — Vote Shards pending. Clear space and rejoin."));
                    break;
                }
                try (PreparedStatement up = c.prepareStatement(
                        "UPDATE " + pendingTable + " SET delivered_at = UTC_TIMESTAMP() WHERE id = ?")) {
                    up.setLong(1, id);
                    up.executeUpdate();
                }
            }
        }
    } catch (Exception ex) {
        plugin.getLogger().log(Level.WARNING, "Vote shard deliver: " + ex.getMessage());
    }
    syncCloudWeights(List.of(uuid));
}

