public GovernanceVotingPower fetchGovernanceVotingPower(String uuid) throws IOException, InterruptedException {
    String json = get("/api/realm/minecraft/governance/voting-power?uuid=" + uuid);
    boolean ok = json.contains("\"ok\":true");
    boolean eligible = json.contains("\"eligible\":true");
    double sharePercent = parseJsonNumber(json, "share_percent");
    String summary = extractString(json, "summary");
    String votingChannelUrl = extractString(json, "voting_channel_url");
    String constitutionUrl = extractString(json, "constitution_url");
    String councilUrl = extractString(json, "council_url");
    int openPolls = (int) Math.round(parseJsonNumber(json, "open_polls_count"));
    double rewardG = parseJsonNumber(json, "proposal_vote_reward_g");
    if (rewardG < 0.01) {
        rewardG = 3;
    }
    return new GovernanceVotingPower(
            ok, eligible, sharePercent, summary, votingChannelUrl, constitutionUrl, councilUrl, openPolls, rewardG);
}

/** Public open Council polls (no server auth required). */
public OpenGovernancePolls fetchOpenGovernancePolls() throws IOException, InterruptedException {
    String json = getPublic("/api/governance/polls");
    if (!json.contains("\"ok\":true")) {
        return OpenGovernancePolls.empty();
    }
    List<OpenPoll> polls = new ArrayList<>();
    int idx = 0;
    while (true) {
        int start = json.indexOf("\"id\"", idx);
        if (start < 0) {
            break;
        }
        String slice = json.substring(start, Math.min(json.length(), start + 500));
        String id = extractString(slice, "id");
        String title = extractString(slice, "title");
        String url = extractString(slice, "url");
        if (id != null && !id.isBlank() && title != null) {
            if (url == null || url.isBlank()) {
                url = "https://rootmc.net/governance/vote/?id=" + id;
            }
            polls.add(new OpenPoll(id, title, url));
        }
        idx = start + 4;
        if (polls.size() >= 20) {
            break;
        }
    }
    return new OpenGovernancePolls(polls);
}

