/** Public open Council polls (no server auth required). */
public OpenGovernancePolls fetchOpenGovernancePolls() throws IOException, InterruptedException {
    String json = publicGet("/api/governance/polls");
    if (!json.contains("\"ok\":true")) {
        return OpenGovernancePolls.empty();
    }
    int pollsKey = json.indexOf("\"polls\"");
    if (pollsKey < 0) {
        return OpenGovernancePolls.empty();
    }
    String region = json.substring(pollsKey);
    List<OpenPoll> polls = new ArrayList<>();
    int idx = 0;
    while (idx < region.length() && polls.size() < 20) {
        int titlePos = region.indexOf("\"title\"", idx);
        if (titlePos < 0) {
            break;
        }
        int windowStart = Math.max(0, titlePos - 120);
        int windowEnd = Math.min(region.length(), titlePos + 400);
        String slice = region.substring(windowStart, windowEnd);
        String id = extractString(slice, "id");
        String title = extractString(slice, "title");
        String url = extractString(slice, "url");
        if (id != null && !id.isBlank() && title != null && !title.isBlank()) {
            if (url == null || url.isBlank()) {
                url = "https://rootmc.net/governance/vote/?id=" + id;
            }
            polls.add(new OpenPoll(id, title, url));
        }
        idx = titlePos + 7;
    }
    return new OpenGovernancePolls(polls);
}

