/** In-game /proposal — Ava formalizes after Paper charged 64 G to reserve. */
public IngameProposalResult submitIngameProposal(String uuid, String username, String message)
        throws IOException, InterruptedException {
    String body = "{\"uuid\":\"" + escapeJson(uuid) + "\",\"username\":\"" + escapeJson(username)
            + "\",\"message\":\"" + escapeJson(message) + "\"}";
    String json = post("/api/rootmc/ingame-proposal", body);
