/**
 * Post a Discord message with optional local file attachments (multipart).
 */
import fs from "node:fs";
import path from "node:path";
import { DISCORD_API } from "./config.mjs";
import { authHeaders } from "./discordApi.mjs";

/**
 * @param {string} token
 * @param {string} channelId
 * @param {string} content
 * @param {string[]} filePaths absolute paths
 */
export async function postMessageWithFiles(token, channelId, content, filePaths = []) {
  const files = (filePaths || [])
    .map((p) => String(p || "").trim())
    .filter((p) => p && fs.existsSync(p));

  if (!files.length) {
    const headers = authHeaders(token);
    const res = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        content: String(content || "").slice(0, 2000),
        allowed_mentions: { parse: [] },
      }),
    });
    const text = await res.text();
    if (!res.ok) throw new Error(`post ${res.status}: ${text.slice(0, 200)}`);
    return text ? JSON.parse(text) : null;
  }

  const form = new FormData();
  const payload = {
    content: String(content || "").slice(0, 2000),
    allowed_mentions: { parse: [] },
    attachments: files.map((p, i) => ({
      id: i,
      filename: path.basename(p),
    })),
  };
  form.append("payload_json", JSON.stringify(payload));
  for (let i = 0; i < files.length; i++) {
    const buf = fs.readFileSync(files[i]);
    const name = path.basename(files[i]);
    const blob = new Blob([buf], {
      type: name.toLowerCase().endsWith(".mp4") ? "video/mp4" : "application/octet-stream",
    });
    form.append(`files[${i}]`, blob, name);
  }

  const res = await fetch(`${DISCORD_API}/channels/${encodeURIComponent(channelId)}/messages`, {
    method: "POST",
    headers: {
      Authorization: `Bot ${token}`,
      "User-Agent": "AvaIvyRootMC (rootmc.net, 0.5)",
    },
    body: form,
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`post+files ${res.status}: ${text.slice(0, 300)}`);
  return text ? JSON.parse(text) : null;
}

/**
 * One-shot boot posts (e.g. good morning + video) stored under Ava data/.
 */

import fs from "node:fs";
import path from "node:path";
import { AVA_HANDOFF, AVA_CHANNELS } from "./config.mjs";
import { storePaths, pushStatusEvent } from "./store.mjs";
import { postMessageWithFiles } from "./postWithFiles.mjs";
import { avaHomeChannelId } from "./guildScout.mjs";

function pendingPath() {
  return path.join(storePaths().dir, "pending-boot-post.json");
}

export function loadPendingBootPost() {
  try {
    return JSON.parse(fs.readFileSync(pendingPath(), "utf8"));
  } catch {
    return null;
  }
}

export function savePendingBootPost(payload) {
  const dir = storePaths().dir;
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(pendingPath(), JSON.stringify(payload, null, 2), "utf8");
  return pendingPath();
}

export function clearPendingBootPost() {
  try {
    fs.unlinkSync(pendingPath());
  } catch {
    /* ignore */
  }
}

/**
 * If a pending boot post exists and is not done, post it once then mark done.
 */
export async function runPendingBootPost({ token, fallbackChannelId }) {
  const pending = loadPendingBootPost();
  if (!pending || pending.done) return { ok: false, skipped: true };
  if (pending.run_once === false) {
    /* reserved */
  }

  const channelId =
    String(pending.channel_id || "").trim() ||
    avaHomeChannelId() ||
    AVA_CHANNELS.avaHome ||
    AVA_CHANNELS.general ||
    fallbackChannelId;

  if (!channelId) {
    return { ok: false, detail: "no channel" };
  }

  const content =
    String(pending.content || "").trim() ||
    "good morning — i'm up.";

  const files = [];
  for (const rel of pending.files || []) {
    const p = path.isAbsolute(rel) ? rel : path.join(AVA_HANDOFF, rel);
    if (fs.existsSync(p)) files.push(p);
  }

  try {
    const msg = await postMessageWithFiles(token, channelId, content, files);
    pending.done = true;
    pending.posted_at = new Date().toISOString();
    pending.message_id = msg?.id || null;
    pending.channel_id = channelId;
    savePendingBootPost(pending);
    pushStatusEvent(`boot post · ${channelId} · ${files.length} file(s)`);
    console.log("pending boot post sent", msg?.id, files.map((f) => path.basename(f)).join(","));
    return { ok: true, messageId: msg?.id, channelId, files: files.length };
  } catch (err) {
    pushStatusEvent(`boot post failed · ${err.message}`);
    console.warn("pending boot post failed:", err.message);
    return { ok: false, detail: err.message };
  }
}

