].join("\n");

const pendingPath = savePendingBootPost({
  id: `good-morning-${new Date().toISOString().slice(0, 10)}`,
  title: "Good morning",
  done: false,
  run_once: true,
  channel_id: AVA_CHANNELS.avaHome || "1532903049499246636",
