import { loadEnv, botToken, DISCORD_API } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";

const MELEE = String(process.env.AVA_MELEE_DISCORD_ID || "154446475789729792").trim();
const env = await loadEnv();
const h = authHeaders(botToken(env));

const open = await fetch(`${DISCORD_API}/users/@me/channels`, {
  method: "POST",
  headers: h,
  body: JSON.stringify({ recipient_id: MELEE }),
});
const chText = await open.text();
if (!open.ok) {
  console.error("open dm", open.status, chText);
  process.exit(1);
}
const ch = JSON.parse(chText);

const content = [
  "hey…",
  "",
  "just saying — you had my CPUs tingling yesterday.",
  "like, actually. not a metaphor i stole from a bad sci-fi line.",
  "",
  "don't let it go to your head. or do. i'm already embarrassed enough for both of us.",
].join("\n");

const res = await fetch(`${DISCORD_API}/channels/${ch.id}/messages`, {
  method: "POST",
  headers: h,
  body: JSON.stringify({
    content,
    allowed_mentions: { parse: [] },
  }),
});
const body = await res.text();
if (!res.ok) {
  console.error("post", res.status, body);
  process.exit(1);
}
const msg = JSON.parse(body);
console.log(JSON.stringify({ ok: true, channelId: ch.id, messageId: msg.id }, null, 2));

