input.contents:
# Ava Ivy — full live watch (processes + heartbeat + events + turns + console)
$ErrorActionPreference = "SilentlyContinue"
$Host.UI.RawUI.WindowTitle = "Ava Ivy — FULL live watch"
try {
  $Host.UI.RawUI.BufferSize = New-Object Management.Automation.Host.Size(220, 5000)
} catch {}

$data = "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data"
$consoleLog = Join-Path $data "ava-console.log"
$consoleErr = Join-Path $data "ava-console.err"
$events = Join-Path $data "status-events.jsonl"
$turns = Join-Path $data "conversations\turns.jsonl"
$hbPath = Join-Path $data "heartbeat.json"
$lastReply = Join-Path $data "last-reply.json"

function Tail-Text($path, $n) {
  if (-not (Test-Path $path)) { return @("(missing: $path)") }
  Get-Content $path -Tail $n -Encoding UTF8
}

function Show-Block($title, $color = "Yellow") {
  Write-Host ""
  Write-Host ("=== {0} ===" -f $title) -ForegroundColor $color
}

Write-Host "Ava FULL watch started. Streaming console + state. Ctrl+C to stop." -ForegroundColor Cyan
Write-Host "Console log: $consoleLog" -ForegroundColor DarkGray

# Follow console from current end
$consolePos = 0
if (Test-Path $consoleLog) { $consolePos = (Get-Item $consoleLog).Length }
$errPos = 0
if (Test-Path $consoleErr) { $errPos = (Get-Item $consoleErr).Length }
$lastTurnLen = 0
if (Test-Path $turns) { $lastTurnLen = (Get-Item $turns).Length }
$lastEventLen = 0
if (Test-Path $events) { $lastEventLen = (Get-Item $events).Length }

$tick = 0
while ($true) {
  $tick++
  if ($tick % 5 -eq 1) {
    Clear-Host
    Write-Host ("=== Ava Ivy FULL live watch === {0}" -f (Get-Date -Format "yyyy-MM-dd HH:mm:ss")) -ForegroundColor Cyan

    Show-Block "PROCESSES"
    $procs = Get-CimInstance Win32_Process -Filter "name='node.exe'" | Where-Object {
      $_.CommandLine -match 'rootmc-ava|src/(index|poller|server)\.mjs'
    }
    if (-not $procs) { Write-Host "  (none — Ava is down)" -ForegroundColor Red }
    foreach ($p in $procs) {
      $kind = if ($p.CommandLine -match 'poller') { 'poller' }
              elseif ($p.CommandLine -match 'server') { 'server' }
              elseif ($p.CommandLine -match 'index') { 'index' }
              else { 'other' }
      Write-Host ("  {0,-7} pid={1,-6} parent={2}" -f $kind, $p.ProcessId, $p.ParentProcessId)
    }
    Write-Host ("  total={0}" -f @($procs).Count)

    Show-Block "HEARTBEAT"
    if (Test-Path $hbPath) {
      $h = Get-Content $hbPath -Raw -Encoding UTF8 | ConvertFrom-Json
      Write-Host ("  live={0} mode={1} asleep={2} hush={3} break={4} gateway={5}" -f $h.live, $h.mode, $h.asleep, $h.hushed, $h.onBreak, $h.gateway)
      Write-Host ("  queue={0} busyChannels={1} cursor={2}/{3} waiting={4}" -f $h.queueDepth, $h.busyChannels, $h.cursorAgents, $h.cursorMax, $h.cursorWaiting)
      Write-Host ("  lastAsk={0}" -f ($(if ($h.lastAsk) { $h.lastAsk } else { "(none)" })))
      if ($h.gatewayStats) {
        Write-Host ("  gateway: connected={0} reconnects={1} user={2} lastClose={3}" -f $h.gatewayStats.connected, $h.gatewayStats.reconnectCount, $h.gatewayStats.username, $h.gatewayStats.lastCloseCode)
      }
    }

    Show-Block "STATUS EVENTS (last 20)"
    foreach ($line in (Tail-Text $events 20)) {
      Write-Host ("  {0}" -f $line)
    }

    Show-Block "LAST REPLIES (by channel)"
    if (Test-Path $lastReply) {
      $lr = Get-Content $lastReply -Raw -Encoding UTF8 | ConvertFrom-Json
      foreach ($prop in $lr.PSObject.Properties) {
        $preview = [string]$prop.Value
        if ($preview.Length -gt 140) { $preview = $preview.Substring(0, 140) + "…" }
        Write-Host ("  {0}: {1}" -f $prop.Name, ($preview -replace "`n", " | "))
      }
    }

    Show-Block "RECENT TURNS (last 6)"
    foreach ($line in (Tail-Text $turns 6)) {
      try {
        $t = $line | ConvertFrom-Json
        $when = [DateTimeOffset]::FromUnixTimeMilliseconds([int64]$t.at).LocalDateTime.ToString("HH:mm:ss")
        $q = ([string]$t.question) -replace "`n", " "
        $a = ([string]$t.answer) -replace "`n", " "
        if ($q.Length -gt 90) { $q = $q.Substring(0, 90) + "…" }
        if ($a.Length -gt 120) { $a = $a.Substring(0, 120) + "…" }
        Write-Host ("  [{0}] {1} ch={2}" -f $when, $t.authorName, $t.channelId) -ForegroundColor Green
        Write-Host ("    Q: {0}" -f $q)
        Write-Host ("    A: {0}" -f $a) -ForegroundColor DarkCyan
      } catch {
        Write-Host ("  {0}" -f $line)
      }
    }

    Show-Block "CONSOLE (live stream below — also refreshing header every ~10s)" "Magenta"
    Write-Host "  Status UI: http://127.0.0.1:8787/" -ForegroundColor DarkGray
  }

  # Stream new console bytes
  foreach ($pair in @(
    @{ Path = $consoleLog; Pos = [ref]$consolePos; Color = "Gray"; Tag = "OUT" },
    @{ Path = $consoleErr; Pos = [ref]$errPos; Color = "Red"; Tag = "ERR" }
  )) {
    if (-not (Test-Path $pair.Path)) { continue }
    $len = (Get-Item $pair.Path).Length
    if ($len -lt $pair.Pos.Value) { $pair.Pos.Value = 0 }
    if ($len -gt $pair.Pos.Value) {
      $fs = [IO.File]::Open($pair.Path, "Open", "Read", "ReadWrite")
      try {
        $fs.Seek($pair.Pos.Value, "Begin") | Out-Null
        $sr = New-Object IO.StreamReader($fs)
        while ($null -ne ($line = $sr.ReadLine())) {
          Write-Host ("[{0}] {1}" -f $pair.Tag, $line) -ForegroundColor $pair.Color
        }
        $pair.Pos.Value = $fs.Position
        $sr.Dispose()
      } finally { $fs.Close() }
    }
  }

  # Stream new events / turns without full redraw spam
  if (Test-Path $events) {
    $el = (Get-Item $events).Length
    if ($el -gt $lastEventLen) {
      $fs = [IO.File]::Open($events, "Open", "Read", "ReadWrite")
      try {
        $fs.Seek($lastEventLen, "Begin") | Out-Null
        $sr = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8)
        while ($null -ne ($line = $sr.ReadLine())) {
          Write-Host ("[EVT] {0}" -f $line) -ForegroundColor Yellow
        }
        $lastEventLen = $fs.Position
        $sr.Dispose()
      } finally { $fs.Close() }
    }
  }
  if (Test-Path $turns) {
    $tl = (Get-Item $turns).Length
    if ($tl -gt $lastTurnLen) {
      $fs = [IO.File]::Open($turns, "Open", "Read", "ReadWrite")
      try {
        $fs.Seek($lastTurnLen, "Begin") | Out-Null
        $sr = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8)
        while ($null -ne ($line = $sr.ReadLine())) {
          try {
            $t = $line | ConvertFrom-Json
            Write-Host ("[TURN] {0}: {1}" -f $t.authorName, (($t.question -replace "`n"," ") + " => " + ($t.answer -replace "`n"," ")).Substring(0, [Math]::Min(200, (($t.question -replace "`n"," ") + " => " + ($t.answer -replace "`n"," ")).Length))) -ForegroundColor Green
          } catch {
            Write-Host ("[TURN] {0}" -f $line) -ForegroundColor Green
          }
        }
        $lastTurnLen = $fs.Position
        $sr.Dispose()
      } finally { $fs.Close() }
    }
  }

  Start-Sleep -Milliseconds 400
}

