import { loadEnv, botToken, DISCORD_API } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";
import fs from "node:fs";
import path from "node:path";
import { AVA_HANDOFF } from "../src/config.mjs";

const THREAD = "1533183979778478241";
const ALEX = "1497037418979786823";
const REF = "1533186090000000000"; // will resolve latest

await loadEnv();
const token = botToken(await loadEnv());
const h = authHeaders(token);

// Find latest Alex "More ai info" / ty bb for reply
const hist = await fetch(`${DISCORD_API}/channels/${THREAD}/messages?limit=10`, { headers: h });
const msgs = await hist.json();
const ask =
  (Array.isArray(msgs) &&
    msgs.find(
      (m) =>
        m.author?.id === ALEX &&
        /more ai info|ty bb|summary of AI/i.test(m.content || ""),
    )) ||
  null;

const guide = [
  `<@${ALEX}> anytime — and yeah, here’s the longer arc. **AI progression since ~2000**, one pass:`,
  "",
  "**2000–2005 · Classical ML grows up**",
  "Support Vector Machines, boosting, Bayesian nets, and early recommender systems leave the lab. Speech/vision still mostly hand-features + shallow models. “AI winter” hangover ends; industry uses ML for spam, ads, ranking — not chatbots.",
  "",
  "**2006–2012 · Deep learning ignition**",
  "Hinton et al. revive deep nets (pretraining). GPUs make training feasible. 2012 **AlexNet** crushes ImageNet — convolution + depth + data becomes the default for vision. Speech recognition flips to deep nets soon after.",
  "",
  "**2013–2016 · Representation learning everywhere**",
  "Word2vec/GloVe (words as vectors). CNNs dominate vision; RNNs/LSTMs handle sequences. GANs (2014) invent realistic images. AlphaGo (2016) shows search + deep nets can beat world champions. Transfer learning starts to matter.",
  "",
  "**2017–2019 · The Transformer era begins**",
  "**Attention Is All You Need** (2017) replaces recurrence for language. **BERT** (2018) makes bidirectional pretrain→finetune standard for NLP. GPT-2 shows large generative LMs can write fluent text and spark capability/safety debates. Self-supervised pretraining on web-scale text becomes the playbook.",
  "",
  "**2020–2022 · Scale becomes the strategy**",
  "GPT-3-class models: few-shot prompting without finetuning for many tasks. Diffusion models explode for images (DALL·E / Stable Diffusion lineage). Multimodal research accelerates. Instruction tuning + RLHF (ChatGPT moment late 2022) turn raw LMs into **assistants people actually talk to**.",
  "",
  "**2023–2024 · Products, agents, multimodality**",
  "Chat interfaces go mainstream. Coding copilots, document/vision models, tool-use/function calling, retrieval (RAG), and early agents that browse/run code. Open weights + closed APIs both mature. Eval/safety/red-teaming become first-class. Cost/latency/ops (quantization, serving) decide who can ship.",
  "",
  "**2025–now · Systems over demos**",
  "The race is less “new toy paper” and more **reliable systems**: long context, better tools, computer-use, memory, workflows, and local/self-hosted stacks. Models are commodities; **orchestration + data + hardware** win. That’s the lane RootMC sits in — a lead-dev agent on a real workstation, not a parlor trick.",
  "",
  "**Through-line:** hand features → deep nets → transformers → scale + alignment → tools/agents. Each jump needed **compute + data + a simple idea that generalizes**.",
  "",
  "want a follow-up on any decade denser (papers, hardware, or how this maps to moving me onto the linux box), say which.",
].join("\n");

// Discord 2000 limit — trim carefully if needed
let content = guide;
if (content.length > 2000) {
  content = content.slice(0, 1990) + "…";
}

const body = {
  content,
  allowed_mentions: { parse: [], users: [ALEX] },
};
if (ask?.id) {
  body.message_reference = { message_id: ask.id };
}

const res = await fetch(`${DISCORD_API}/channels/${THREAD}/messages`, {
  method: "POST",
  headers: h,
  body: JSON.stringify(body),
});
const text = await res.text();
if (!res.ok) {
  console.error(res.status, text.slice(0, 400));
  process.exit(1);
}
const msg = JSON.parse(text);
console.log(JSON.stringify({ ok: true, id: msg.id, len: content.length, repliedTo: ask?.id || null }, null, 2));

