        name: "ava-ivy",
        type: 0,
        topic,
        parent_id: parent_id || undefined,
        reason: "Ava Ivy first-join home channel",
      }),
    });
    return {
      id: created.id,
      name: created.name || "ava-ivy",
      created: true,
      topic,
    };
  } catch (err) {
    return {
      id: null,
      name: "ava-ivy",
      created: false,
      error: String(err?.message || err),
    };
  }
