function looksLikeAnnouncement(text) {
  const t = String(text || "").trim();
  // Operator ship notes / status dumps that mention Ava but aren't asking her
  if (/^\*?Ava\b.*—/i.test(t)) return true;
  if (/^\*?(Incident report|Ava roadmap|Ava Discord|Ava dig core|Proposal:)/i.test(t))
    return true;
  if (/^\*[^*\n]+\*$/.test(t.split("\n")[0] || "") && !/\?\s*$/.test(t))
    return true;
  return false;
}

function discordAddressesAva(m, avaId) {
  if (!m || m.author?.bot || m.author?.id === avaId) return false;
  const c = String(m.content || "");
  if (
    m.mentions?.some((u) => u.id === avaId) ||
    c.includes(`<@${avaId}>`) ||
    c.includes(`<@!${avaId}>`)
  ) {
    return true;
  }
  if (looksLikeAnnouncement(c)) return false;
  // Soft address: name + ask energy, and message not ancient (>3d snowflake ~)
  try {
    const ageMs = Date.now() - Number((BigInt(m.id) >> 22n) + 1420070400000n);
    if (ageMs > 3 * 24 * 60 * 60 * 1000) return false;
  } catch {
    /* ignore */
  }
  return (
    /\bava(\s+ivy)?\b/i.test(c) &&
    /\?|please|can you|could you|would you|help|look|confirm|hey ava|yo ava|ping/i.test(
      c,
    )
  );
}

function slackAddressesAva(text, botId) {
  const t = String(text || "");
  if (t.includes(`<@${botId}>`)) return true;
  if (looksLikeAnnouncement(t)) return false;
  return (
    /(^|\W)ava(\s+ivy)?(\W|$)/i.test(t) &&
    /\?/.test(t) &&
    /\b(please|can you|could you|would you|are you|cool with|confirm|help)\b/i.test(
      t,
    )
  );
}

